window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0128", [{"word":"independence movement","ipa_uk":"/ˌɪndɪˈpendəns ˈmuːvmənt/","ipa_us":"/ˌɪndɪˈpendəns ˈmuːvmənt/","definition_zh":"独立运动；（尤指）争取民族独立、结束外部统治的有组织政治运动","definition_en":"an organized political campaign that seeks to end outside rule and win self-government for a people or territory","core_image":"广场上同一块布缝成的旗被举过头顶，人群从街角不断汇入，远处旧政权的徽记正被取下","scene":"广场上的人群举着同一块布缝成的旗，从清晨站到黄昏，要求由自己决定本地事务。The independence movement spread from the capital to every provincial town.","sceneCN":"这里 independence movement 指「争取政治独立的群众运动」（第 1 个义项：以结束外部统治、取得自主政权为目标的有组织行动）；句意为这场独立运动从首都蔓延到每一个省城。图中可辨识物件：手缝旗帜、密集人群、被取下的旧徽记、临时演讲台。","pos":[{"tag":"n.","zh":"独立运动（可数；指具体一场运动时用单数或复数 independence movements）"}],"collocations":[{"phrase":"national independence movement","zh":"民族独立运动"},{"phrase":"peaceful independence movement","zh":"和平独立运动"},{"phrase":"independence movement leader","zh":"独立运动领袖"},{"phrase":"mass independence movement","zh":"群众性独立运动"},{"phrase":"independence movement against colonial rule","zh":"反抗殖民统治的独立运动"},{"phrase":"join the independence movement","zh":"加入独立运动"}],"forms":[{"label":"复数","form":"independence movements"},{"label":"核心名词（独立）","form":"independence"},{"label":"核心形容词（独立的）","form":"independent"},{"label":"副词（独立地）","form":"independently"},{"label":"核心名词（运动）","form":"movement"},{"label":"近义短语（解放运动）","form":"liberation movement"}],"derivatives":[{"word":"independence","pos":"n.","zh":"独立；自主（由 independent 加 -ence 构成，指不依附的状态）"},{"word":"independent","pos":"adj./n.","zh":"独立的；独立的报业或政治人士（由 in- 加 dependent 构成）"},{"word":"independently","pos":"adv.","zh":"独立地；不受他人支配地（independent 加 -ly）"},{"word":"dependence","pos":"n.","zh":"依赖；依附（由 depend 加 -ence，指悬挂于他者的状态）"},{"word":"dependent","pos":"adj./n.","zh":"依赖的；受抚养者（拉丁 dependere 的现在分词形）"},{"word":"movement","pos":"n.","zh":"运动；移动（由 move 加 -ment，指移动这一动作或一股持续的行动）"},{"word":"move","pos":"v./n.","zh":"移动；推动；一步棋（拉丁 movere 经古法语进入英语）"}],"senses":[{"no":"01","title":"An organized campaign for political sovereignty","titleCN":"为取得政治主权而组织起来的群众运动","definition":"a sustained public campaign whose aim is to end foreign or colonial rule and place political power in local hands","definitionCN":"持续进行的公众行动，目标是结束外国或殖民统治，把政治权力交回本地人手中","example":"The independence movement spread from the capital to every provincial town.","exampleCN":"这场独立运动从首都蔓延到每一个省城。","why":"Independence is in- 'not' plus dependere 'to hang from', so the campaign is literally a push to stop hanging from another power.","whyCN":"independence 是 in-「不」加 dependere「悬挂于」，因此这场运动字面上就是「不再挂在另一个强权之下」的努力。"},{"no":"02","title":"The decolonization wave of the mid-twentieth century","titleCN":"二十世纪中叶的去殖民化浪潮","definition":"the series of campaigns through which colonies in Asia and Africa won formal statehood in the decades after the Second World War","definitionCN":"第二次世界大战后数十年间，亚洲与非洲各殖民地通过一系列运动取得正式国家地位的过程","example":"Historians treat the independence movement as part of a wider decolonization wave.","exampleCN":"历史学家把这场独立运动视为更广泛的去殖民化浪潮的一部分。","why":"When many campaigns succeed within a few decades, the phrase shifts from one campaign to the whole historical wave they form.","whyCN":"当许多运动在几十年内相继成功，这个短语就从单场运动转指它们共同构成的历史浪潮。"},{"no":"03","title":"A separatist campaign inside an existing state","titleCN":"现有国家内部要求分离的运动","definition":"a movement in which a region or ethnic group seeks to leave an existing state and govern itself","definitionCN":"某一地区或族群谋求脱离现有国家并自行治理的运动","example":"The regional independence movement demanded a referendum on leaving the union.","exampleCN":"该地区的独立运动要求就脱离联邦举行公投。","why":"The core idea of not being attached to a larger power applies equally when the larger power is a partner state rather than an empire.","whyCN":"「不隶属于更大权力」这一核心意思，同样适用于更大的一方是联邦伙伴而非帝国的情况。"},{"no":"04","title":"An armed struggle for independence","titleCN":"以武装斗争方式争取独立","definition":"the military wing of such a campaign, waged by guerrilla or regular forces against the ruling power","definitionCN":"此类运动中以游击或正规武装对抗统治方的军事部分","example":"The independence movement took up arms after the petitions were ignored.","exampleCN":"请愿被置之不理后，这场独立运动拿起了武器。","why":"The same goal can be pursued by petitions or by rifles, so the phrase covers the armed phase without changing its aim.","whyCN":"同一目标可以用请愿也可以用枪械去追求，因此这个短语也涵盖武装阶段，而目标不变。"},{"no":"05","title":"A civil or nonviolent independence campaign","titleCN":"以公民不服从与非暴力方式开展的独立运动","definition":"a campaign that uses strikes, boycotts, marches and legal challenge rather than weapons","definitionCN":"以罢工、抵制、游行与法律诉讼而非武器为手段的运动","example":"A civil independence movement can bring down a colonial administration without a single shot.","exampleCN":"一场公民独立运动可以不放一枪就拖垮殖民当局。","why":"Because the phrase names the goal rather than the method, it accommodates campaigns that deliberately refuse violence.","whyCN":"因为这个短语命名的是目标而非手段，所以也能容纳刻意拒绝暴力的运动。"},{"no":"06","title":"A cultural assertion of separate identity","titleCN":"以文化与语言主张独立身份的运动","definition":"a campaign that presses for a separate language, literature and historical narrative as the groundwork of political independence","definitionCN":"以争取独立语言、文学与历史叙事为政治独立铺路的文化运动","example":"The independence movement began in poetry journals long before it reached the assembly.","exampleCN":"这场独立运动早在进入议会之前，就已经在诗歌刊物中开始了。","why":"Political separation needs a people who see themselves as distinct, so the phrase extends to the cultural work that builds that distinctness.","whyCN":"政治分离需要一个自视独特的民族，因此这个短语延伸到构建这种独特性的文化工作。"},{"no":"07","title":"A period label used by historians","titleCN":"历史学中作为时期标签的用法","definition":"a conventional name for a phase of a country's history, as in a chapter heading or museum display","definitionCN":"对一个国家某一历史阶段的惯用称呼，常见于章节标题或博物馆展陈","example":"The gallery devotes its second room to the independence movement.","exampleCN":"该展馆把第二个展厅专门留给独立运动时期。","why":"Once a campaign is over, the phrase stops naming actors and starts naming a stretch of time, the way a war becomes a period.","whyCN":"运动结束之后，这个短语不再指行动者，而开始指一段时间，就像一场战争变成一个时期。"},{"no":"08","title":"Any drive for institutional autonomy","titleCN":"引申为任何机构争取自主权的行动","definition":"a figurative use for an internal push by a department, school or agency to free itself from central control","definitionCN":"比喻用法，指部门、学校或机构内部为摆脱中央控制而发起的行动","example":"The laboratory's independence movement was really a budget dispute.","exampleCN":"实验室的这场「独立运动」其实是一场预算之争。","why":"The metaphor works because the literal scene has exactly the shape of any unit trying to stop depending on a centre.","whyCN":"这个比喻成立，是因为字面场景与任何单位试图不再依赖中心的结构完全一致。"}],"etymology":{"intro":{"en":"Independence is a negative built on a Latin verb of hanging, while movement is a Latin verb of moving filtered through French. Dates are approximate.","cn":"independence 是在一个表示「悬挂」的拉丁动词上加否定构成，movement 则是表示「移动」的拉丁动词经法语而来。年代均为约数。"},"items":[{"era":"LATIN PENDERE","en":"Pendere meant 'to hang, to weigh', and its root is generally thought to be the same stock that gives pendulum and suspend.","cn":"pendere 意为「悬挂、称重」，一般认为它与 pendulum、suspend 同出一源。"},{"era":"LATIN DEPENDERE","en":"De- 'down from' plus pendere produced dependere 'to hang from, to rely on', the source of the whole dependence family.","cn":"de-「自……向下」加 pendere 构成 dependere「悬挂于、依赖」，是整族依赖类词的来源。"},{"era":"FRENCH INDEPENDANT","en":"French built independant with in- 'not', and English took the adjective in the seventeenth century before forming the noun independence with -ence.","cn":"法语用 in-「不」造出 independant，英语在十七世纪先借入形容词，再加 -ence 造出名词 independence。"},{"era":"LATIN MOVERE","en":"Movere 'to move' gave the medieval noun movimentum, which French shortened to movement and English borrowed in the fourteenth century.","cn":"movere「移动」构成中世纪名词 movimentum，法语缩为 movement，英语在十四世纪借入。"},{"era":"POLITICAL PHRASE","en":"The two words were joined as a fixed phrase in the eighteenth and nineteenth centuries, when campaigns against colonial rule needed a compact name.","cn":"这两个词在十八、十九世纪组合为固定短语，当时反抗殖民统治的运动需要一个简短的名称。"},{"era":"UNCERTAIN DATES","en":"Source uncertain (first dates only): the exact first written use of the combined phrase is not recorded, and the political sense of independence is generally dated to the eighteenth century without a precise citation.","cn":"来源不确定（仅首见年代）：这一组合短语确切的最早书证未见记载；independence 的政治义一般认为是十八世纪，但没有确切书证。"}]},"similar":{"note":{"en":"Group one holds forms built from the same hanging root that are easily mistaken for one another; group two holds movements that share the goal but not the word.","cn":"第一组是同出「悬挂」词根、容易被混用的形式；第二组是目标相近但词源不同的运动名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","tag":"same root, state not campaign","definition":"The state of not being governed by another power; it names the condition, while the phrase names the campaign that seeks it.","definitionCN":"指不受他国统治的状态；它命名的是状态，而这个短语命名的是争取该状态的行动。"},{"word":"independency","ipa":"/ˌɪndɪˈpendənsi/","tag":"rare variant","definition":"An older and now rare doublet of independence, used mainly for church self-government, not for political campaigns.","definitionCN":"independence 的旧式罕见双式词，主要用于教会自治，不用于政治运动。"},{"word":"dependence","ipa":"/dɪˈpendəns/","tag":"same root, opposite pole","definition":"The state of hanging from or relying on another; it is the exact condition the movement tries to end.","definitionCN":"指依附或依赖他者的状态，正是这场运动试图终结的状况。"},{"word":"pendant","ipa":"/ˈpendənt/","tag":"same root, concrete object","definition":"A hanging ornament, from the same pendere 'to hang'; the shared root is physical here, not political.","definitionCN":"悬挂的饰物，同出 pendere「悬挂」；此处词根是物理意义，与政治无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"liberation movement","ipa":"/ˌlɪbəˈreɪʃən ˈmuːvmənt/","tag":"freedom from control","definition":"A campaign framed around freeing people from an occupying or oppressive power rather than around founding a state.","definitionCN":"侧重把人们从占领或压迫性权力下解放出来，而不强调建立国家。"},{"word":"separatist movement","ipa":"/ˈsepərətɪst ˈmuːvmənt/","tag":"breakaway faction","definition":"A campaign to detach a region from a state; it usually carries a negative tone from the perspective of that state.","definitionCN":"试图使某地区脱离国家的运动；在该国视角下通常带贬义。"},{"word":"nationalist movement","ipa":"/ˈnæʃənəlɪst ˈmuːvmənt/","tag":"identity-driven","definition":"A campaign organized around national identity; it may or may not seek separate statehood.","definitionCN":"围绕民族身份组织的运动，未必追求单独建国。"},{"word":"autonomy movement","ipa":"/ɔːˈtɒnəmi ˈmuːvmənt/","tag":"self-rule inside a state","definition":"A campaign for local self-government within an existing state rather than for full independence.","definitionCN":"在现有国家内争取地方自治，而非争取完全独立。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'not' plus dependere 'to hang from': a people that refuses to hang from another power.","cn":"in-「不」加 dependere「悬挂于」：一个拒绝再挂在别国身上的民族。"},{"en":"The family runs depend, dependent, dependence, independent, independence, independently.","cn":"同族词依次是 depend、dependent、dependence、independent、independence、independently。"},{"en":"Movement is move plus -ment, so the phrase pairs a condition of non-attachment with a sustained push.","cn":"movement 是 move 加 -ment，因此这个短语把「不依附」的状态与持续的行动配在一起。"},{"en":"Fixed collocations mark the field: national independence movement, peaceful independence movement, independence movement leader.","cn":"固定搭配标出这一领域：民族独立运动、和平独立运动、独立运动领袖。"},{"en":"Historical shorthand: the phrase usually evokes the decolonization era rather than any single country.","cn":"历史称谓：这个短语通常让人想到去殖民化时代，而不是某一个国家。"}],"abstract":[{"en":"Picture a rope between two boats being cut, and one boat drifting free.","cn":"想象两只船之间的绳索被割断，其中一只漂离而去。"},{"en":"Picture a grown child taking the house key off the family hook and keeping it.","cn":"想象长大的孩子把家门钥匙从家庭挂钩上取下，自己留着。"},{"en":"Picture a potted plant lifted out of its pot and rooted directly in open soil.","cn":"想象一株盆栽被从盆里提起，直接扎根在露地土壤中。"}]},"examples":[{"en":"The independence movement gained strength after the tax on salt was imposed.","cn":"盐税开征之后，独立运动的力量增强了。"},{"en":"Foreign correspondents were allowed to report on the independence movement only from a distance.","cn":"外国记者只被允许远距离报道这场独立运动。"},{"en":"Scholars now study the independence movement through pamphlets, songs and court records.","cn":"学者们如今通过小册子、歌曲与法庭记录研究这场独立运动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（不）+ depend（依靠）+ movement（动起来）」——不再依靠别人，动起来要自己当家 → 独立运动","word":"independence movement"},"root":"独立：in-「不」+ dependere「悬挂、依附」，字面为「不挂在他人之下」；运动：拉丁 movere「移动」经古法语 movement 进入英语。合成后指「为摆脱外部统治而持续行动」。pendere 更深来源一般认为是同一「悬挂」词族，但无确证。","sensesIntro":{"en":"Eight senses follow one refusal: a people stops hanging from another power, and that refusal is then read as a historical wave, a breakaway region, an armed phase, a civil method, a cultural groundwork, a period label, and finally any unit seeking autonomy.","cn":"八个义项沿同一个「拒绝」展开：一个民族不再挂在另一强权之下，这一拒绝再依次被读作历史浪潮、分离地区、武装阶段、公民手段、文化铺垫、时期标签，最后是任何单位争取自主的行动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rope that once tied a community to a distant capital is cut, and the community starts steering itself.","cn":"核心意象：曾把一个社群系在远方首都的绳索被割断，这个社群开始自己掌舵。"},"chain":["REFUSE DEPENDENCE","CLAIM SOVEREIGNTY","MOBILIZE THE PUBLIC","BREAK AWAY","SUSTAIN THE STRUGGLE","WIDER AUTONOMY"],"branches":[{"senses":"S1 · S2","en":"COLLECTIVE CAMPAIGN: the same refusal scales from one territory to a whole era of decolonization.","cn":"集体行动：同一种拒绝从一个地区放大到整个去殖民化时代。"},{"senses":"S3 · S4","en":"BREAKAWAY AND FORCE: leaving a partner state and taking up arms are two intensities of the same exit.","cn":"分离与武力：脱离伙伴国家与拿起武器，是同一场退出行动的两种强度。"},{"senses":"S5 · S6","en":"SOFT MEANS: boycotts and poetry both build the confidence that self-rule requires.","cn":"柔性手段：抵制与诗歌同样在积累自治所需的自信心。"},{"senses":"S7","en":"PERIOD LABEL: once the rope is cut, the campaign turns into a dated chapter of history.","cn":"时期标签：绳索割断之后，这场行动就变成历史中一个有年代的一章。"},{"senses":"S8","en":"METAPHORICAL UNIT: any office that stops reporting to a centre repeats the literal shape in miniature.","cn":"比喻单位：任何不再向中心汇报的部门，都以缩小的规模重演了字面结构。"}]},"affixes":{"intro":{"en":"The phrase is transparent at the morpheme level: a negative prefix, a hanging root, a state suffix, a verb of motion and an action suffix.","cn":"这个短语在语素层面是透明的：一个否定前缀、一个「悬挂」词根、一个状态后缀、一个表示移动的动词，以及一个动作后缀。"},"latinIntro":{"en":"Latin pendere and movere supply the two halves, and dependere is the prefixed form that English shortened into depend.","cn":"拉丁 pendere 与 movere 提供前后两半，dependere 则是加前缀的形式，英语缩为 depend。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'not')","meaning":"not; without","meaningCN":"不；无","example":"The prefix turns a word for reliance into a word for non-reliance.","exampleCN":"这个前缀把表示依赖的词变成表示不依赖的词。"},{"word":"dependere","structure":"dependere (Latin verb, third conjugation)","meaning":"to hang from; to rely on","meaningCN":"悬挂于；依赖","example":"The image of hanging is still visible in the modern family.","exampleCN":"「悬挂」的形象在现代词族中仍然看得见。"},{"word":"-ence","structure":"-ence (Latin suffix, state or quality)","meaning":"the state of being","meaningCN":"……的状态","example":"The suffix turns the adjective into the name of a condition.","exampleCN":"这个后缀把形容词变成一种状态的名称。"},{"word":"independent","structure":"in- + dependent","meaning":"not relying on another","meaningCN":"不依赖他人的；独立的","example":"The adjective describes a person or body that steers itself.","exampleCN":"这个形容词描述自行掌舵的人或机构。"},{"word":"independence","structure":"independent + -ence","meaning":"the state of steering oneself","meaningCN":"自主的状态；独立","example":"The noun names the condition the campaign wants.","exampleCN":"这个名词命名这场运动想要的状态。"},{"word":"move","structure":"move (English verb, from Latin movere)","meaning":"to set in motion","meaningCN":"移动；推动","example":"A campaign moves people from private complaint to public demand.","exampleCN":"一场运动把人们从私下抱怨推动到公开诉求。"},{"word":"-ment","structure":"-ment (French and Latin suffix, action or result)","meaning":"an action or its result","meaningCN":"动作或其结果","example":"The suffix turns a verb of motion into a sustained public effort.","exampleCN":"这个后缀把移动动词变成持续的公众行动。"},{"word":"movement","structure":"move + -ment","meaning":"a sustained collective action","meaningCN":"持续开展的集体行动","example":"A movement lasts longer than a single protest.","exampleCN":"一场运动比一次抗议持续得更久。"}],"latinEntries":[{"word":"pendere","structure":"pendere, pependi, pensum (verb, third conjugation)","meaning":"to hang, weigh, pay out","meaningCN":"悬挂；称重；付出"},{"word":"dependere","structure":"dependere, dependi, depensum (verb, third conjugation)","meaning":"to hang from, depend on","meaningCN":"悬挂于；依赖于"},{"word":"movere","structure":"movere, movi, motum (verb, second conjugation)","meaning":"to move, set in motion","meaningCN":"移动；使动"},{"word":"motus","structure":"motus, motus (m., fourth declension)","meaning":"a movement, motion","meaningCN":"运动；移动"}]}},{"word":"nationalism","ipa_uk":"/ˈnæʃənəlɪzəm/","ipa_us":"/ˈnæʃənəlɪzəm/","definition_zh":"民族主义；国家主义；对本民族的高度忠诚与自豪；（亦含贬义）排外的民族优越感","definition_en":"a strong sense of loyalty to a nation, and the doctrine that a people with a shared identity should govern itself in its own state","core_image":"一张旧地图、一本历史教科书和一面旗被摆在同一张桌上，三条边界线在纸上重合","scene":"博物馆的展柜里，地图、教科书与旗并排放着，讲解员说这三样东西常常替一个国家讲同一个故事。Nationalism gave the young republic a common story to tell its children.","sceneCN":"这里 nationalism 指「以共同历史凝聚本国人的民族意识」（第 4 个义项：把一群人想象成一个有共同出身与命运的整体）；句意为民族主义给了这个年轻共和国一个讲给孩子们听的共同故事。图中可辨识物件：折痕地图、翻开的历史课本、叠放的旗、玻璃展柜。","pos":[{"tag":"n.","zh":"民族主义；国家主义（多作不可数；指不同形态时偶用复数 nationalisms）"}],"collocations":[{"phrase":"rising nationalism","zh":"上升的民族主义情绪"},{"phrase":"economic nationalism","zh":"经济民族主义"},{"phrase":"civic nationalism","zh":"公民民族主义"},{"phrase":"ethnic nationalism","zh":"族裔民族主义"},{"phrase":"a wave of nationalism","zh":"一股民族主义浪潮"},{"phrase":"nationalism and patriotism","zh":"民族主义与爱国主义"}],"forms":[{"label":"形容词（民族的）","form":"national"},{"label":"形容词（民族主义的）","form":"nationalistic"},{"label":"名词（民族主义者）","form":"nationalist"},{"label":"名词（民族；国家）","form":"nation"},{"label":"名词（国籍；民族性）","form":"nationality"},{"label":"复数（少见，指多种民族主义形态）","form":"nationalisms"}],"derivatives":[{"word":"nation","pos":"n.","zh":"民族；国家（拉丁 natio「出生、族群」，由「同出一源的人」引申）"},{"word":"national","pos":"adj.","zh":"国家的；民族的（nation 加 -al，指属于整个民族的）"},{"word":"nationalist","pos":"n./adj.","zh":"民族主义者；民族主义的（national 加 -ist，指信奉该主张的人）"},{"word":"nationalistic","pos":"adj.","zh":"民族主义色彩的（nationalist 加 -ic，指带有这种情绪的特征）"},{"word":"nationality","pos":"n.","zh":"国籍；民族（national 加 -ity，指属于某国的法律身份）"},{"word":"nationalize","pos":"v.","zh":"收归国有；使民族化（national 加 -ize，使转为国家所有）"},{"word":"internationalism","pos":"n.","zh":"国际主义（inter- 加 national 加 -ism，主张跨国合作）"}],"senses":[{"no":"01","title":"Pride in and loyalty to one's nation","titleCN":"对本民族的自豪与忠诚","definition":"a strong emotional attachment to one's country and its people, often felt as pride when it is praised","definitionCN":"对本国与本国人的强烈情感依附，常在国家受称赞时表现为自豪","example":"Nationalism filled the square when the team won its first international match.","exampleCN":"球队赢下第一场国际比赛时，民族自豪感充满了广场。","why":"The word starts from nation, 'a people born together', so the plain sense is simply the feeling of belonging to that group.","whyCN":"这个词从 nation「同出一源的一群人」出发，最朴素的意思就是归属于这一群体的情感。"},{"no":"02","title":"The doctrine that a nation deserves a state","titleCN":"主张每个民族都应拥有自己国家的学说","definition":"the political principle that a people sharing a language, history or origin should form its own sovereign state","definitionCN":"认为共享语言、历史或出身的一群人应组成独立主权国家的政治原则","example":"Nationalism redrew the map of Europe in the nineteenth century.","exampleCN":"民族主义在十九世纪重绘了欧洲地图。","why":"The suffix -ism turns the feeling into an organized doctrine, and the doctrine's central claim is the match between people and state.","whyCN":"后缀 -ism 把这种情感变成一套有组织的主张，而这套主张的核心就是「民族与国家应一一对应」。"},{"no":"03","title":"An ideology driving independence campaigns","titleCN":"推动独立运动的意识形态","definition":"the body of ideas that motivates a colony or subject people to seek sovereignty","definitionCN":"激励殖民地或受统治民族追求主权的一套观念","example":"Nationalism supplied the language in which the independence movement made its demands.","exampleCN":"民族主义提供了独立运动提出诉求时所用的语言。","why":"A doctrine about matching people to state naturally becomes a weapon when the two are currently mismatched by empire.","whyCN":"当帝国统治使「民族」与「国家」当前并不对应时，主张二者对应的学说自然成为武器。"},{"no":"04","title":"A shared sense of national identity","titleCN":"共同的民族身份意识","definition":"the everyday sense that strangers in the same country belong to one community with a common past","definitionCN":"同国陌生人之间那种同属一个共同体、共享同一过去的日常感受","example":"Nationalism gave the young republic a common story to tell its children.","exampleCN":"民族主义给了这个年轻共和国一个讲给孩子们听的共同故事。","why":"Before a doctrine can be argued, people must imagine themselves as one group; the word often names that imagined unity itself.","whyCN":"在一种学说被论证之前，人们必须先把自己想象成一个群体；这个词常常正是指这种被想象出来的统一。"},{"no":"05","title":"Chauvinism and exclusion of outsiders","titleCN":"民族优越感与对外来者的排斥","definition":"an aggressive form of national feeling that treats other peoples as inferior or unwelcome","definitionCN":"一种攻击性的民族情感，把其他民族视为低劣或不受欢迎","example":"The speech was criticized as nationalism dressed up as patriotism.","exampleCN":"这篇演讲被批评为披着爱国主义外衣的民族主义。","why":"Belonging to one group always draws a line against others; when that line hardens into contempt, the word takes its negative tone.","whyCN":"属于一个群体总要对外画出界线；当这条线硬化为蔑视，这个词就带上贬义。"},{"no":"06","title":"Civic nationalism based on citizenship","titleCN":"以公民身份为基础的公民民族主义","definition":"a version that defines the nation by shared citizenship, law and political values rather than by blood","definitionCN":"以共同公民身份、法律与政治价值而非血统来界定民族的版本","example":"Civic nationalism allows newcomers to become members by taking on the same political rights.","exampleCN":"公民民族主义允许新来者通过取得同样的政治权利而成为成员。","why":"The doctrine needs a definition of who counts as the people; civic nationalism chooses law and participation as the glue.","whyCN":"这一学说必须界定谁算「人民」；公民民族主义选择以法律与参与作为黏合剂。"},{"no":"07","title":"Ethnic nationalism based on descent","titleCN":"以血缘与族裔为基础的族裔民族主义","definition":"a version that defines the nation by ancestry, language and culture and treats membership as inherited","definitionCN":"以祖先、语言与文化界定民族，并把成员资格视为继承而来的版本","example":"Ethnic nationalism can leave long-settled families without papers feeling foreign.","exampleCN":"族裔民族主义会让世代居住却没有凭证的家庭觉得自己是外人。","why":"If the nation is a people born together, then birth is the obvious test; this sense follows the oldest root meaning literally.","whyCN":"如果民族是「同出一源的一群人」，那么出生就是最直接的检验；这一义项最字面地沿用了最早的词根含义。"},{"no":"08","title":"Nationalist policy in trade, culture or media","titleCN":"在贸易、文化或媒体上推行的民族主义政策","definition":"the practice of protecting domestic industry, language or media in the name of the nation","definitionCN":"以民族之名保护本国产业、语言或媒体的做法","example":"Economic nationalism raised tariffs and praised goods made at home.","exampleCN":"经济民族主义提高关税，并称赞本国制造的商品。","why":"A doctrine about the nation's interests moves easily from flags to budgets, where protecting one's own becomes policy.","whyCN":"关于民族利益的学说很容易从旗帜转到预算，在那里「保护自己人」变成具体的政策。"}],"etymology":{"intro":{"en":"Nationalism joins a Latin noun for a people born together with a Greek suffix for doctrines. Dates are approximate.","cn":"nationalism 把表示「同出一源的一群人」的拉丁名词，与表示学说的希腊后缀合在一起。年代均为约数。"},"items":[{"era":"LATIN NASCI","en":"Nasci 'to be born' is generally thought to come from an older root meaning 'to beget', the same stock behind gignere 'to produce'.","cn":"nasci「出生」一般认为来自更早的「生育」词根，与 gignere「产生」同出一源。"},{"era":"LATIN NATIO","en":"Natio first meant 'birth, origin', then 'a people of common birth', and in Roman use could mean a tribe or a group of foreigners.","cn":"natio 最初指「出生、出身」，继而指「同出一源的一群人」，在罗马用法中也可指部落或一群外邦人。"},{"era":"FRENCH NATION","en":"French nation narrowed the word toward a political people, and English borrowed it in the fourteenth century with that narrower sense.","cn":"法语 nation 把词义收窄为政治意义上的「国民」，英语在十四世纪借入时也带上了这一较窄的含义。"},{"era":"GREEK -ISMOS","en":"The suffix -ismos named a practice or a doctrine; Latin took it as -ismus and French passed -isme to English as -ism.","cn":"后缀 -ismos 表示某种实践或学说；拉丁作 -ismus，法语以 -isme 传给英语，成为 -ism。"},{"era":"ENGLISH NATIONALISM","en":"English formed national from nation, then nationalism from national, and the political sense became common in the nineteenth century alongside the new nation-states.","cn":"英语先由 nation 造出 national，再由 national 造出 nationalism；其政治义在十九世纪随新的民族国家一同普及。"},{"era":"UNCERTAIN DATES","en":"Source uncertain (first dates only): the earliest English uses are variously dated to the late eighteenth or early nineteenth century, and no single first citation is agreed.","cn":"来源不确定（仅首见年代）：英语最早的用例被分别定在十八世纪末或十九世纪初，并无一致认可的最早书证。"}]},"similar":{"note":{"en":"Group one holds words built on the same birth root that are easy to swap by mistake; group two holds feelings and doctrines that sit close in meaning.","cn":"第一组是同出「出生」词根、极易误换的词；第二组是语义相近的情感与主张。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nationalist","ipa":"/ˈnæʃənəlɪst/","tag":"person, not doctrine","definition":"A supporter of nationalism; the -ist ending names a person or a political label, while -ism names the doctrine itself.","definitionCN":"民族主义的支持者；-ist 结尾指人或政治标签，而 -ism 指学说本身。"},{"word":"nationalistic","ipa":"/ˌnæʃənəˈlɪstɪk/","tag":"adjective form","definition":"The adjective meaning 'showing nationalist feeling'; it describes a tone or policy, not the movement as a whole.","definitionCN":"意为「带有民族主义色彩的」形容词，描述语气或政策，而非整个运动。"},{"word":"nativism","ipa":"/ˈneɪtɪvɪzəm/","tag":"same birth root, different doctrine","definition":"From native, also from nasci, but it means preference for established inhabitants over immigrants, not national sovereignty.","definitionCN":"来自 native，同样出 nasci，但指偏袒本地原有居民、排斥移民，而非民族主权。"},{"word":"nationality","ipa":"/ˌnæʃəˈnæləti/","tag":"legal status","definition":"The legal bond between a person and a state; it names a status that nationalism may treat as destiny.","definitionCN":"个人与国家之间的法律纽带，指一种身份，而民族主义可能把它当成命运。"}]},{"heading":"NEAR MEANING","entries":[{"word":"patriotism","ipa":"/ˈpætriətɪzəm/","tag":"love of country","definition":"Love of and readiness to defend one's country; it lacks the doctrine that the country must match an ethnic nation.","definitionCN":"对国家的热爱与保卫意愿，不含「国家必须与某一民族对应」的学说。"},{"word":"chauvinism","ipa":"/ˈʃɔːvɪnɪzəm/","tag":"aggressive superiority","definition":"Exaggerated belief in the superiority of one's own group; nationalism becomes chauvinism when contempt for others dominates.","definitionCN":"对自己群体的夸大优越感；当对别人的蔑视占主导时，民族主义就变成沙文主义。"},{"word":"jingoism","ipa":"/ˈdʒɪŋɡəʊɪzəm/","tag":"war-minded patriotism","definition":"A belligerent, flag-waving patriotism that pushes for war; it is a mood rather than a full political doctrine.","definitionCN":"好战、挥舞旗帜并推动战争的爱国主义，是一种情绪而非完整学说。"},{"word":"self-determination","ipa":"/ˌself dɪˌtɜːmɪˈneɪʃən/","tag":"legal principle","definition":"The principle that peoples may choose their own political status; nationalism often invokes it in arguments.","definitionCN":"各民族可以自行选择政治地位的原则；民族主义常在论证中援引它。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nation plus -al plus -ism: the doctrine built around a people born together.","cn":"nation 加 -al 再加 -ism：围绕「同出一源的一群人」建立的主张。"},{"en":"Latin nasci 'be born' also yields native, nature and nativity, so the root is literally about birth.","cn":"拉丁 nasci「出生」还衍生 native、nature、nativity，这个词根字面上就是「出生」。"},{"en":"The family runs nation, national, nationalist, nationalistic, nationality, nationalize, nationalism.","cn":"同族词依次是 nation、national、nationalist、nationalistic、nationality、nationalize、nationalism。"},{"en":"Fixed collocations reveal the types: civic nationalism, ethnic nationalism, economic nationalism.","cn":"固定搭配显示不同类型：公民民族主义、族裔民族主义、经济民族主义。"},{"en":"-ism regularly names doctrines, as in realism, idealism and socialism, so nationalism is a doctrine first.","cn":"-ism 常用来命名学说，如 realism、idealism、socialism，因此 nationalism 首先是一套主张。"}],"abstract":[{"en":"Picture a family tree whose branches are redrawn as the borders of a country.","cn":"想象一棵家族树，它的枝条被重新描成一个国家的边界。"},{"en":"Picture a classroom where every child is handed the same photograph of the same ancestor.","cn":"想象一间教室，每个孩子都被发到同一张同一祖先的照片。"},{"en":"Picture a map folded inside a family album, so the paper and the memories touch.","cn":"想象一张地图被折进家族相册，纸页与记忆贴在一起。"}]},"examples":[{"en":"Nationalism in the nineteenth century turned cultural pride into demands for statehood.","cn":"十九世纪的民族主义把文化自豪转化为建国诉求。"},{"en":"The party campaigned on a mixture of economic nationalism and nostalgia.","cn":"该党以经济民族主义与怀旧情绪的混合体进行竞选。"},{"en":"Scholars distinguish civic nationalism from the ethnic variety.","cn":"学者们把公民民族主义与族裔民族主义区分开来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nation（民族）+ ism（主义）」——把民族放在第一位的主张 → 民族主义","word":"nationalism"},"root":"拉丁 natio「出生、出身、族群」出自 nasci「出生」；加 -al 成 national，再加希腊来源的 -ism 成 nationalism。词根深处与 gignere「产生」一般认为是同一词族，但印欧具体形式属重构。","sensesIntro":{"en":"Eight senses follow one bond: people born together are felt as one, and that feeling is then turned into a doctrine, a campaign, an identity, an exclusion, two ways of drawing the border, and finally a policy.","cn":"八个义项沿同一条纽带展开：同出一源的人被感受为一个整体，这种感受再变成学说、运动、身份、排斥、两种划界方式，最后变成政策。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn around a people, then copied onto a map as a border.","cn":"核心意象：先在一群人周围画一条线，再把这条线抄到地图上当作国界。"},"chain":["BORN TOGETHER","FEEL AS ONE","DESERVE A STATE","MOBILIZE","DRAW THE LINE","MAKE POLICY"],"branches":[{"senses":"S1 · S2","en":"FEELING INTO DOCTRINE: pride in the group hardens into the claim that the group must rule itself.","cn":"情感变学说：对群体的自豪硬化为「群体必须自治」的主张。"},{"senses":"S3 · S4","en":"CAMPAIGN AND IDENTITY: a movement needs both a shared story and a doctrine to act on.","cn":"运动与身份：一场运动既需要共同故事，也需要可供行动的学说。"},{"senses":"S5","en":"EXCLUSION: the same line that unites insiders marks outsiders as inferior.","cn":"排斥：团结内部人的那条线，同时把外部人标为低劣。"},{"senses":"S6 · S7","en":"TWO BORDERS: law and blood are the two rival answers to who belongs.","cn":"两种边界：法律与血统是对「谁属于这里」的两个竞争性答案。"},{"senses":"S8","en":"POLICY: once the border is settled, the doctrine moves into tariffs, schools and broadcasters.","cn":"政策：边界一旦确定，这套主张就进入关税、学校与媒体。"}]},"affixes":{"intro":{"en":"The word is built in three clear steps: a Latin noun of birth, an adjective suffix, and the doctrine suffix -ism.","cn":"这个词分三步构成：一个表示出生的拉丁名词、一个形容词后缀，以及表示学说的 -ism。"},"latinIntro":{"en":"Latin natio and nasci supply the base, while -ismus came to English through French as -ism.","cn":"拉丁 natio 与 nasci 提供词基，-ismus 则经法语以 -ism 进入英语。"},"items":[{"word":"nasci","structure":"nasci, natus sum (Latin deponent verb)","meaning":"to be born","meaningCN":"出生","example":"The verb supplies the idea of a shared origin.","exampleCN":"这个动词提供「共同出身」的意思。"},{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"birth, origin, a people","meaningCN":"出生；出身；族群","example":"The noun shifts from a single birth to a whole people.","exampleCN":"这个名词从一次出生转指整个族群。"},{"word":"-al","structure":"-al (Latin adjective suffix)","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix makes an adjective of belonging.","exampleCN":"这个后缀造出表示归属的形容词。"},{"word":"national","structure":"nation + -al","meaning":"belonging to a whole people","meaningCN":"属于整个民族的","example":"The adjective widens a local body to a national one.","exampleCN":"这个形容词把地方机构扩大到全国层面。"},{"word":"-ism","structure":"-ismus (Greek and Latin suffix, doctrine or practice)","meaning":"a doctrine or system","meaningCN":"学说或体系","example":"The suffix turns an adjective into a named creed.","exampleCN":"这个后缀把形容词变成有名目的信条。"},{"word":"nationalism","structure":"national + -ism","meaning":"the doctrine of the nation","meaningCN":"关于民族的主张","example":"The noun names a creed rather than a single feeling.","exampleCN":"这个名词命名一种信条，而非单一情感。"},{"word":"-ist","structure":"-ista (Greek and Latin suffix, one who follows)","meaning":"a person who follows a doctrine","meaningCN":"信奉某学说的人","example":"The suffix produces nationalist beside nationalism.","exampleCN":"这个后缀在 nationalism 旁造出 nationalist。"},{"word":"-ity","structure":"-itas (Latin suffix, state or quality)","meaning":"the state of being","meaningCN":"……的状态","example":"The suffix turns national into nationality.","exampleCN":"这个后缀把 national 变成 nationality。"}],"latinEntries":[{"word":"nasci","structure":"nasci, natus sum (deponent verb, third conjugation)","meaning":"to be born, to arise","meaningCN":"出生；产生"},{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"birth, origin, people, tribe","meaningCN":"出生；出身；族群；部落"},{"word":"nationalis","structure":"nationalis, nationale (adjective, third declension)","meaning":"of a people or a birth-group","meaningCN":"民族的；族群的"},{"word":"-ismus","structure":"-ismus (suffix of doctrine, from Greek -ismos)","meaning":"a practice or system of thought","meaningCN":"实践或思想体系"}]}},{"word":"nationalist","ipa_uk":"/ˈnæʃənəlɪst/","ipa_us":"/ˈnæʃənəlɪst/","definition_zh":"民族主义者；民族主义政党的成员或支持者；adj. 民族主义的","definition_en":"a person who believes that a people should rule itself in its own state, or a member of a party that campaigns for that goal","core_image":"一个人站在两级台阶之间，一手举着写有地名的木牌，另一手压着一本用本族语写成的书","scene":"老照片里，一个人站在集会人群的前排，手里的木牌写着本地的地名。The nationalist refused to sign the treaty that kept his province under foreign rule.","sceneCN":"这里 nationalist 指「主张本民族应当自治建国的人」（第 1 个义项：以民族自决为信念并为之行动的人）；句意为这名民族主义者拒绝签署那份让本省继续受外国统治的条约。图中可辨识物件：木牌、集会人群、旧照片边角、本族语书籍。","pos":[{"tag":"n.","zh":"民族主义者；民族主义政党成员（可数，复数 nationalists）"},{"tag":"adj.","zh":"民族主义的；民族主义政党的"}],"collocations":[{"phrase":"a committed nationalist","zh":"坚定的民族主义者"},{"phrase":"nationalist party","zh":"民族主义政党"},{"phrase":"nationalist sentiment","zh":"民族主义情绪"},{"phrase":"nationalist government","zh":"民族主义政府"},{"phrase":"hard-line nationalist","zh":"强硬的民族主义者"},{"phrase":"nationalist movement","zh":"民族主义运动"}],"forms":[{"label":"复数","form":"nationalists"},{"label":"形容词（民族主义的）","form":"nationalistic"},{"label":"名词（民族主义）","form":"nationalism"},{"label":"形容词（民族的）","form":"national"},{"label":"名词（民族；国家）","form":"nation"},{"label":"名词（国籍）","form":"nationality"}],"derivatives":[{"word":"nationalism","pos":"n.","zh":"民族主义（national 加 -ism，指整套学说而非个人）"},{"word":"nationalistic","pos":"adj.","zh":"民族主义色彩的（nationalist 加 -ic，指带有这种倾向）"},{"word":"national","pos":"adj.","zh":"民族的；全国的（nation 加 -al）"},{"word":"nation","pos":"n.","zh":"民族；国家（拉丁 natio，本义「同出一源的人」）"},{"word":"nationality","pos":"n.","zh":"国籍；民族（national 加 -ity，指法律身份）"},{"word":"nationalize","pos":"v.","zh":"收归国有（national 加 -ize，使归国家所有）"},{"word":"internationalist","pos":"n./adj.","zh":"国际主义者；国际主义的（inter- 加 nationalist，指主张跨国合作者）"}],"senses":[{"no":"01","title":"A believer in national self-rule","titleCN":"主张民族自决的人","definition":"a person who holds that a people with a shared identity ought to govern itself in its own state","definitionCN":"认为共享身份的一群人应当在自己的国家中自治的人","example":"The nationalist refused to sign the treaty that kept his province under foreign rule.","exampleCN":"这名民族主义者拒绝签署那份让本省继续受外国统治的条约。","why":"The -ist ending marks a person who follows the doctrine, so the noun is the human counterpart of nationalism.","whyCN":"-ist 结尾标记信奉某学说的人，因此这个名词是 nationalism 的人形对应词。"},{"no":"02","title":"A member or supporter of a nationalist party","titleCN":"民族主义政党的成员或支持者","definition":"someone enrolled in or voting for a party whose programme centres on national sovereignty","definitionCN":"加入或以选票支持一个以民族主权为核心纲领的政党的人","example":"Party workers called every nationalist in the district before the vote.","exampleCN":"投票前，党务人员给选区里每一位民族主义支持者打了电话。","why":"Once a doctrine is organized into a party, its followers are named by the same word, the way a creed becomes a label.","whyCN":"一种学说一旦组织成政党，其追随者就用同一个词来称呼，信条由此变成标签。"},{"no":"03","title":"The attributive adjective for nationalist politics","titleCN":"作定语、表示民族主义政治的形容词","definition":"used before a noun to mean 'of or run by nationalists', as in a nationalist government or a nationalist newspaper","definitionCN":"置于名词前表示「属于或由民族主义者执掌的」，如民族主义政府、民族主义报纸","example":"The nationalist government promised land reform within a year.","exampleCN":"这个民族主义政府承诺一年内完成土地改革。","why":"English lets a noun modify another noun, so the person-word doubles as an adjective without any ending change.","whyCN":"英语允许名词修饰名词，因此这个指人的词无需加后缀就可兼作形容词。"},{"no":"04","title":"A derogatory label for a chauvinist","titleCN":"带有贬义的「狂热排外者」","definition":"a person whose national pride has turned into contempt for foreigners or minorities","definitionCN":"民族自豪已转为蔑视外国人或少数群体的人","example":"Critics dismissed him as a nationalist who confused pride with prejudice.","exampleCN":"批评者把他斥为一个把自豪与偏见混为一谈的民族主义者。","why":"Any word for a strong group loyalty can be thrown as an accusation when the loyalty turns aggressive.","whyCN":"任何表示强烈群体忠诚的词，在忠诚变得有攻击性时都可以被当作指责抛出。"},{"no":"05","title":"A member of a historically named party","titleCN":"历史上特定民族主义政党的成员","definition":"a capitalized or party-specific use, as for members of named nationalist organizations in Ireland, India or elsewhere","definitionCN":"首字母大写或专指某党的用法，如爱尔兰、印度等地有名目的民族主义组织成员","example":"Her grandfather sat as a nationalist in the old assembly.","exampleCN":"她的祖父曾在旧议会中以民族主义党议员身份任职。","why":"Because the label was written on ballot papers, it became a proper political identity rather than a general description.","whyCN":"因为这个标签印在选票上，它就成了具体的政治身份，而不只是泛泛的描述。"},{"no":"06","title":"A cultural nationalist defending language and tradition","titleCN":"捍卫语言与传统的文化民族主义者","definition":"a person who works to keep a national language, literature or custom alive against outside pressure","definitionCN":"致力于在外部压力下保住民族语言、文学或习俗的人","example":"Cultural nationalists opened schools where lessons were taught in the old tongue.","exampleCN":"文化民族主义者开办学校，用古老的语言授课。","why":"The doctrine's cultural wing argues that a people is lost once its language is lost, so the same label covers language work.","whyCN":"这一学说的文化支派认为语言一失民族即失，因此同一标签也涵盖语言工作。"},{"no":"07","title":"An economic nationalist protecting domestic industry","titleCN":"主张保护本国产业的经济民族主义者","definition":"a person who wants tariffs, subsidies or ownership rules to keep key industries in national hands","definitionCN":"主张用关税、补贴或所有权规则把关键产业留在本国手中的人","example":"Economic nationalists blocked the sale of the port to a foreign group.","exampleCN":"经济民族主义者阻止了把港口出售给外国集团。","why":"If the nation is the unit that matters, then strategic assets inside its borders are treated as family property.","whyCN":"如果民族才是重要的单位，那么境内的战略资产就会被当作家族财产看待。"},{"no":"08","title":"An adjective describing a symbol of national pride","titleCN":"描述民族自豪象征的形容词用法","definition":"applied to objects, songs or ceremonies that express national feeling, as in a nationalist symbol or a nationalist anthem","definitionCN":"用于表达民族情感的事物、歌曲或仪式，如民族主义象征、民族主义颂歌","example":"The old anthem became a nationalist symbol during the strike.","exampleCN":"罢工期间，这首老颂歌成了民族主义的象征。","why":"The adjective spreads from people to the objects that carry their feeling, since a flag can be as loud as a speech.","whyCN":"形容词从人扩展到承载其情感的事物，因为一面旗可以和一篇演说一样响亮。"}],"etymology":{"intro":{"en":"Nationalist is a person-word built from the Latin noun for a people, an adjective suffix and the Greek suffix for a follower. Dates are approximate.","cn":"nationalist 是一个指人的词，由表示族群的拉丁名词、一个形容词后缀与表示追随者的希腊后缀构成。年代均为约数。"},"items":[{"era":"LATIN NATIO","en":"Natio meant 'birth, origin' and then 'a people of common birth'; its root nasci 'to be born' is generally thought to be shared with gignere 'to produce'.","cn":"natio 意为「出生、出身」，继而指「同出一源的一群人」；其词根 nasci「出生」一般认为与 gignere「产生」同族。"},{"era":"FRENCH NATIONAL","en":"French formed national from nation, and English borrowed the adjective in the sixteenth century.","cn":"法语由 nation 造出 national，英语在十六世纪借入这个形容词。"},{"era":"GREEK -ISTES","en":"The suffix -istes named an agent or a follower of a practice; Latin took it as -ista and French passed -iste to English as -ist.","cn":"后缀 -istes 指行动者或某种实践的追随者；拉丁作 -ista，法语以 -iste 传给英语，成为 -ist。"},{"era":"ENGLISH NATIONALIST","en":"English joined national and -ist in the eighteenth century, first for a person devoted to a nation's interests and later for a party member.","cn":"英语在十八世纪把 national 与 -ist 结合，最初指关心民族利益的人，后来指政党成员。"},{"era":"PARTY LABEL","en":"In the nineteenth century the word was printed on ballots in several countries, which turned a description into a recognized political identity.","cn":"十九世纪，这个词在若干国家被印上选票，使一个描述变成被承认的政治身份。"},{"era":"UNCERTAIN DATES","en":"Source uncertain (first dates only): the earliest uses are placed somewhere in the eighteenth century, and no single first citation is agreed.","cn":"来源不确定（仅首见年代）：最早的用例被定在十八世纪的某个时段，并无一致认可的最早书证。"}]},"similar":{"note":{"en":"Group one holds the same birth-root family and its look-alike adjectives; group two holds people whose loyalty resembles but does not equal nationalism.","cn":"第一组是同出「出生」词根的词族与形近形容词；第二组是忠诚相似但并不等同的人物称谓。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nationalism","ipa":"/ˈnæʃənəlɪzəm/","tag":"doctrine, not person","definition":"The doctrine itself; -ism names the belief, while -ist names the believer.","definitionCN":"指学说本身；-ism 命名信念，-ist 命名信奉者。"},{"word":"nationalistic","ipa":"/ˌnæʃənəˈlɪstɪk/","tag":"adjective, not person","definition":"An adjective meaning 'showing nationalist feeling'; it cannot stand alone for a person.","definitionCN":"意为「带有民族主义色彩的」形容词，不能单独指人。"},{"word":"national","ipa":"/ˈnæʃənəl/","tag":"neutral belonging","definition":"Simply 'of a nation', as in national park or national average; it carries no doctrine.","definitionCN":"仅表示「属于国家的」，如国家公园、全国平均值，不含学说色彩。"},{"word":"nativist","ipa":"/ˈneɪtɪvɪst/","tag":"same birth root, different stance","definition":"From native, also from nasci, but it names a person who favours established inhabitants over immigrants.","definitionCN":"来自 native，同样出 nasci，但指偏袒本地原有居民、排斥移民的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"patriot","ipa":"/ˈpætriət/","tag":"loves the country","definition":"A person who loves and defends their country; the word need not imply a claim that the country belongs to one ethnic group.","definitionCN":"热爱并保卫自己国家的人；该词不必含有「国家属于某族裔」的主张。"},{"word":"chauvinist","ipa":"/ˈʃɔːvɪnɪst/","tag":"aggressive superiority","definition":"A person with an exaggerated belief in their group's superiority; a nationalist becomes this when contempt dominates.","definitionCN":"对自己群体有夸大优越感的人；当蔑视占上风时，民族主义者就变成这种人。"},{"word":"jingoist","ipa":"/ˈdʒɪŋɡəʊɪst/","tag":"war-minded flag-waver","definition":"A person who pushes for war in the name of national glory; the emphasis is on belligerence rather than statehood.","definitionCN":"以民族荣耀之名推动战争的人，重点在好战而非建国。"},{"word":"separatist","ipa":"/ˈsepərətɪst/","tag":"wants to break away","definition":"A person who seeks to detach a region from an existing state; a nationalist may or may not go that far.","definitionCN":"谋求使某地区脱离现有国家的人；民族主义者未必走到这一步。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nation + -al + -ist: the person who follows the doctrine of the nation.","cn":"nation 加 -al 再加 -ist：信奉民族学说的人。"},{"en":"-ist regularly marks a person, as in realist, socialist and activist, so nationalist is someone rather than something.","cn":"-ist 常标记人物，如 realist、socialist、activist，因此 nationalist 指人而非事物。"},{"en":"The family runs nation, national, nationalism, nationalist, nationalistic, nationality.","cn":"同族词依次是 nation、national、nationalism、nationalist、nationalistic、nationality。"},{"en":"Fixed collocations place the person: nationalist party, nationalist movement, hard-line nationalist.","cn":"固定搭配标出人物位置：民族主义政党、民族主义运动、强硬民族主义者。"},{"en":"The same word serves as adjective before nouns, as in nationalist government and nationalist sentiment.","cn":"同一个词也可作定语形容词，如民族主义政府、民族主义情绪。"}],"abstract":[{"en":"Picture a person holding a map folded to the size of a single province.","cn":"想象一个人举着一张被折成单省大小的地图。"},{"en":"Picture a voter's card and a family photograph kept in the same pocket.","cn":"想象一张选民证与一张全家福被放在同一个口袋里。"},{"en":"Picture a key kept on a string around the neck, as if a house could be carried away.","cn":"想象一把钥匙用绳挂在脖子上，仿佛一座房子可以被随身带走。"}]},"examples":[{"en":"The nationalist spent his twenties printing pamphlets in a borrowed cellar.","cn":"这名民族主义者二十多岁时在一间借来的地下室里印传单。"},{"en":"A hard-line nationalist would rather lose the vote than soften the demand.","cn":"强硬的民族主义者宁愿输掉表决，也不愿软化诉求。"},{"en":"The paper described her as a cultural nationalist rather than a party activist.","cn":"这家报纸称她为文化民族主义者，而非政党活动家。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nation（民族）+ al + ist（人）」——把民族放在第一位的那种人 → 民族主义者","word":"nationalist"},"root":"拉丁 natio「同出一源的人群」出自 nasci「出生」，加 -al 成 national，再加希腊来源的 -ist（行动者）成 nationalist。词根深处与 gignere「产生」一般认为是同族，具体印欧形式属重构。","sensesIntro":{"en":"Eight senses follow one person: a believer in self-rule becomes a party member, an adjective, an insult, a historical label, a defender of language, a protector of industry, and finally a word for the symbols that carry the cause.","cn":"八个义项沿同一个人展开：主张自决者依次成为政党成员、定语形容词、贬义标签、历史称谓、语言捍卫者、产业保护者，最后成为承载事业的象征之形容词。"},"semanticMap":{"core":{"en":"CORE IMAGE: one person standing at the boundary of a people, holding its name in one hand and its language in the other.","cn":"核心意象：一个人站在族群边界上，一手举着族名，一手握着本族语言。"},"chain":["CLAIM SELF-RULE","JOIN THE CAUSE","BECOME A LABEL","HARDEN INTO HATE","DEFEND CULTURE","PROTECT ASSETS"],"branches":[{"senses":"S1 · S2","en":"BELIEVER TO MEMBER: a personal conviction takes on a party card and a voting list.","cn":"从信念到成员：个人信念获得党证与选民名册。"},{"senses":"S3 · S8","en":"ADJECTIVE SPREAD: the person-word starts describing governments, anthems and symbols.","cn":"形容词扩散：这个指人的词开始描述政府、颂歌与象征。"},{"senses":"S4","en":"INSULT: the same conviction is named as prejudice when it turns aggressive.","cn":"贬义：同一种信念在变得有攻击性时被叫作偏见。"},{"senses":"S5","en":"BALLOT IDENTITY: history fixes the word to named parties and old assemblies.","cn":"选票身份：历史把这个词固定在特定政党与旧议会之上。"},{"senses":"S6 · S7","en":"TWO FRONTS: language and industry are the cultural and material halves of the same defence.","cn":"两条战线：语言与产业是同一场防卫的文化面与物质面。"}]},"affixes":{"intro":{"en":"The word stacks two suffixes on a Latin noun, and each step is visible: belonging, then the person who follows.","cn":"这个词在拉丁名词上叠加两个后缀，每一步都看得见：先是归属，后是信奉该主张的人。"},"latinIntro":{"en":"Natio and nasci supply the base; -alis makes the adjective and -ista makes the person.","cn":"natio 与 nasci 提供词基；-alis 造形容词，-ista 造指人的名词。"},"items":[{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"a people of common birth","meaningCN":"同出一源的一群人","example":"The noun names the group before any doctrine exists.","exampleCN":"这个名词在任何学说出现之前就命名了这个群体。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix turns the group into an adjective of belonging.","exampleCN":"这个后缀把这个群体变成表示归属的形容词。"},{"word":"national","structure":"nation + -al","meaning":"of the whole people","meaningCN":"整个民族的","example":"The adjective describes what concerns everyone in the country.","exampleCN":"这个形容词描述与全国每个人都有关的事。"},{"word":"-ist","structure":"-ista (Latin suffix from Greek -istes, one who follows)","meaning":"a follower or agent","meaningCN":"追随者或行动者","example":"The suffix attaches a person to a doctrine.","exampleCN":"这个后缀把一个人附着到一种学说上。"},{"word":"nationalist","structure":"national + -ist","meaning":"a follower of national self-rule","meaningCN":"信奉民族自决的人","example":"The noun names a person, not a feeling.","exampleCN":"这个名词指人，而非情感。"},{"word":"-ism","structure":"-ismus (suffix of doctrine)","meaning":"the doctrine itself","meaningCN":"学说本身","example":"The suffix makes nationalism the belief behind the believer.","exampleCN":"这个后缀使 nationalism 成为信奉者背后的信念。"},{"word":"-ic","structure":"-icus (Latin and Greek adjective suffix)","meaning":"having the character of","meaningCN":"具有……特征的","example":"The suffix yields nationalistic, the adjective of tone.","exampleCN":"这个后缀造出 nationalistic，表示语气倾向的形容词。"},{"word":"-ity","structure":"-itas (Latin suffix, state or quality)","meaning":"the state of being","meaningCN":"……的状态","example":"The suffix turns national into nationality.","exampleCN":"这个后缀把 national 变成 nationality。"}],"latinEntries":[{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"birth, origin, people, tribe","meaningCN":"出生；出身；族群；部落"},{"word":"nasci","structure":"nasci, natus sum (deponent verb, third conjugation)","meaning":"to be born","meaningCN":"出生"},{"word":"nationalis","structure":"nationalis, nationale (adjective, third declension)","meaning":"of a people","meaningCN":"民族的"},{"word":"-ista","structure":"-ista (agent suffix from Greek -istes)","meaning":"one who follows or practises","meaningCN":"追随或从事的人"}]}},{"word":"nation","ipa_uk":"/ˈneɪʃən/","ipa_us":"/ˈneɪʃən/","definition_zh":"民族；国家；全体国民；（历史用法）部落、族群","definition_en":"a people who share a common origin, history or identity, especially when organized as a state","core_image":"一条手绘的边界线穿过同一片口音相同的村庄，把同一个集市分成两半","scene":"旧地图铺在桌上，一条边界线正好穿过说同一种口音的几个村庄，教书的人用手指顺着线划过。The nation was divided by a border drawn through its villages.","sceneCN":"这里 nation 指「共享同一种身份与语言的一群人」（第 2 个义项：以共同出身、语言或历史凝聚的群体，未必与国家疆界重合）；句意为这个民族被一条穿过其村庄的边界分成了两半。图中可辨识物件：旧地图、铅笔画的边界、被切开的集市、手指。","pos":[{"tag":"n.","zh":"民族；国家；全体国民（可数，复数 nations）"}],"collocations":[{"phrase":"sovereign nation","zh":"主权国家"},{"phrase":"a nation of immigrants","zh":"一个由移民构成的国家"},{"phrase":"the nation as a whole","zh":"整个国家；全体国民"},{"phrase":"nation building","zh":"国家建构；民族建构"},{"phrase":"across the nation","zh":"在全国范围内"},{"phrase":"a nation without a state","zh":"没有国家的民族"}],"forms":[{"label":"复数","form":"nations"},{"label":"形容词（国家的；民族的）","form":"national"},{"label":"名词（国籍；民族）","form":"nationality"},{"label":"名词（民族主义）","form":"nationalism"},{"label":"名词（民族主义者）","form":"nationalist"},{"label":"复合词（民族国家）","form":"nation-state"}],"derivatives":[{"word":"national","pos":"adj.","zh":"国家的；民族的（nation 加 -al，指属于整个民族的）"},{"word":"nationality","pos":"n.","zh":"国籍；民族（national 加 -ity，指法律或族群身份）"},{"word":"nationalism","pos":"n.","zh":"民族主义（national 加 -ism，指以民族为中心的主张）"},{"word":"nationalist","pos":"n./adj.","zh":"民族主义者；民族主义的（national 加 -ist）"},{"word":"nationalize","pos":"v.","zh":"收归国有；使全国化（national 加 -ize，使转为国家所有）"},{"word":"nativity","pos":"n.","zh":"出生；诞生（拉丁 nasci 加 -ity，与 nation 同出「出生」词根）"},{"word":"native","pos":"adj./n.","zh":"本地的；本地人（拉丁 nativus，同出 nasci「出生」）"}],"senses":[{"no":"01","title":"A sovereign country","titleCN":"主权国家","definition":"an independent state with its own government, territory and seat at international bodies","definitionCN":"拥有自己的政府、领土与国际组织席位的独立国家","example":"The two nations opened embassies within a year of the ceasefire.","exampleCN":"停火一年之内，这两个国家互设了大使馆。","why":"Because a people organized as a state is the modern default, the plain everyday sense of the word is simply 'country'.","whyCN":"因为「组织成国家的一群人」是现代默认形态，所以这个词最日常的意思就是「国家」。"},{"no":"02","title":"A people sharing identity","titleCN":"共享身份的一群人","definition":"a group held together by a common language, history or sense of belonging, whether or not it has a state","definitionCN":"由共同语言、历史或归属感凝聚的群体，无论是否拥有国家","example":"The nation was divided by a border drawn through its villages.","exampleCN":"这个民族被一条穿过其村庄的边界分成了两半。","why":"The oldest sense is a people born together, and that sense survives precisely where the state and the people do not match.","whyCN":"最古老的意思是「同出一源的一群人」，这一意思恰恰在国家与人群不重合之处延续下来。"},{"no":"03","title":"The citizenry taken as one body","titleCN":"作为整体的全体国民","definition":"the whole body of citizens, often addressed as a single moral actor in speeches","definitionCN":"全体公民的整体，常在演说中被当作单一的道义行动者来称呼","example":"The nation was asked to give up one holiday to fund the hospital.","exampleCN":"全体国民被要求放弃一个假日，为医院筹资。","why":"Once everyone is imagined as one body, speakers can address the whole population as a single person who decides.","whyCN":"一旦所有人被想象成一个整体，演说者就能把全体人口当作一个做决定的单数人格来称呼。"},{"no":"04","title":"A tribe or ethnic people in older usage","titleCN":"旧用法中的部落或族群","definition":"a people or tribe described in history and anthropology, as in the nations of the ancient Near East","definitionCN":"历史学与人类学中描述的族群或部落，如古代近东诸族","example":"The chronicle lists the nations that sent tribute to the capital.","exampleCN":"这部编年史列出了向都城进贡的各族。","why":"Natio in Latin could mean any group of common birth, and that broad sense passed into older English historical writing.","whyCN":"拉丁 natio 可指任何同出一源的群体，这一宽泛含义进入了较早的英语历史写作。"},{"no":"05","title":"A formally recognized tribal nation","titleCN":"获正式承认的原住民族","definition":"the official self-designation of many Native American peoples, as in the Navajo Nation","definitionCN":"许多北美原住民族群的正式自称，如纳瓦霍族","example":"The tribal council speaks for the nation in negotiations with the federal government.","exampleCN":"部落议会在与联邦政府的谈判中代表该民族发言。","why":"Sovereignty language was borrowed from international law, so tribes adopted 'nation' to assert a political status older than the state.","whyCN":"主权话语借自国际法，因此各部落采用「nation」来主张一种比国家更古老的政治地位。"},{"no":"06","title":"The community of states","titleCN":"国际社会中的国家共同体","definition":"the collectivity of states acting together, as in 'the community of nations' or 'the family of nations'","definitionCN":"共同行动的各国整体，如「国际社会」「国家大家庭」","example":"The community of nations voted to send observers.","exampleCN":"国际社会投票决定派出观察员。","why":"When states are treated as persons in international law, their society is naturally described as a group of nations.","whyCN":"当国家在国际法中被当作人格，它们的共同体自然就被描述为一群国家。"},{"no":"07","title":"A student nation at older universities","titleCN":"旧式大学中的学生同乡会","definition":"a regional association of students at historic Scandinavian and other European universities","definitionCN":"北欧及欧洲其他历史悠久的大学中，按地区组成的学生团体","example":"He joined the northern nation and ate at its hall every evening.","exampleCN":"他加入了北方学生同乡会，每晚都在其食堂吃饭。","why":"The word once meant simply a group of people of common origin, which is exactly what a regional student society is.","whyCN":"这个词曾经只表示同出一源的一群人，而按地区组成的学生团体正是如此。"},{"no":"08","title":"A rhetorical collective of like-minded people","titleCN":"修辞上指志趣相同的一群人","definition":"a figurative use such as 'a nation of readers' or 'a nation of shopkeepers', naming a large group by its shared habit","definitionCN":"比喻用法，如「阅读的民族」「店主的国家」，以共同习惯命名一大群人","example":"The magazine called its subscribers a nation of careful readers.","exampleCN":"这本杂志把它的订户称为一个认真阅读的民族。","why":"The rhetorical force comes from treating a shared practice as a common birth, which is the word's original image.","whyCN":"这种修辞力量来自把共同习惯当作共同出身，而这正是这个词最初的意象。"}],"etymology":{"intro":{"en":"Nation comes from a Latin noun of birth, narrowed in French toward a political people and then widened again in English. Dates are approximate.","cn":"nation 来自一个表示出生的拉丁名词，在法语中被收窄为政治意义上的国民，进入英语后又重新变宽。年代均为约数。"},"items":[{"era":"LATIN NASCI","en":"Nasci 'to be born' is generally thought to descend from a root meaning 'to beget', the same stock as gignere 'to produce' and genus 'race, kind'.","cn":"nasci「出生」一般认为源自表示「生育」的词根，与 gignere「产生」、genus「种族、种类」同族。"},{"era":"LATIN NATIO","en":"Natio first named a birth or an origin, then a body of people of common birth; Roman writers also used it for foreigners living in one quarter of the city.","cn":"natio 最初指出生或出身，继而指同出一源的一群人；罗马作家也用它指聚居城中一区的异邦人。"},{"era":"OLD FRENCH NATION","en":"Old French nation narrowed the word to a political people or a province, and English borrowed it in the fourteenth century.","cn":"古法语 nation 把词义收窄为政治意义上的国民或一个行省，英语在十四世纪借入。"},{"era":"ENGLISH NATION","en":"English first used the word for a people of common stock, then for the whole political community of a kingdom, then for a sovereign state.","cn":"英语最初用它指同出一源的族群，继而指一个王国中的整体政治共同体，再指主权国家。"},{"era":"MODERN STATEHOOD","en":"In the eighteenth and nineteenth centuries the word was joined to -state and -hood, and the pairing of nation and state became the normal form of political organization.","cn":"十八、十九世纪，这个词与 state、hood 组合，民族与国家的配对成为常见的政治组织形式。"},{"era":"UNCERTAIN DATES AND RECONSTRUCTION","en":"Source uncertain (dates and reconstruction): the exact point at which the word shifted from a birth-group to a sovereign state is not recorded, and the pre-Latin root form is a reconstruction.","cn":"来源不确定（年代与重构）：从出生群体转向主权国家的确切时点没有记载；拉丁语之前的词根形式属重构形式。"}]},"similar":{"note":{"en":"Group one holds words that share the birth root and are constantly confused; group two holds words for the same large entity seen from different angles.","cn":"第一组是同出「出生」词根、极易混淆的词；第二组是从不同角度指同一大实体的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nationality","ipa":"/ˌnæʃəˈnæləti/","tag":"legal and ethnic status","definition":"The status of belonging to a state in law, or to an ethnic group; it names a status, while nation names the group itself.","definitionCN":"法律上属于某国的身份，或属于某族群的身份；它指身份，而 nation 指群体本身。"},{"word":"national","ipa":"/ˈnæʃənəl/","tag":"adjective","definition":"The adjective 'of a nation', needed before a noun; it cannot stand for the people themselves.","definitionCN":"意为「国家的、民族的」形容词，须置于名词前，不能直接代替人群本身。"},{"word":"nationalism","ipa":"/ˈnæʃənəlɪzəm/","tag":"doctrine","definition":"The doctrine built on nation; it is a belief about nations, not a nation.","definitionCN":"建立在 nation 之上的学说，是关于民族的信念，而非民族本身。"},{"word":"nativity","ipa":"/nəˈtɪvəti/","tag":"same birth root, single birth","definition":"The fact of being born, or a birth scene in art; the root is literal birth rather than a political people.","definitionCN":"指出生这一事实，或艺术中的诞生场景；词根取「出生」字面义，而非政治人群。"}]},{"heading":"NEAR MEANING","entries":[{"word":"state","ipa":"/steɪt/","tag":"legal and institutional","definition":"The political and legal apparatus with borders and sovereignty; a nation may exist without one, a state may hold several.","definitionCN":"拥有边界与主权的政治法律机构；民族可以没有国家，国家也可以包含多个民族。"},{"word":"country","ipa":"/ˈkʌntri/","tag":"everyday territory word","definition":"The everyday word for a land and its people; it stresses territory rather than shared identity.","definitionCN":"指一片土地及其人民的日常用词，侧重领土而非共同身份。"},{"word":"people","ipa":"/ˈpiːpəl/","tag":"the human group","definition":"A body of persons considered together; it can mean the same as nation but carries no claim to a state.","definitionCN":"被整体看待的一群人；可与民族同义，但不含建国主张。"},{"word":"ethnic group","ipa":"/ˈeθnɪk ɡruːp/","tag":"shared descent and culture","definition":"A group defined by ancestry, language and culture; it is the social-science term where nation carries political weight.","definitionCN":"以祖先、语言与文化界定的群体；这是社会科学术语，而 nation 带有政治分量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nasci 'be born' plus -io gives natio, a people of common birth, and English shortened natio to nation.","cn":"nasci「出生」加 -io 得 natio，即同出一源的一群人，英语把 natio 缩为 nation。"},{"en":"The same birth root gives native, nativity and nature, so all three share the idea of what one is born with.","cn":"同一「出生」词根还给出 native、nativity、nature，三者都含「与生俱来」的意思。"},{"en":"The family runs nation, national, nationality, nationalism, nationalist, nationalize.","cn":"同族词依次是 nation、national、nationality、nationalism、nationalist、nationalize。"},{"en":"Fixed phrases mark the senses: sovereign nation, a nation of immigrants, a nation without a state.","cn":"固定搭配标出各义项：主权国家、移民国家、没有国家的民族。"},{"en":"The compound nation-state exists precisely because nation and state can come apart.","cn":"nation-state 这一复合词之所以存在，正因为民族与国家可能分离。"}],"abstract":[{"en":"Picture a family album whose pages are used as a map.","cn":"想象一本家族相册，它的书页被当作地图来用。"},{"en":"Picture a border post standing in the middle of one orchard.","cn":"想象一座边界哨站立在同一个果园的正中间。"},{"en":"Picture a choir singing one song in two separate rooms.","cn":"想象同一个合唱团在两个分开的房间里唱同一首歌。"}]},"examples":[{"en":"The nation rebuilt its railways with money borrowed from abroad.","cn":"这个国家用向外国借来的钱重建了铁路。"},{"en":"A nation can outlive the state that claims to represent it.","cn":"一个民族可以比声称代表它的国家活得更久。"},{"en":"The census asks people to state their nation as well as their citizenship.","cn":"人口普查要求人们同时填写民族与国籍。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「na（那）+ tion（人群）」——那一片同出一源的人 → 民族、国家","word":"nation"},"root":"拉丁 natio「出生、出身、族群」，出自 nasci「出生」；与 gignere「产生」、genus「种族」一般认为是同一词族。英语 nation 兼指民族与国家，因为二者常被视为一体。","sensesIntro":{"en":"Eight senses follow one birth-group: people of common origin become a country, a citizenry, a tribe, a recognized tribal nation, a society of states, a student society, and finally any large group sharing a habit.","cn":"八个义项沿同一个「出生群体」展开：同出一源的人依次成为国家、全体国民、部落、获承认的原住民族、国家共同体、学生同乡会，最后成为任何共享习惯的大群体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn around people of common birth, which later becomes a border on a map.","cn":"核心意象：围绕同出一源的人画一条线，这条线后来变成地图上的国界。"},"chain":["BORN TOGETHER","A PEOPLE","A COUNTRY","THE CITIZENRY","A TRIBE","A COLLECTIVE"],"branches":[{"senses":"S1 · S6","en":"STATE AND SOCIETY: one nation is a country, many nations together are the international community.","cn":"国家与国际社会：单个民族是国家，众多国家合起来是国际社会。"},{"senses":"S2 · S7","en":"PEOPLE WITHOUT A STATE: a nation can be split by a border or organized as a student society.","cn":"无国家的人群：民族可以被边界切开，也可以组织成学生同乡会。"},{"senses":"S3","en":"ONE BODY: the citizenry is addressed as a single moral person.","cn":"一个整体：全体国民被当作单一的道义人格来称呼。"},{"senses":"S4 · S5","en":"TRIBAL NATION: history and law both use the word for peoples organized by descent.","cn":"部落民族：历史学与法学都用这个词指按血缘组织的人群。"},{"senses":"S8","en":"FIGURATIVE GROUP: any shared habit can be played as a common birth.","cn":"比喻群体：任何共同习惯都可以被当作共同出身来用。"}]},"affixes":{"intro":{"en":"Nation is a Latin noun of birth with a state suffix, and the same stem then feeds nationality, nationalism and national.","cn":"nation 是一个表示出生、带状态后缀的拉丁名词，同一词干又衍生出 nationality、nationalism、national。"},"latinIntro":{"en":"Nasci supplies the verb, -io makes a noun of state, and natio is the result; -al and -itas extend the family.","cn":"nasci 提供动词，-io 构成状态名词，natio 即其结果；-al 与 -itas 再扩展整个词族。"},"items":[{"word":"nasci","structure":"nasci, natus sum (Latin deponent verb)","meaning":"to be born","meaningCN":"出生","example":"The verb is the root of the whole family.","exampleCN":"这个动词是整族词的词根。"},{"word":"-io","structure":"-io, -ionis (Latin noun suffix, action or state)","meaning":"an act or a state","meaningCN":"动作或状态","example":"The suffix turns the verb of birth into a noun.","exampleCN":"这个后缀把「出生」动词变成名词。"},{"word":"natio","structure":"nasci + -io","meaning":"birth; a people of common birth","meaningCN":"出生；同出一源的人群","example":"The noun starts as a single birth and ends as a people.","exampleCN":"这个名词从一次出生出发，最后指一群人。"},{"word":"nation","structure":"natio (Old French nation)","meaning":"a people; a country","meaningCN":"民族；国家","example":"English shortened the Latin noun without changing its core.","exampleCN":"英语缩短了这个拉丁名词，核心含义未变。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix produces national from nation.","exampleCN":"这个后缀由 nation 造出 national。"},{"word":"-ity","structure":"-itas (Latin suffix, state or quality)","meaning":"the state of being","meaningCN":"……的状态","example":"The suffix produces nationality from national.","exampleCN":"这个后缀由 national 造出 nationality。"},{"word":"-ism","structure":"-ismus (suffix of doctrine or practice)","meaning":"a doctrine","meaningCN":"学说","example":"The suffix produces nationalism from national.","exampleCN":"这个后缀由 national 造出 nationalism。"},{"word":"-ize","structure":"-izare (Latin and Greek verb suffix, to make)","meaning":"to make or convert","meaningCN":"使成为；使转化","example":"The suffix produces nationalize from national.","exampleCN":"这个后缀由 national 造出 nationalize。"}],"latinEntries":[{"word":"nasci","structure":"nasci, natus sum (deponent verb, third conjugation)","meaning":"to be born, arise","meaningCN":"出生；产生"},{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"birth, origin, people, tribe","meaningCN":"出生；出身；族群；部落"},{"word":"nativus","structure":"nativus, nativa, nativum (adjective, first and second declension)","meaning":"native, born with","meaningCN":"本地的；天生的"},{"word":"nationalis","structure":"nationalis, nationale (adjective, third declension)","meaning":"of a people","meaningCN":"民族的"}]}},{"word":"nation-state","ipa_uk":"/ˌneɪʃən ˈsteɪt/","ipa_us":"/ˌneɪʃən ˈsteɪt/","definition_zh":"民族国家；指疆界与民族共同体大致重合、以民族认同整合的主权国家","definition_en":"a sovereign state whose territory is understood to coincide with the homeland of one people","core_image":"两张透明地图叠在灯下，一张画国界，一张画方言分布，两条线几乎重合","scene":"会议室的墙上并排挂着两张地图，一张画国界，一张画方言分布，讲解的人用两支笔同时描过两条线。The nation-state rests on the hope that a border and a language map can be made to coincide.","sceneCN":"这里 nation-state 指「疆界与民族分布大致重合的国家形态」（第 1 个义项：以民族共同体为其领土基础的主权国家）；句意为民族国家建立在这样一个希望上：国界与语言地图能够被画成同一条线。图中可辨识物件：两张地图、两支描线笔、投影灯、会议桌。","pos":[{"tag":"n.","zh":"民族国家（可数，复数 nation-states；亦作定语，如 nation-state system）"}],"collocations":[{"phrase":"the modern nation-state","zh":"现代民族国家"},{"phrase":"nation-state system","zh":"民族国家体系"},{"phrase":"nation-state building","zh":"民族国家建构"},{"phrase":"a fragile nation-state","zh":"脆弱的民族国家"},{"phrase":"the rise of the nation-state","zh":"民族国家的兴起"},{"phrase":"nation-state sovereignty","zh":"民族国家主权"}],"forms":[{"label":"复数","form":"nation-states"},{"label":"名词（国家地位）","form":"nation-statehood"},{"label":"相关名词（民族）","form":"nation"},{"label":"相关名词（国家）","form":"state"},{"label":"相关名词（国家地位）","form":"statehood"},{"label":"相关形容词（无国家的）","form":"stateless"}],"derivatives":[{"word":"nation","pos":"n.","zh":"民族（拉丁 natio「同出一源的人群」，出自 nasci「出生」）"},{"word":"national","pos":"adj.","zh":"民族的；国家的（nation 加 -al）"},{"word":"nationalism","pos":"n.","zh":"民族主义（national 加 -ism，指以民族为中心的主张）"},{"word":"state","pos":"n.","zh":"国家；状态（拉丁 status「站立的状态」，出自 stare「站立」）"},{"word":"statehood","pos":"n.","zh":"国家地位（state 加 -hood，指成为国家的状态）"},{"word":"stateless","pos":"adj.","zh":"无国籍的；无国家的（state 加 -less，指不属任何国家）"},{"word":"nationhood","pos":"n.","zh":"民族地位；民族意识（nation 加 -hood，指成为民族的状态）"}],"senses":[{"no":"01","title":"A state whose borders match a people","titleCN":"疆界与民族大致重合的国家","definition":"a state that claims to be the political home of one people, with borders treated as the edge of that homeland","definitionCN":"声称是某一民族政治家园的国家，其边界被视为该民族家园的边缘","example":"The nation-state rests on the hope that a border and a language map can be made to coincide.","exampleCN":"民族国家建立在这样一个希望上：国界与语言地图能够被画成同一条线。","why":"The compound simply puts the two nouns side by side, so its core sense is the fit between a people and a state.","whyCN":"这个复合词只是把两个名词并排，因此核心意思就是「民族与国家相合」。"},{"no":"02","title":"The ideal type in political science","titleCN":"政治学中的理想类型","definition":"a model used for comparison rather than a description of any real country, since most states contain several peoples","definitionCN":"用于比较的模型，而非对任何现实国家的描述，因为多数国家内部都有多个民族","example":"Analysts treat the nation-state as an ideal type, not a census category.","exampleCN":"分析者把民族国家当作理想类型，而不是人口统计类别。","why":"Once scholars need a benchmark to measure real states against, the word becomes a theoretical model rather than a place.","whyCN":"当学者需要一个基准来衡量现实国家，这个词就变成理论模型，而不再是一个地点。"},{"no":"03","title":"The historical product of nineteenth-century nationalism","titleCN":"十九世纪民族主义的历史产物","definition":"the form of state that emerged in Europe when nationalist movements merged cultural nations with existing administrative units","definitionCN":"欧洲民族主义运动把文化民族与既有行政单元合并后出现的国家形态","example":"The nation-state was assembled from provinces that had never shared a school system.","exampleCN":"这个民族国家由从未共用过一套学校体系的多个省份拼合而成。","why":"The thing itself has a birthday: railways, schools and newspapers let a state standardize one language across its territory.","whyCN":"这一事物本身有诞生日：铁路、学校与报纸让国家能在领土上标准化一种语言。"},{"no":"04","title":"An ethnic nation-state","titleCN":"以族裔核心为基础的民族国家","definition":"a state that defines belonging by ancestry and treats one ethnic group's culture as the national culture","definitionCN":"以祖源界定归属、并把某一族群的文化当作国家文化的国家","example":"An ethnic nation-state can make old minorities feel newly foreign.","exampleCN":"以族裔为核心的民族国家会让原有少数群体突然觉得自己是外人。","why":"If the nation is a people born together, the most literal state is one whose institutions reproduce that birth group.","whyCN":"如果民族是「同出一源的一群人」，最字面意义上的国家就是其制度复制这一血缘群体的国家。"},{"no":"05","title":"A civic nation-state","titleCN":"以公民身份为基础的民族国家","definition":"a state that builds national unity from citizenship, law and shared political values rather than descent","definitionCN":"以公民身份、法律与共同政治价值而非血统来建立国家团结的国家","example":"A civic nation-state can absorb newcomers through school and naturalization.","exampleCN":"公民民族国家可以通过学校与入籍吸收新来者。","why":"The same compound supports a different answer to who belongs, since the people can be defined by law instead of blood.","whyCN":"同一个复合词也支持对「谁属于这里」的不同回答，因为人民可以由法律而非血统来界定。"},{"no":"06","title":"The nation-state as a sovereign actor","titleCN":"作为主权行动者的民族国家","definition":"the unit treated as a single legal person in international relations, with borders, treaties and a seat at the table","definitionCN":"在国际关系中被当作单一法律人格的单位，拥有边界、条约与谈判席位","example":"Global markets now move faster than the nation-state can legislate.","exampleCN":"全球市场的变动速度已快过民族国家的立法速度。","why":"Because the state half supplies sovereignty, the compound also names the basic actor in diplomacy and international law.","whyCN":"因为后半的 state 提供主权，这个复合词也命名外交与国际法中的基本行动者。"},{"no":"07","title":"The model pursued by postcolonial state-builders","titleCN":"后殖民建国者追求的模型","definition":"the template adopted by new states that inherited colonial borders and tried to turn them into national homelands","definitionCN":"继承殖民边界并试图把这些边界变成民族家园的新国家所采用的模板","example":"Postcolonial leaders inherited a nation-state whose borders cut through several peoples.","exampleCN":"后殖民领导人继承了一个边界穿过数个民族的民族国家。","why":"Independence handed new governments colonial maps, and the compound names the ambition of turning those maps into nations.","whyCN":"独立把殖民地图交给新政府，而这个复合词命名了把这些地图变成民族的雄心。"},{"no":"08","title":"The attributive use in debates about globalization","titleCN":"讨论全球化时作定语的用法","definition":"used before nouns such as system, building or sovereignty to name the political order being defended or eroded","definitionCN":"置于 system、building、sovereignty 等名词前，指正在被捍卫或被侵蚀的政治秩序","example":"The nation-state system is older than most of its members.","exampleCN":"民族国家体系比它的大多数成员都要古老。","why":"When writers need a shorthand for the whole order, the compound works as a modifier without losing its two-part shape.","whyCN":"当作者需要指称整个秩序的简称时，这个复合词就充当修饰语，而两部分的结构仍然保留。"}],"etymology":{"intro":{"en":"Nation-state is a modern compound of a Latin birth-noun and a Latin standing-noun, coined when the two ideas were deliberately fused. Dates are approximate.","cn":"nation-state 是把一个表示出生的拉丁名词与一个表示站立状态的拉丁名词组成的现代复合词，造出时正是要把这两个观念有意熔合。年代均为约数。"},"items":[{"era":"LATIN NATIO","en":"Natio meant 'birth, origin' and then 'a people of common birth', from nasci 'to be born'; its deeper root is a reconstruction.","cn":"natio 意为「出生、出身」，继而指「同出一源的人群」，出自 nasci「出生」；更深词根属重构形式。"},{"era":"LATIN STATUS","en":"Status meant 'a standing, a condition', from stare 'to stand'; it named a person's legal position before it named a polity.","cn":"status 意为「站立的状态、处境」，出自 stare「站立」；它先指个人的法律地位，后来才指政治共同体。"},{"era":"ENGLISH STATE","en":"English state first meant a condition or a rank, and only in the sixteenth century came to mean the organized political community of a territory.","cn":"英语 state 最初指状态或等级，直到十六世纪才指一片领土上有组织的政治共同体。"},{"era":"COMPOUND NATION-STATE","en":"The two words were joined in the early twentieth century to name a state that claims to be the home of one people, a term needed once empires broke into successor states.","cn":"这两个词在二十世纪初组合，用来指声称是一个民族家园的国家；帝国分裂为后继国家后，这一术语变得必要。"},{"era":"POLITICAL SCIENCE","en":"Mid-twentieth-century scholarship turned the compound into an ideal type, and it now names a model as often as a place.","cn":"二十世纪中期的学术研究把这个复合词变成理想类型，如今它既指地点，也同样常指模型。"},{"era":"UNCERTAIN DATES AND RECONSTRUCTION","en":"Source uncertain (dates and reconstruction): the first written use of the hyphenated compound is dated differently by different reference works, and the pre-Latin roots of both halves are reconstructions.","cn":"来源不确定（年代与重构）：这个带连字符的复合词最早的书面用例，各家工具书给出的年代不一；前后两半在拉丁语之前的词根均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the component words and near-identical compounds that get swapped; group two holds other political forms that are defined against it.","cn":"第一组是构成词与极易替换的近形复合词；第二组是与之相对照的其他政治形态。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nation","ipa":"/ˈneɪʃən/","tag":"one half of the compound","definition":"The people alone; it says nothing about a state, which is why a nation can exist without one.","definitionCN":"仅指人群，不涉及国家，因此民族可以没有国家。"},{"word":"state","ipa":"/steɪt/","tag":"the other half","definition":"The political and legal apparatus alone; a state may contain many nations or only part of one.","definitionCN":"仅指政治法律机构；一个国家可以包含多个民族，也可以只含某一民族的一部分。"},{"word":"nationhood","ipa":"/ˈneɪʃənhʊd/","tag":"status, not structure","definition":"The condition of being a nation; it is a status, while the compound names an institutional form.","definitionCN":"指成为民族的状态；它是身份，而这个复合词指制度形态。"},{"word":"nation building","ipa":"/ˈneɪʃən ˌbɪldɪŋ/","tag":"process, not entity","definition":"The process of forging a shared national identity; the compound is the resulting structure.","definitionCN":"指锻造共同民族身份的过程；复合词指由此形成的结构。"}]},{"heading":"NEAR MEANING","entries":[{"word":"multinational state","ipa":"/ˌmʌltiˈnæʃənəl steɪt/","tag":"the opposite case","definition":"A state that openly contains several nations and does not claim to belong to one people.","definitionCN":"公开包含多个民族、且不声称属于单一人群的国家。"},{"word":"sovereign state","ipa":"/ˈsəvərɪn steɪt/","tag":"legal term","definition":"The international-law term for an independent state, silent on whether its borders match a nation.","definitionCN":"国际法中指独立国家的术语，不涉及边界是否与民族重合。"},{"word":"city-state","ipa":"/ˈsɪti steɪt/","tag":"small urban polity","definition":"A sovereign city and its hinterland, a form older than the national model and organized around a town rather than a people.","definitionCN":"拥有主权的城市及其腹地，这种形态早于民族模型，以城镇而非民族为中心。"},{"word":"empire","ipa":"/ˈempaɪə/","tag":"many peoples, one ruler","definition":"A polity holding many nations under one sovereign; it is the historic opposite of the one-people ideal.","definitionCN":"把多个民族置于一位君主之下的政体，是「一族一国」理想的历史对立面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Nation 'a people born together' plus state 'a standing political order': two halves, one claim that they fit.","cn":"nation「同出一源的人群」加 state「站立的政治秩序」：两半，一个「二者相合」的主张。"},{"en":"The hyphen is doing work: it marks a fusion that is desired rather than a fact that is observed.","cn":"连字符在起作用：它标记一种被期望的熔合，而非被观察到的事实。"},{"en":"The family runs nation, national, nationalism, state, statehood, stateless, nationhood.","cn":"同族词依次是 nation、national、nationalism、state、statehood、stateless、nationhood。"},{"en":"Fixed collocations mark the debates: nation-state system, nation-state building, the rise of the nation-state.","cn":"固定搭配标出相关争论：民族国家体系、民族国家建构、民族国家的兴起。"},{"en":"The contrasting term is multinational state, which exists because most real states hold several peoples.","cn":"对照术语是多民族国家，它的存在正因为多数现实国家包含多个民族。"}],"abstract":[{"en":"Picture two sheets of tracing paper laid one over the other until their lines almost touch.","cn":"想象两张描图纸叠在一起，直到它们的线条几乎贴合。"},{"en":"Picture a passport and a family tree printed on the same page.","cn":"想象一本护照与一棵家族树被印在同一页上。"},{"en":"Picture a classroom map where the colour of the language and the colour of the border are the same shade.","cn":"想象一张教室地图上，语言的颜色与边界的颜色是同一种色调。"}]},"examples":[{"en":"The peace conference tried to fit nation-states onto maps drawn for empires.","cn":"和会试图把民族国家套进为帝国绘制的地图上。"},{"en":"Migration has made the pure nation-state rare in practice.","cn":"移民使纯粹的民族国家在现实中变得少见。"},{"en":"The nation-state remains the unit that issues passports and signs treaties.","cn":"民族国家仍是签发护照与签署条约的单位。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nation（民族）+ state（国家）」——让民族的边界长成国家的边界 → 民族国家","word":"nation-state"},"root":"nation 出自拉丁 natio「同出一源的人群」（nasci「出生」）；state 出自拉丁 status「站立的状态」（stare「站立」）。复合词把「人群」与「政治秩序」并置，主张二者边界重合，是近代民族主义兴起后的产物。","sensesIntro":{"en":"Eight senses follow one fit: a people is matched to a state, and the match is then used as an ideal type, a historical product, an ethnic model, a civic model, a sovereign actor, a postcolonial ambition, and a shorthand for the whole order.","cn":"八个义项沿同一个「吻合」展开：人群与国家被配对，这一配对再被用作理想类型、历史产物、族裔模型、公民模型、主权行动者、后殖民雄心，以及整个秩序的简称。"},"semanticMap":{"core":{"en":"CORE IMAGE: a border line laid directly on top of a language boundary until the two become one line.","cn":"核心意象：把国界线直接压在语言分界线上，直到两条线变成一条。"},"chain":["A PEOPLE","A STATE","THE FIT","THE MODEL","THE ACTOR","THE ORDER"],"branches":[{"senses":"S1 · S2","en":"FIT AND MODEL: the same match is both a claim about places and a benchmark for comparing them.","cn":"吻合与模型：同一种配对既是对地方的断言，也是比较它们的基准。"},{"senses":"S3","en":"HISTORICAL BIRTH: schools, railways and newspapers made the fit possible in the nineteenth century.","cn":"历史诞生：学校、铁路与报纸在十九世纪使这种吻合成为可能。"},{"senses":"S4 · S5","en":"TWO ANSWERS: descent and citizenship are rival definitions of the people being fitted to the state.","cn":"两个答案：血统与公民身份是对「被配对的人群」的竞争性定义。"},{"senses":"S6 · S8","en":"SOVEREIGN ORDER: one actor at the table, and a whole system of such actors.","cn":"主权秩序：谈判桌上的一个行动者，以及由这类行动者构成的整个体系。"},{"senses":"S7","en":"POSTCOLONIAL HOPE: inherited colonial lines are asked to become national homes.","cn":"后殖民希望：继承来的殖民边界被要求变成民族家园。"}]},"affixes":{"intro":{"en":"Both halves keep their own morphology: a birth-noun with its suffixes, and a standing-noun that also yields status words.","cn":"前后两半都保留各自的构词：一个带后缀的出生名词，以及一个同样衍生状态类词的站立名词。"},"latinIntro":{"en":"Nasci and natio build the first half; stare and status build the second, and English added -hood and -less to both.","cn":"nasci 与 natio 构成前半，stare 与 status 构成后半，英语又给两半分别加上 -hood 与 -less。"},"items":[{"word":"nasci","structure":"nasci, natus sum (Latin deponent verb)","meaning":"to be born","meaningCN":"出生","example":"The verb supplies the people's shared origin.","exampleCN":"这个动词提供人群的共同出身。"},{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"a people of common birth","meaningCN":"同出一源的人群","example":"The noun supplies the first half of the compound.","exampleCN":"这个名词提供复合词的前半。"},{"word":"stare","structure":"stare, steti, statum (Latin verb, first conjugation)","meaning":"to stand","meaningCN":"站立","example":"The verb supplies the image of something standing firm.","exampleCN":"这个动词提供「稳固站立」的意象。"},{"word":"status","structure":"status, status (m., fourth declension)","meaning":"a standing, a condition","meaningCN":"站立的状态；处境","example":"The noun moves from a person's rank to a polity's order.","exampleCN":"这个名词从个人等级转到政治秩序的层面。"},{"word":"state","structure":"status (through Old French estat)","meaning":"condition; organized political community","meaningCN":"状态；有组织的政治共同体","example":"The second half supplies sovereignty.","exampleCN":"后半提供主权含义。"},{"word":"nation-state","structure":"nation + state","meaning":"a state claiming one people as its base","meaningCN":"以单一民族为基础的国家","example":"The compound asserts a fit rather than describing one.","exampleCN":"这个复合词是主张一种吻合，而非描述一种吻合。"},{"word":"-hood","structure":"-had (Old English suffix, state or condition)","meaning":"the state of being","meaningCN":"……的状态","example":"The suffix yields nationhood and statehood.","exampleCN":"这个后缀造出 nationhood 与 statehood。"},{"word":"-less","structure":"-leas (Old English suffix, without)","meaning":"without","meaningCN":"没有……的","example":"The suffix yields stateless for people outside any state.","exampleCN":"这个后缀造出 stateless，指不属于任何国家的人。"},{"word":"-ism","structure":"-ismus (suffix of doctrine)","meaning":"a doctrine","meaningCN":"学说","example":"The suffix yields nationalism from the first half.","exampleCN":"这个后缀由前半造出 nationalism。"}],"latinEntries":[{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"birth, origin, people","meaningCN":"出生；出身；族群"},{"word":"nasci","structure":"nasci, natus sum (deponent verb, third conjugation)","meaning":"to be born","meaningCN":"出生"},{"word":"status","structure":"status, status (m., fourth declension)","meaning":"standing, condition, position","meaningCN":"站立；状态；地位"},{"word":"stare","structure":"stare, steti, statum (verb, first conjugation)","meaning":"to stand, remain","meaningCN":"站立；停留"}]}},{"word":"treaty","ipa_uk":"/ˈtriːti/","ipa_us":"/ˈtriːti/","definition_zh":"条约；（尤指国家间）正式签署、受国际法约束的书面协定；和约","definition_en":"a formal written agreement between states, binding under international law, especially one that ends a war or settles a dispute","core_image":"长桌上摊开一张厚纸，两支笔同时落在签名线上，纸角压着一枚火漆印章","scene":"窗外港口刚刚停火，长桌上的厚纸摊开，两支笔同时落在签名线上，纸角压着印章。The two states signed a treaty that returned the captured port.","sceneCN":"这里 treaty 指「国家间正式签署、具有约束力的书面协定」（第 1 个义项：经授权代表签署并受国际法约束的国家间协议）；句意为两国签署了一份归还被占领港口的条约。图中可辨识物件：厚纸、两支笔、火漆印章、窗外港口。","pos":[{"tag":"n.","zh":"条约；协定（可数，复数 treaties）"}],"collocations":[{"phrase":"sign a treaty","zh":"签署条约"},{"phrase":"ratify a treaty","zh":"批准条约"},{"phrase":"peace treaty","zh":"和平条约；和约"},{"phrase":"treaty of alliance","zh":"同盟条约"},{"phrase":"treaty obligations","zh":"条约义务"},{"phrase":"under the treaty","zh":"根据该条约"}],"forms":[{"label":"复数","form":"treaties"},{"label":"动词（对待；谈判）","form":"treat"},{"label":"名词（处理；治疗）","form":"treatment"},{"label":"名词（论著）","form":"treatise"},{"label":"名词（谈判；处理）","form":"negotiation"},{"label":"相关形容词（条约的）","form":"treaty-based"}],"derivatives":[{"word":"treat","pos":"v./n.","zh":"对待；处理；请客（由拉丁 tractare「处理」经法语 traiter 而来，语义从「处置」扩到「招待」）"},{"word":"treatment","pos":"n.","zh":"处理；治疗（treat 加 -ment，指处理的动作或方式）"},{"word":"treatise","pos":"n.","zh":"论著（由 traiter 加 -ise 构成，指系统处理某一主题的著作）"},{"word":"tractable","pos":"adj.","zh":"易处理的；温顺的（拉丁 tractare 加 -able，指可被处理的）"},{"word":"tract","pos":"n.","zh":"地带；小册子（拉丁 tractus「拉长的东西」，同出 trahere「拉」）"},{"word":"contract","pos":"n./v.","zh":"合同；收缩（com- 加 trahere「拉」，把双方拉到一起，与 treaty 同根不同前缀）"}],"senses":[{"no":"01","title":"A binding written agreement between states","titleCN":"国家间具有约束力的书面协定","definition":"an instrument signed by authorized representatives and governed by international law","definitionCN":"由授权代表签署、受国际法管辖的正式文书","example":"The two states signed a treaty that returned the captured port.","exampleCN":"两国签署了一份归还被占领港口的条约。","why":"The word descends from a verb meaning 'to handle or negotiate', so the document is the handled result of long bargaining.","whyCN":"这个词出自表示「处理、交涉」的动词，因此文书是长期交涉被「处理」出来的结果。"},{"no":"02","title":"A peace treaty ending a war","titleCN":"结束战争的和约","definition":"the settlement that formally ends hostilities and fixes borders, reparations or withdrawals","definitionCN":"正式结束敌对行动、确定边界、赔款或撤军安排的协定","example":"The peace treaty was signed in a railway carriage.","exampleCN":"和约是在一节火车车厢里签署的。","why":"Ending a war is the oldest and most visible use, so 'treaty' alone often means the peace instrument.","whyCN":"结束战争是最古老也最显眼的用途，因此 treaty 单独出现时常指和约。"},{"no":"03","title":"A treaty of alliance or friendship","titleCN":"同盟或友好条约","definition":"an agreement promising mutual support, trade rights or non-aggression rather than settling a past war","definitionCN":"承诺相互支持、贸易权利或不侵犯的协定，而非清算过去的战争","example":"The treaty of alliance obliged both fleets to sail together.","exampleCN":"同盟条约要求两支舰队共同出航。","why":"The instrument is the same, but the content looks forward rather than backward, so the same word covers promises about the future.","whyCN":"文书形式相同，但内容朝向未来而不是清算过去，因此同一个词也涵盖对未来的承诺。"},{"no":"04","title":"Any formal bilateral agreement","titleCN":"任何正式的双边协定","definition":"a written arrangement on a specific matter, such as extradition, taxation or fishing rights","definitionCN":"就引渡、税收或捕鱼权等具体事项作出的书面安排","example":"An extradition treaty lets each state hand over suspects to the other.","exampleCN":"引渡条约允许两国把嫌疑人移交给对方。","why":"Once the form is established, any subject that two governments need to settle in writing can be dressed in it.","whyCN":"形式一旦确立，两国政府需要书面解决任何事项，都可以套用这一形式。"},{"no":"05","title":"The instrument requiring ratification","titleCN":"须经批准程序才生效的文书","definition":"the signed text that only binds a state after its legislature or head of state ratifies it","definitionCN":"签署后仍需经立法机关或国家元首批准才对国家产生约束的文本","example":"The treaty was signed in June but ratified only in December.","exampleCN":"条约在六月签署，但直到十二月才获批准。","why":"Signature and obligation are separated in modern practice, so the word often names the paper that waits for approval.","whyCN":"在现代实践中签署与生效是分开的，因此这个词常指等待批准的文书。"},{"no":"06","title":"A treaty between a state and indigenous nations","titleCN":"国家与原住民族之间的条约","definition":"an agreement recognizing tribal rights, land or self-government, often older than the state that now disputes it","definitionCN":"承认部落权利、土地或自治的协定，其年代常早于如今对它有争议的国家","example":"The tribe went to court to defend rights promised in an old treaty.","exampleCN":"该部落上法庭捍卫一份旧条约中承诺的权利。","why":"Because tribes were treated as sovereign partners in early diplomacy, their agreements were also called treaties and still are.","whyCN":"因为早期外交把部落当作主权伙伴，它们的协议也被称为条约，至今如此。"},{"no":"07","title":"The old sense of negotiation itself","titleCN":"古旧用法：指谈判过程本身","definition":"an archaic use for the discussion and bargaining that precedes a settlement, not the document","definitionCN":"古旧用法，指达成协定之前的讨论与交涉过程，而非文书","example":"The old chronicle says the treaty lasted three months before any paper was signed.","exampleCN":"旧编年史说，这场谈判持续了三个月才签下任何纸张。","why":"The Latin source names the handling and discussing, and English kept that sense for centuries before the paper took over.","whyCN":"拉丁词源指「处理与讨论」，英语保留这一含义数百年，之后才转指文书。"},{"no":"08","title":"A figurative bargain between two parties","titleCN":"比喻：两方达成的临时约定","definition":"a humorous or journalistic use for any carefully negotiated truce between neighbours, departments or rivals","definitionCN":"幽默或新闻用法，指邻居、部门或对手之间小心谈成的任何停战式约定","example":"The two departments wrote a treaty about who owns the photocopier.","exampleCN":"两个部门就复印机归谁用写了一份「条约」。","why":"The metaphor borrows the solemnity of diplomacy to make a small deal sound like a settlement between powers.","whyCN":"这个比喻借外交的庄重感，让一桩小事听起来像两个强权之间的和谈。"}],"etymology":{"intro":{"en":"Treaty comes from a Latin verb of handling and pulling, through French, and moved from the act of negotiating to the paper produced. Dates are approximate.","cn":"treaty 经法语来自一个表示「处理、拉拽」的拉丁动词，从谈判这一动作转到谈判产生的文书。年代均为约数。"},"items":[{"era":"LATIN TRAHERE","en":"Trahere meant 'to pull, draw, drag'; its past participle tractus also gives tract and the tract- words in English.","cn":"trahere 意为「拉、拖、牵引」；其过去分词 tractus 还衍生出 tract 以及英语中一系列 tract- 词。"},{"era":"LATIN TRACTARE","en":"Tractare was a frequentative of trahere, 'to handle or deal with repeatedly', and from handling it came to mean discussing and negotiating.","cn":"tractare 是 trahere 的反复动词，意为「反复处理、应对」，由「处理」引申为「讨论、交涉」。"},{"era":"LATIN TRACTATUS","en":"Tractatus named a handling, a discussion or a written account; the word could mean both the talk and the text that came out of it.","cn":"tractatus 指处理、讨论或书面记述；这个词既可指谈话，也可指谈话产生的文本。"},{"era":"FRENCH TRAITE","en":"Old French traite narrowed the noun toward a negotiated settlement, and English borrowed it in the fourteenth century.","cn":"古法语 traite 把这个名词收窄为谈成的协定，英语在十四世纪借入。"},{"era":"ENGLISH TREATY","en":"English first used the word for the process of negotiation, then for the document, and by the seventeenth century the diplomatic instrument was the dominant sense.","cn":"英语最初用这个词指谈判过程，继而指文书；到十七世纪，外交文书已成为主要含义。"},{"era":"UNCERTAIN DATES AND RECONSTRUCTION","en":"Source uncertain (dates and reconstruction): the exact point of the shift from negotiation to document is not recorded, and the deeper origin of trahere is a reconstruction.","cn":"来源不确定（年代与重构）：从「谈判」转向「文书」的确切时点没有记载；trahere 更深层的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root relatives and near-identical legal words that are routinely confused; group two holds instruments that differ in solemnity or scope.","cn":"第一组是同根亲属与常被混淆的相近法律词；第二组是庄重程度或适用范围不同的文书。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"treat","ipa":"/triːt/","tag":"verb, same root","definition":"The verb 'to deal with or behave toward'; it comes from the same tractare, but it is not a document.","definitionCN":"动词「处理、对待」，同出 tractare，但并非文书。"},{"word":"treatise","ipa":"/ˈtriːtɪs/","tag":"same root, a book","definition":"A long written work on a subject, from the same handling root; it discusses rather than binds.","definitionCN":"就某一主题写成的长篇论著，同出「处理」词根；它是论述，不具约束力。"},{"word":"contract","ipa":"/ˈkɒntrækt/","tag":"same root, different prefix","definition":"From com- 'together' plus trahere 'pull', so parties are pulled together; it is enforceable in private law, not between states.","definitionCN":"由 com-「共同」加 trahere「拉」构成，把各方拉到一处；它在私法中可强制执行，而非国家间。"},{"word":"tract","ipa":"/trækt/","tag":"same participle, concrete","definition":"From tractus 'a drawing out', it names a stretch of land or a pamphlet, not an agreement.","definitionCN":"出自 tractus「拉长之物」，指一片土地或一本小册子，并非协定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pact","ipa":"/pækt/","tag":"less formal","definition":"A general word for an agreement, often political or personal and not necessarily ratified; treaty is the formal legal instrument.","definitionCN":"协议的通称，常指政治或个人约定，未必经过批准；treaty 是正式法律文书。"},{"word":"accord","ipa":"/əˈkɔːd/","tag":"settlement tone","definition":"An agreement, often used in titles of settlements; it stresses harmony reached rather than the paper's status.","definitionCN":"指协议，常用于协定名称；侧重达成的和谐，而非文书的地位。"},{"word":"convention","ipa":"/kənˈvenʃən/","tag":"multilateral treaty type","definition":"A multilateral agreement adopted by many states, often under an international organization; a treaty may be bilateral or multilateral.","definitionCN":"由许多国家通过的多边协定，常在国际组织主持下达成；treaty 可以是双边或多边。"},{"word":"armistice","ipa":"/ɑːˈmɪstɪs/","tag":"stop fighting only","definition":"An agreement to stop shooting, not a full peace settlement; a treaty may follow an armistice.","definitionCN":"仅停止射击的约定，不是完整的和平安排；armistice 之后才可能有和约。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"trahere 'pull' plus the frequentative -tare gives tractare 'handle repeatedly', and handling a dispute produces a treaty.","cn":"trahere「拉」加反复后缀 -tare 得 tractare「反复处理」，反复处理争端的结果就是条约。"},{"en":"The root family runs tract, tractable, treat, treatment, treatise, treaty, contract.","cn":"同根词依次是 tract、tractable、treat、treatment、treatise、treaty、contract。"},{"en":"Fixed collocations show the stages: sign a treaty, ratify a treaty, treaty obligations.","cn":"固定搭配显示阶段：签署条约、批准条约、条约义务。"},{"en":"The paper sense won: English once used the word for the talking, and now uses it for the signed sheet.","cn":"文书义胜出：英语曾用它指谈话，如今用它指签好的纸页。"},{"en":"The near neighbours split by scope: a pact can be informal, an accord is a settlement, an armistice only stops the guns.","cn":"近义词按范围区分：pact 可以非正式，accord 是协定，armistice 只停枪。"}],"abstract":[{"en":"Picture two hands pulling one rope from opposite ends until a knot holds them still.","cn":"想象两只手从两端拉同一根绳，直到一个结把双方固定住。"},{"en":"Picture a heavy book left open on a table as a doorstop for two rooms.","cn":"想象一本厚书摊在桌上，被当作两个房间之间的门挡。"},{"en":"Picture a wax seal pressed onto a page, cooling into a small hard coin.","cn":"想象一枚火漆印章压在纸页上，冷却成一小枚硬币。"}]},"examples":[{"en":"The treaty required both navies to leave the strait within a year.","cn":"该条约要求两国海军在一年内撤出海峡。"},{"en":"No treaty can bind a state that refuses to ratify it.","cn":"任何条约都无法约束拒绝批准它的国家。"},{"en":"The museum displays the treaty beside the pens used to sign it.","cn":"博物馆把条约与签署时所用的笔并排展出。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「treat（处理）+ y」——把争端反复处理到最后，签下一张纸 → 条约","word":"treaty"},"root":"拉丁 trahere「拉、牵引」，其反复动词 tractare「反复处理、交涉」构成 tractatus「处理、讨论、记述」，经古法语 traite 进入英语。词义由「谈判过程」转为「谈判产生的文书」。trahere 更深来源属重构形式。","sensesIntro":{"en":"Eight senses follow one paper: a bargain is handled until it is written, and the writing then means peace, alliance, any bilateral deal, a text awaiting ratification, a tribal right, the old talking itself, and finally any small truce.","cn":"八个义项沿同一张纸展开：交涉被反复处理直到写成文字，这份文字再指和约、同盟、任何双边协定、待批准的文本、部落权利、旧时的谈判本身，最后指任何小型停战。"},"semanticMap":{"core":{"en":"CORE IMAGE: two parties pulling at a dispute until the pull is fixed in writing and sealed.","cn":"核心意象：两方拉扯一桩争端，直到这股拉力被写进文字并盖章固定。"},"chain":["PULL AND HANDLE","NEGOTIATE","WRITE IT DOWN","BIND THE STATES","RATIFY","SETTLE AFFAIRS"],"branches":[{"senses":"S1 · S7","en":"TALK AND TEXT: the same word once meant the negotiation and now means its written result.","cn":"谈话与文本：同一个词曾指谈判，如今指谈判的书面结果。"},{"senses":"S2 · S3","en":"PAST AND FUTURE: a peace treaty closes a war, an alliance treaty opens a partnership.","cn":"过去与未来：和约结束战争，同盟条约开启伙伴关系。"},{"senses":"S4 · S5","en":"FORM AND PROCEDURE: any subject can be written into the form, and the form waits for ratification.","cn":"形式与程序：任何事项都能写成这种形式，而形式要等待批准。"},{"senses":"S6","en":"TRIBAL SOVEREIGNTY: early diplomacy treated tribes as partners, so their agreements kept the name.","cn":"部落主权：早期外交把部落当作伙伴，因此它们的协议保留了这个名称。"},{"senses":"S8","en":"SMALL TRUCE: the solemn paper is borrowed to make a minor deal sound like a settlement.","cn":"小型停战：庄重的纸页被借来，让一桩小事听起来像正式协定。"}]},"affixes":{"intro":{"en":"Treaty is a past participle turned noun: a pulling root, a frequentative suffix, and a noun ending that English shortened.","cn":"treaty 是由过去分词转成的名词：一个「拉」词根、一个反复后缀，以及英语缩短的名词词尾。"},"latinIntro":{"en":"Trahere gives the root, tractare the frequentative verb, and tractatus the noun that French shortened.","cn":"trahere 提供词根，tractare 是反复动词，tractatus 是被法语缩短的名词。"},"items":[{"word":"trahere","structure":"trahere, traxi, tractum (Latin verb, third conjugation)","meaning":"to pull, draw, drag","meaningCN":"拉；牵引；拖","example":"The root image is physical pulling.","exampleCN":"词根的意象是物理上的拉拽。"},{"word":"-tare","structure":"-tare (Latin frequentative suffix)","meaning":"to do repeatedly","meaningCN":"反复做","example":"The suffix turns one pull into repeated handling.","exampleCN":"这个后缀把一次拉拽变成反复处理。"},{"word":"tractare","structure":"trahere + -tare","meaning":"to handle, discuss, negotiate","meaningCN":"处理；讨论；交涉","example":"Handling a matter repeatedly becomes negotiating it.","exampleCN":"反复处理一件事，就变成对它进行交涉。"},{"word":"-atus","structure":"-atus (Latin noun suffix, action or result)","meaning":"an act or its result","meaningCN":"动作或其结果","example":"The suffix makes tractatus the handling or the record of it.","exampleCN":"这个后缀使 tractatus 指处理行为或其记录。"},{"word":"treaty","structure":"tractatus (through Old French traite)","meaning":"a negotiated written agreement","meaningCN":"经谈判形成的书面协定","example":"The noun moves from talk to paper.","exampleCN":"这个名词从谈话转到纸页。"},{"word":"treat","structure":"traiter (Old French, from tractare)","meaning":"to deal with; to give someone something pleasant","meaningCN":"处理；对待；招待","example":"The verb keeps the original handling sense.","exampleCN":"这个动词保留最初的「处理」义。"},{"word":"-ment","structure":"-mentum (Latin noun suffix, action or result)","meaning":"an action or its result","meaningCN":"动作或其结果","example":"The suffix yields treatment from treat.","exampleCN":"这个后缀由 treat 造出 treatment。"},{"word":"-ise","structure":"-ise (French noun suffix, from Latin -ensis)","meaning":"a written work","meaningCN":"一部著作","example":"The suffix yields treatise, a written handling of a subject.","exampleCN":"这个后缀造出 treatise，即对某一主题的书面处理。"}],"latinEntries":[{"word":"trahere","structure":"trahere, traxi, tractum (verb, third conjugation)","meaning":"to pull, draw, drag","meaningCN":"拉；牵引；拖"},{"word":"tractare","structure":"tractare, tractavi, tractatum (verb, first conjugation)","meaning":"to handle, manage, discuss","meaningCN":"处理；管理；讨论"},{"word":"tractatus","structure":"tractatus, tractatus (m., fourth declension)","meaning":"a handling, discussion, treatise","meaningCN":"处理；讨论；论著"},{"word":"tractus","structure":"tractus, tractus (m., fourth declension)","meaning":"a drawing out, a stretch","meaningCN":"拉长；一片延伸之地"}]}},{"word":"alliance","ipa_uk":"/əˈlaɪəns/","ipa_us":"/əˈlaɪəns/","definition_zh":"联盟；同盟；（国家、政党、企业或家族之间）为共同利益结成的正式联合；联姻","definition_en":"a formal union between states, parties, firms or families who agree to act together for shared interests","core_image":"两艘船的缆绳在同一只铁环上收紧，甲板上的人把两面不同的旗并排插好","scene":"两艘船的缆绳在同一只铁环上收紧，甲板上的人把两面不同的旗并排插好，海峡的风把旗面吹向同一侧。The two small states formed an alliance to keep the strait open to both fleets.","sceneCN":"这里 alliance 指「国家之间为共同防务结成的正式同盟」（第 1 个义项：以条约或承诺固定下来的国家间军事互助关系）；句意为两个小国结成同盟，让海峡对两支舰队同时开放。图中可辨识物件：两条缆绳、一只铁环、两面并排的旗、甲板与海峡。","pos":[{"tag":"n.","zh":"联盟；同盟；联姻（可数，复数 alliances）"}],"collocations":[{"phrase":"form an alliance","zh":"结成联盟"},{"phrase":"military alliance","zh":"军事同盟"},{"phrase":"enter into an alliance","zh":"加入同盟；缔结同盟"},{"phrase":"strategic alliance","zh":"战略联盟"},{"phrase":"in alliance with","zh":"与……结盟"},{"phrase":"break an alliance","zh":"解除同盟"}],"forms":[{"label":"复数","form":"alliances"},{"label":"动词（结盟；联合）","form":"ally"},{"label":"名词（盟友；同盟者）","form":"ally"},{"label":"形容词（结盟的；联合的）","form":"allied"},{"label":"同源名词（联盟；联合会）","form":"league"},{"label":"核心搭配（结成同盟）","form":"form an alliance"}],"derivatives":[{"word":"ally","pos":"v./n.","zh":"结盟；盟友（由古法语 alier「结合」而来，其源头是拉丁 alligare「绑在一起」；动词与名词同形）"},{"word":"allied","pos":"adj.","zh":"结盟的；联合的（ally 加 -ed，指已经被盟约绑在一起的）"},{"word":"league","pos":"n.","zh":"联盟；联合会；联赛（同出拉丁 ligare「绑」，经古法语 ligue 进入英语，与 alliance 同源而不同词）"},{"word":"liable","pos":"adj.","zh":"负有法律责任的；易遭……的（拉丁 ligare 加 -able，字面为「可被绑住的」，由受约束转为承担责任）"},{"word":"ligament","pos":"n.","zh":"韧带（拉丁 ligamentum，由 ligare「绑」加 -mentum，指把骨头绑在一起的组织）"},{"word":"ligature","pos":"n.","zh":"缚线；绑扎；连字（拉丁 ligatura，由 ligare 加 -tura，指绑扎的动作或用来绑的东西）"}],"senses":[{"no":"01","title":"A formal military pact between states","titleCN":"国家之间的正式军事同盟","definition":"a treaty or pledge by which two or more states promise to defend one another or fight a common enemy","definitionCN":"两个或更多国家以条约或承诺约定相互防卫、共同对敌的关系","example":"The two small states formed an alliance to keep the strait open to both fleets.","exampleCN":"两个小国结成同盟，让海峡对两支舰队同时开放。","why":"The Latin verb behind the word means 'to bind to', so the pact is imagined as a rope tied around the parties rather than a mere promise.","whyCN":"这个词背后的拉丁动词意为「绑在……上」，所以盟约被想象成一条绕住双方的绳，而不只是口头承诺。"},{"no":"02","title":"An electoral alliance between parties","titleCN":"政党之间的选举联盟","definition":"an arrangement in which parties agree not to compete against each other and to share power after the vote","definitionCN":"各政党约定互不竞争、并在投票后分享权力的安排","example":"Three parties entered an alliance to contest the election together.","exampleCN":"三个政党结成联盟，共同参加选举。","why":"The binding image transfers easily from armies to organisations that would lose separately but win together.","whyCN":"「绑在一起」的形象很容易从军队转到那些单独会输、合起来能赢的组织。"},{"no":"03","title":"A strategic alliance between firms","titleCN":"企业之间的战略联盟","definition":"a long-term cooperative deal in which competitors share technology, supply chains or markets without merging","definitionCN":"竞争者在不合并的情况下共享技术、供应链或市场的长期合作协议","example":"The airline joined a global alliance to share routes and lounges.","exampleCN":"这家航空公司加入一个全球联盟，以共享航线和休息室。","why":"Because the parties keep their own identities while sharing resources, the word fits business ties better than 'merger' does.","whyCN":"因为各方保留自己的身份而只共享资源，所以这个词比「合并」更适合描述商业上的联结。"},{"no":"04","title":"A dynastic marriage alliance","titleCN":"王朝之间的联姻同盟","definition":"a marriage arranged between ruling houses to secure peace, inheritance or mutual support","definitionCN":"统治家族之间为换取和平、继承权或相互支持而安排的婚姻","example":"The marriage was an alliance between two royal houses, not a love match.","exampleCN":"这桩婚姻是两个王室之间的联盟，而不是恋爱结合。","why":"Before standing armies, a wedding was the cheapest way to tie two dynasties together, so the same noun also named the married couple.","whyCN":"在常备军出现之前，一场婚礼是把两个王朝绑在一起最便宜的办法，因此同一个名词也指联姻的双方。"},{"no":"05","title":"A temporary alliance around one issue","titleCN":"围绕单一议题的临时联盟","definition":"a short-lived bloc of groups that combine only to pass or block a particular measure","definitionCN":"只在推动或阻止某一具体议案时才联合起来的短暂集团","example":"Farmers and environmentalists formed an unlikely alliance over the water bill.","exampleCN":"农民与环保人士围绕水费议案结成了一个出人意料的联盟。","why":"The binding can be loosened again once the vote is over, which shows the word does not require permanent friendship.","whyCN":"投票一结束，这条绳就可以松开，这说明这个词并不要求双方永久友好。"},{"no":"06","title":"The abstract state of being allied","titleCN":"抽象的结盟状态与同盟关系","definition":"the condition of standing together, used without naming any particular treaty or bloc","definitionCN":"站在一起的状况，不特指某一纸条约或某个集团","example":"Their alliance survived three changes of government on both sides.","exampleCN":"他们的同盟关系挺过了双方各自三次政府更迭。","why":"When the paper is forgotten, what remains is a relationship, and the noun then names the relationship rather than the instrument.","whyCN":"当纸面文件被淡忘，剩下的是一种关系，于是这个名词命名的是关系本身而非文书。"},{"no":"07","title":"An alliance of organisations or networks","titleCN":"组织或网络构成的联盟","definition":"a federation of clubs, charities, unions or platforms that coordinate action while keeping separate members","definitionCN":"由俱乐部、慈善机构、工会或平台组成、协调行动而各成员仍独立的联合体","example":"The alliance of coastal towns lobbied together for flood defences.","exampleCN":"沿海城镇组成的联盟共同游说修建防洪设施。","why":"The same knot now holds many cords at once, so the word moves from two parties to a whole network.","whyCN":"同一个结现在同时系住许多条绳，于是这个词从两方扩展到整个网络。"},{"no":"08","title":"A figurative alliance of ideas or interests","titleCN":"比喻：观念或利益的同盟","definition":"a loosened use for any pairing of ideas, habits or interests that seem to support each other","definitionCN":"较松散的用法，指相互支撑的观念、习惯或利益的任何配对","example":"There is an odd alliance between thrift and vanity in his spending.","exampleCN":"他的花销里有一种节俭与虚荣的奇特同盟。","why":"The metaphor keeps only the shape of two things holding together, with no parties, no treaty and no flags.","whyCN":"这个比喻只保留「两样东西互相系住」的形状，没有缔约方、没有条约，也没有旗帜。"}],"etymology":{"intro":{"en":"Alliance comes through Old French from the Latin verb alligare, 'to bind to', built from ad- and ligare 'bind'. The same ligare stock also yields league, liable and ligament.","cn":"alliance 经古法语来自拉丁动词 alligare「绑在……上」，由 ad- 加 ligare「绑」构成。同一个 ligare 词族还衍生出 league、liable、ligament。"},"items":[{"era":"LATIN LIGARE","en":"Ligare meant 'to bind, tie, fasten'; it is the source of the whole knot of words, and the same stock also gives ligament.","cn":"ligare 意为「绑、系、缚」；它是整组词的核心来源，同一词族也衍生出 ligament。"},{"era":"LATIN ALLIGARE","en":"Ad- 'to, toward' plus ligare produced alligare, 'to bind something to something else', the direct ancestor of the English family.","cn":"ad-「向、朝」加 ligare 构成 alligare「把某物绑到另一物上」，是英语这一族词的直接祖源。"},{"era":"FRENCH ALIER","en":"Old French alier reduced alligare to a verb meaning 'to join, unite', and English took it as ally.","cn":"古法语 alier 把 alligare 简化为表示「结合、联合」的动词，英语借入后成为 ally。"},{"era":"FRENCH ALIANCE","en":"The French noun aliance named both the act of binding and the group so bound; English borrowed it in the fourteenth century.","cn":"法语名词 aliance 既指绑扎的动作，也指被绑在一起的一方；英语在十四世纪借入。"},{"era":"ENGLISH ALLIANCE","en":"English widened the noun from a bond between rulers to parties, firms, clubs and eventually any pairing of interests.","cn":"英语把这个名词从统治者之间的联结，扩展到政党、企业、俱乐部，最终扩展到任何利益的配对。"},{"era":"UNCERTAIN SOURCE","en":"Source uncertain: the deeper origin of ligare is a reconstruction, and no single earlier root is agreed.","cn":"来源不确定：ligare 更深层的来源属重构形式，尚无公认的更早词根。"}]},"similar":{"note":{"en":"Group one holds forms built on the same binding root that are easily mistaken for one another; group two holds unions that differ in permanence, scope or tone.","cn":"第一组是同出「绑」词根、容易被混用的形式；第二组是持久性、范围或语气不同的联合体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ally","ipa":"/əˈlaɪ/","tag":"same root, a party not the pact","definition":"A state or person joined to another; it names one member of the union, while alliance names the union itself.","definitionCN":"指加入另一方的国家或个人；它命名同盟中的一员，而 alliance 命名同盟本身。"},{"word":"league","ipa":"/liːɡ/","tag":"same root, separate borrowing","definition":"From the same ligare through Old French ligue; it often names a sports or political federation with its own rules.","definitionCN":"同出 ligare，经古法语 ligue 借入；常指有自身规则的体育或政治联合会。"},{"word":"liable","ipa":"/ˈlaɪəbl/","tag":"same root, legal duty","definition":"Literally 'able to be bound', it now means answerable in law; there is no union and no partner.","definitionCN":"字面为「可被绑住的」，如今指在法律上负有责任；既无联合体，也无伙伴。"},{"word":"ligament","ipa":"/ˈlɪɡəmənt/","tag":"same root, anatomy","definition":"A band that binds bone to bone; the root is physical here and carries no political sense.","definitionCN":"把骨与骨绑在一起的带状组织；此处词根是物理意义，没有政治含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"coalition","ipa":"/kəˈlɪʃən/","tag":"temporary common front","definition":"A union of groups that keep their differences and act together for one purpose, often short-lived; an alliance can be long-term.","definitionCN":"各团体保留分歧、为单一目的共同行动的联合，常较短暂；alliance 可以是长期的。"},{"word":"confederation","ipa":"/kənˌfedəˈreɪʃən/","tag":"loose permanent union","definition":"A permanent union of states or bodies that delegate limited powers to a centre while keeping sovereignty.","definitionCN":"国家或机构把有限权力交给中心、同时保留主权的永久联合。"},{"word":"pact","ipa":"/pækt/","tag":"the agreement itself","definition":"The agreement, often informal and between two parties; alliance stresses the standing union rather than the document.","definitionCN":"指协议本身，常较非正式且限于两方；alliance 侧重持续的联合而非文书。"},{"word":"entente","ipa":"/ɒnˈtɒnt/","tag":"friendly understanding","definition":"A friendly understanding between states with no binding military duty, looser than a full alliance.","definitionCN":"国家之间没有约束性军事义务的友好谅解，比完整同盟更松。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ligare 'bind' plus ad- 'to' gives 'bind to': an alliance is two parties tied to each other, and the knot is the treaty.","cn":"ligare「绑」加 ad-「向」就是「绑到……上」：alliance 是两方互相系住，那个结就是条约。"},{"en":"The family runs ligare, alligare, ally, allied, alliance, league, liable, ligament.","cn":"同族词依次是 ligare、alligare、ally、allied、alliance、league、liable、ligament。"},{"en":"Fixed collocations mark the stages: form an alliance, enter into an alliance, break an alliance.","cn":"固定搭配标出阶段：结成同盟、加入同盟、解除同盟。"},{"en":"One knot, many scales: states, parties, airlines, royal houses and coastal towns all use the same word.","cn":"一个结，多种尺度：国家、政党、航空公司、王室与沿海城镇都用同一个词。"},{"en":"The near neighbours differ in grip: a coalition is temporary, a confederation permanent, an entente friendly but unarmed.","cn":"近义词的抓握程度不同：coalition 短暂，confederation 永久，entente 友好但不带武装义务。"}],"abstract":[{"en":"Picture two ropes pulled through one iron ring until the ring cannot slip.","cn":"想象两条绳穿过同一只铁环，被拉到铁环再也滑不动。"},{"en":"Picture two flags on one mast, each flying in a different colour but turning with the same wind.","cn":"想象一根桅杆上挂两面旗，颜色不同，却随同一阵风转向。"},{"en":"Picture a knot that stays tied even after the two boats have drifted apart.","cn":"想象两条船已经漂开，那个结却仍然没有松。"}]},"examples":[{"en":"The alliance collapsed when one member signed a separate peace.","cn":"一名成员单独签订和约后，这个同盟瓦解了。"},{"en":"Small parties often gain more from an alliance than from running alone.","cn":"小党从联盟中得到的，往往比单独参选更多。"},{"en":"Historians describe the marriage as an alliance sealed with a dowry.","cn":"历史学家把这桩婚姻描述为以嫁妆加固的联盟。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「a（啊）+ lli（连）+ ance（安斯）」——彼此连住、安稳不放 → 同盟","word":"alliance"},"root":"拉丁 ligare「绑、系」经 ad- 加 ligare 构成 alligare「绑在一起」，再经古法语 alier、aliance 进入英语；alliance 与 ally 同源，并非 alli- 加 -ance 的独立词根。ligare 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one knot: two parties are bound together, and that binding is then read as a war pact, an election pact, a corporate deal, a marriage, a temporary front, a standing condition, a network, and finally a tie between ideas.","cn":"八个义项沿同一个结展开：两方被绑在一起，这个结再依次被读作战争同盟、选举联盟、企业合作、王朝联姻、临时战线、持久关系、组织网络，最后是观念之间的联结。"},"semanticMap":{"core":{"en":"CORE IMAGE: two cords pulled tight through one iron ring, each end flying a different flag.","cn":"核心意象：两条绳穿过同一只铁环被拉紧，两端各飘着一面不同的旗。"},"chain":["BIND TWO PARTIES","PLEDGE MUTUAL SUPPORT","MARRY THE HOUSES","JOIN FOR ONE CAUSE","STAND TOGETHER","ANY SHARED INTEREST"],"branches":[{"senses":"S1 · S2","en":"SHOT AND BALLOT: the pact between armies and the pact between parties are the same knot at two scales (S1, S2).","cn":"枪炮与选票：军队之间的盟约与政党之间的盟约，是同一个结的两种尺度（义项一、二）。"},{"senses":"S3 · S4","en":"CONTRACT AND MARRIAGE: firms pool markets and dynasties pool bloodlines, both by the same binding (S3, S4).","cn":"合同与婚姻：企业共享市场，王朝共享血统，靠的都是同一种绑缚（义项三、四）。"},{"senses":"S5 · S6","en":"CAUSE AND CONDITION: a temporary front around one bill fades into the standing fact of being allied (S5, S6).","cn":"议题与状态：围绕某一议案的临时战线，会沉淀为持久的结盟事实（义项五、六）。"},{"senses":"S7","en":"NETWORK: federations, unions and platforms tie many members to one centre while each keeps its own name (S7).","cn":"网络：联合会、工会与平台把许多成员系向一个中心，而各成员保留自己的名字（义项七）。"},{"senses":"S8","en":"METAPHOR: ideas and interests can be tied too, with no signature and no flags (S8).","cn":"比喻：观念与利益也能被系在一起，既无签名，也无旗帜（义项八）。"}]},"affixes":{"intro":{"en":"Alliance is a prefixed Latin verb turned French noun: a directional prefix, a binding root, and a noun ending for a state or act.","cn":"alliance 是加前缀的拉丁动词转成的法语名词：一个方向前缀、一个「绑」词根，以及表示状态或动作的名词词尾。"},"latinIntro":{"en":"Ligare supplies the root, ad- plus ligare makes alligare, and French shortened that verb to alier before adding its noun ending.","cn":"ligare 提供词根，ad- 加 ligare 构成 alligare，法语把这个动词缩为 alier，再加自己的名词词尾。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, toward')","meaning":"to; toward","meaningCN":"向；朝","example":"The prefix points the binding toward a second party.","exampleCN":"这个前缀把「绑」的方向指向另一方。"},{"word":"ligare","structure":"ligare, ligavi, ligatum (Latin verb, first conjugation)","meaning":"to bind, tie, fasten","meaningCN":"绑；系；缚","example":"The root image is a cord pulled around two objects.","exampleCN":"词根的意象是一条绳绕住两件东西被拉紧。"},{"word":"alligare","structure":"ad- + ligare","meaning":"to bind one thing to another","meaningCN":"把一物绑到另一物上","example":"The compound turns a simple tie into a tie between parties.","exampleCN":"这个复合形式把单纯的绑扎变成两方之间的联结。"},{"word":"alier","structure":"alier (Old French verb, from Latin alligare)","meaning":"to join, unite","meaningCN":"结合；联合","example":"French softened the consonant and kept the sense of joining.","exampleCN":"法语软化了辅音，保留了「结合」的意思。"},{"word":"-ance","structure":"-ance (French noun suffix, from Latin -antia)","meaning":"a state or an act","meaningCN":"状态或动作","example":"The suffix turns the verb of joining into the name of the union.","exampleCN":"这个后缀把表示结合的动词变成联合这一状态的名称。"},{"word":"aliance","structure":"alier + -ance (Old French noun)","meaning":"a binding together; the group so bound","meaningCN":"绑在一起；被绑在一起的一方","example":"The French noun already carried both the act and the group.","exampleCN":"这个法语名词已经同时指动作和由此形成的一方。"},{"word":"alliance","structure":"aliance (Old French, borrowed into English)","meaning":"a union formed by agreement","meaningCN":"经约定形成的联合","example":"English kept the noun and widened its range.","exampleCN":"英语保留了这个名词，并扩大了它的适用范围。"},{"word":"ally","structure":"alier (Old French verb and participle)","meaning":"to join; one who is joined","meaningCN":"联合；被联合的一方","example":"The verb and the person share one French source.","exampleCN":"动词与「盟友」这个人称名词共用一个法语来源。"},{"word":"ligament","structure":"ligare + -mentum (Latin)","meaning":"that which binds","meaningCN":"用来绑缚之物","example":"The same root names the band that holds bones together.","exampleCN":"同一个词根命名把骨头系在一起的那条带。"}],"latinEntries":[{"word":"ligare","structure":"ligare, ligavi, ligatum (verb, first conjugation)","meaning":"to bind, tie, fasten","meaningCN":"绑；系；缚"},{"word":"alligare","structure":"alligare, alligavi, alligatum (verb, first conjugation)","meaning":"to bind to, fasten to","meaningCN":"绑到……上；系在……上"},{"word":"ligamentum","structure":"ligamentum, ligamenti (n., second declension)","meaning":"a band, ligament","meaningCN":"带；韧带"},{"word":"ligatura","structure":"ligatura, ligaturae (f., first declension)","meaning":"a binding, ligature","meaningCN":"绑扎；缚线；连字"}]}},{"word":"diplomatic","ipa_uk":"/ˌdɪpləˈmætɪk/","ipa_us":"/ˌdɪpləˈmætɪk/","definition_zh":"外交的；外交官的；讲究策略、圆融得体的；外交文书或渠道的；有手腕的","definition_en":"relating to the management of relations between states, and by extension showing tact and skill in handling people or delicate matters","core_image":"一张对折的厚纸在使者手中展开，折痕上压着湿印泥，门外两方随从各站一侧","scene":"长桌两端各摆一面小旗，中间的文书分成几叠，随从退到门边，谁开口前都先看一眼对面。The minister opened the diplomatic talks with a carefully neutral statement.","sceneCN":"这里 diplomatic 指「与国与国之间的交涉事务相关的」（第 1 个义项：属于国家间谈判、往来与交涉范畴的）；句意为部长用一句刻意中立的开场话启动了这场外交会谈。图中可辨识物件：长桌、两面小旗、成叠文书、退到门边的随从。","pos":[{"tag":"adj.","zh":"外交的；外交官的；圆融的；有手腕的"}],"collocations":[{"phrase":"diplomatic relations","zh":"外交关系"},{"phrase":"diplomatic immunity","zh":"外交豁免权"},{"phrase":"diplomatic channels","zh":"外交渠道"},{"phrase":"diplomatic solution","zh":"外交解决方案"},{"phrase":"diplomatic note","zh":"外交照会；外交文书"},{"phrase":"the diplomatic corps","zh":"外交使团"}],"forms":[{"label":"比较级","form":"more diplomatic"},{"label":"最高级","form":"most diplomatic"},{"label":"副词（圆融地；以外交方式）","form":"diplomatically"},{"label":"名词（外交官）","form":"diplomat"},{"label":"名词（外交；外交手腕）","form":"diplomacy"},{"label":"形容词（不圆融的）","form":"undiplomatic"},{"label":"同源名词（公文；文凭）","form":"diploma"}],"derivatives":[{"word":"diplomat","pos":"n.","zh":"外交官（由 diplomatic 逆构、去掉后缀而来，语义由「外交的」收窄为从事外交的人）"},{"word":"diplomacy","pos":"n.","zh":"外交；外交手腕（经法语 diplomatie，由 diplomatique 加 -ie 构成，语义由形容词转为行业与技艺名词）"},{"word":"diplomatically","pos":"adv.","zh":"圆融地；通过外交途径（diplomatic 加 -ly，语义由性质转为方式）"},{"word":"undiplomatic","pos":"adj.","zh":"不圆融的；不得体的（un- 加 diplomatic，语义加否定，指缺少分寸）"},{"word":"diploma","pos":"n.","zh":"文凭；公文（希腊 diploma「对折的纸」经拉丁 diploma 而来，与「外交」义同源而分道）"}],"senses":[{"no":"01","title":"Relating to dealings between states","titleCN":"与国家间交涉事务相关的","definition":"belonging to the conduct of official relations between governments, including talks, notes and visits","definitionCN":"属于政府之间官方关系的处理，包括会谈、照会与访问","example":"The minister opened the diplomatic talks with a carefully neutral statement.","exampleCN":"部长用一句刻意中立的开场话启动了这场外交会谈。","why":"The word began as the adjective of the credential that accredited an envoy, so it first describes the official channel between states.","whyCN":"这个词最初是委派使节所用凭证的形容词，因此最先描述国家之间的官方渠道。"},{"no":"02","title":"Tactful in handling people","titleCN":"与人打交道时讲究分寸、圆融的","definition":"skilled at saying difficult things without giving offence or exposing anyone to humiliation","definitionCN":"善于把难说的话说出来而不冒犯他人、不使任何人难堪","example":"She gave a diplomatic answer about her colleague's lateness.","exampleCN":"她对同事迟到一事给了一个很圆融的回答。","why":"Negotiators must save faces on both sides, so their professional manner became the model for any tactful person.","whyCN":"谈判者必须顾全双方的面子，因此他们的职业作风成了任何圆融之人的样板。"},{"no":"03","title":"Of official notes and channels","titleCN":"属于外交文书与外交渠道的","definition":"describing the written messages, formal protests and established routes through which governments communicate","definitionCN":"描述政府之间沟通所用的书面信息、正式抗议与既定途径","example":"The protest was delivered as a diplomatic note rather than a press statement.","exampleCN":"这项抗议是以外交照会而非新闻声明的方式递交的。","why":"The original Greek word named a folded document, so documents remained the most literal kind of diplomatic object.","whyCN":"最早的希腊词指一张对折的文书，因此文书始终是最字面意义上的外交物件。"},{"no":"04","title":"Of embassy staff and the corps","titleCN":"属于使馆外交人员的","definition":"relating to accredited officials serving in an embassy, their ranks and their families","definitionCN":"指在使馆任职的持证官员、其等级与家属","example":"The diplomatic staff were evacuated before the embassy closed.","exampleCN":"使馆关闭前，外交人员已经撤离。","why":"Because the credential made a person 'diplomatic', the adjective attached to people and then to the whole resident staff.","whyCN":"因为凭证使一个人成为「外交的」，这个形容词便附着于人，进而指整个驻馆人员。"},{"no":"05","title":"Relating to immunity and privileges","titleCN":"涉及外交豁免与礼遇的","definition":"pertaining to the legal protections, tax exemptions and ceremonial courtesies granted to envoys","definitionCN":"指给予使节的法律保护、税收豁免与礼仪优待","example":"The car carried diplomatic plates and could not be searched.","exampleCN":"那辆车挂着外交牌照，不能被搜查。","why":"The same credential that admitted an envoy also shielded him, so privileges grew into a distinct use of the adjective.","whyCN":"准许使节入境的同一份凭证也保护了他，于是特权发展为这个形容词的独立用法。"},{"no":"06","title":"Delicate handling of a difficult matter","titleCN":"处理棘手事务时得体的","definition":"describing a move that avoids confrontation, keeps options open and leaves the other party room to retreat","definitionCN":"描述一种避免对抗、保留余地、给对方留退路的做法","example":"A diplomatic silence was the only safe response to the question.","exampleCN":"对这个提问，外交式的沉默是唯一安全的回应。","why":"Tact is not only politeness; it is the calculation of how much can be said without closing a door.","whyCN":"分寸不只是礼貌，它还是计算「说多少才不至于关上某扇门」。"},{"no":"07","title":"Of a negotiated rather than forceful solution","titleCN":"指以外交谈判而非武力解决的","definition":"describing a settlement reached by talks, sanctions or mediation instead of armed action","definitionCN":"描述通过谈判、制裁或斡旋、而非军事行动达成的解决","example":"The crisis ended in a diplomatic settlement, not a military one.","exampleCN":"这场危机以外交方式而非军事方式收场。","why":"When the adjective modifies 'solution', it names the whole method, setting negotiation against the use of force.","whyCN":"当这个形容词修饰「解决方案」时，它命名的是整套方法，把谈判与动武对立起来。"},{"no":"08","title":"Calculated, with an edge of cunning","titleCN":"引申为有手腕的，有时带算计意味","definition":"an ironic or critical use for behaviour that is too smooth, too carefully arranged to be sincere","definitionCN":"讽刺或批评用法，指过于圆滑、安排得过于周到而显得不真诚的举止","example":"His diplomatic smile suggested he had already decided and would not say so.","exampleCN":"他那个外交式的微笑说明他早已有定论，只是不打算说出来。","why":"The nineteenth-century taste for tact acquired a shadow: skill in managing people can look like management of them.","whyCN":"十九世纪对分寸的推崇带来一层阴影：善于应对他人，也可能看起来像是在操控他人。"}],"etymology":{"intro":{"en":"Diplomatic goes back to Greek diploma, a paper folded in two, then to the Latin document that accredited an envoy, and through French to the modern adjective. The tact sense is a nineteenth-century extension.","cn":"diplomatic 可追到希腊 diploma「对折的纸」，再经指委派使节文书的拉丁 diploma，并通过法语成为现代形容词。圆融义是十九世纪的引申。"},"items":[{"era":"GREEK DIPLOUN","en":"Diploun meant 'to fold', from diploos 'twofold'; a diploma was literally a sheet folded double.","cn":"diploun 意为「折」，源自 diploos「双重的」；diploma 字面上就是一张对折的纸。"},{"era":"GREEK DIPLOMA","en":"The Greek noun named a folded document and later a letter of recommendation carried by an envoy.","cn":"这个希腊名词指对折的文书，后指使节随身携带的推荐信。"},{"era":"LATIN DIPLOMA","en":"Latin borrowed diploma for an official document, including travel warrants and credentials issued to envoys.","cn":"拉丁借入 diploma 指官方文书，包括旅行许可与发给使节的委任凭证。"},{"era":"FRENCH DIPLOMATIQUE","en":"French built diplomatique on the Latin noun; the adjective described matters handled through such credentials and envoys.","cn":"法语在拉丁名词基础上造出 diplomatique；这个形容词描述通过此类凭证与使节处理的事务。"},{"era":"ENGLISH DIPLOMATIC","en":"English borrowed the adjective in the eighteenth century for state-to-state business, and by the nineteenth it also meant tactful personal conduct.","cn":"英语在十八世纪借入这个形容词，指国家间事务；到十九世纪，它也指个人处事圆融。"},{"era":"UNCERTAIN DATES","en":"Source uncertain (first dates only): the exact moment when the tact sense appeared is not recorded, and the link from credential to conduct is generally accepted rather than fully documented.","cn":"来源不确定（仅首见年代）：圆融义确切出现的时点没有记载；从「凭证」到「举止」的关联一般认为成立，但缺乏完整书证。"}]},"similar":{"note":{"en":"Group one holds same-root words that look almost identical but name different things; group two holds adjectives close in meaning but different in degree and motive.","cn":"第一组是同根、外形几乎相同却指不同事物的词；第二组是含义接近但程度与动机不同的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"diploma","ipa":"/dɪˈpləʊmə/","tag":"same root, a paper","definition":"The folded document itself, now usually a certificate of study; it has no tactful or political sense.","definitionCN":"指那张对折的文书本身，如今多指学业证书；它没有圆融或政治含义。"},{"word":"diplomat","ipa":"/ˈdɪpləmæt/","tag":"same root, a person","definition":"A person accredited to represent a state abroad; the adjective describes the field, the noun names the official.","definitionCN":"指受委派代表国家驻外的人；形容词描述领域，名词命名官员。"},{"word":"diplomacy","ipa":"/dɪˈpləʊməsi/","tag":"same root, the craft","definition":"The activity or skill of conducting relations; it is the noun of the field rather than a quality of a person.","definitionCN":"指处理关系的活动或技艺；它是领域名词，而非形容人的品质。"},{"word":"diplomatics","ipa":"/dɪˈplɒmətɪks/","tag":"same root, document studies","definition":"The scholarly study of old official documents, a different branch built on the same folded-paper root.","definitionCN":"指对古代官方文书的学术研究，是同出「对折纸」词根的另一个分支。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tactful","ipa":"/ˈtæktfəl/","tag":"personal skill","definition":"Careful not to hurt feelings; it is about social sensitivity, with no reference to states or envoys.","definitionCN":"指小心不伤感情，侧重社交敏感，不涉及国家或使节。"},{"word":"discreet","ipa":"/dɪˈskriːt/","tag":"keeping quiet","definition":"Careful to keep a secret or avoid notice; diplomatic may be outspoken, discreet must not be.","definitionCN":"指谨慎保守秘密或不引人注意；圆融的人可以明说，谨慎的人则不能。"},{"word":"politic","ipa":"/ˈpɒlətɪk/","tag":"prudent calculation","definition":"A formal word for a wise, calculated move; it stresses advantage rather than courtesy.","definitionCN":"正式用语，指明智而有计算的举动；侧重利益而非礼貌。"},{"word":"suave","ipa":"/ˈswɑːv/","tag":"smooth surface","definition":"Smooth and agreeable in manner, often with a hint of insincerity; it describes the surface, not the strategy.","definitionCN":"指举止圆滑讨喜，常暗示不够真诚；它描述表面，而非策略。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The core image is a paper folded in two: a credential, not a certificate of study, is what made an envoy diplomatic.","cn":"核心意象是一张对折的纸：使节之所以「外交」，凭的是这份凭证，而不是学业证书。"},{"en":"The family runs diploma, diplomat, diplomacy, diplomatic, diplomatically, undiplomatic.","cn":"同族词依次是 diploma、diplomat、diplomacy、diplomatic、diplomatically、undiplomatic。"},{"en":"Fixed collocations mark the field: diplomatic relations, diplomatic immunity, diplomatic channels, diplomatic note.","cn":"固定搭配标出这一领域：外交关系、外交豁免、外交渠道、外交照会。"},{"en":"Two senses split late: official state business kept the adjective, and personal tact borrowed its prestige in the nineteenth century.","cn":"两个义项分化较晚：官方国家事务保留了这个形容词，个人分寸则在十九世纪借用了它的声望。"},{"en":"Near words differ in motive: tactful cares about feelings, discreet about silence, politic about advantage, suave about impression.","cn":"近义词动机不同：tactful 在意感受，discreet 在意沉默，politic 在意利益，suave 在意印象。"}],"abstract":[{"en":"Picture a thick sheet folded once, with a wax seal pressed exactly on the crease.","cn":"想象一张厚纸对折一次，火漆印章正好压在折痕上。"},{"en":"Picture two negotiators passing a single folded note back and forth across a long table.","cn":"想象两名谈判者在长桌两头，把同一张对折的便笺来回递送。"},{"en":"Picture a door held half open, wide enough for talk and narrow enough for retreat.","cn":"想象一扇门只开到一半，宽到足以交谈，窄到足以退回。"}]},"examples":[{"en":"Both governments agreed to resolve the dispute through diplomatic means.","cn":"两国政府同意通过外交手段解决这场争端。"},{"en":"It was a diplomatic way of saying that the plan would never work.","cn":"那是一种圆融的说法，意思是这个计划根本行不通。"},{"en":"The delegation lost its diplomatic status after the recall.","cn":"召回之后，该代表团失去了外交身份。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「diplo（对折）+ matic」——纸对折，话也留一层 → 外交的；圆融的","word":"diplomatic"},"root":"希腊 diploma「对折的纸」，源自 diploun「折」；经拉丁 diploma「公文、通行凭证」进入法语 diplomatique，再由英语借入。「外交」义由「折叠公文/凭证」引申，与「文凭」义同源而分道；圆融义为十九世纪引申。","sensesIntro":{"en":"Eight senses follow one folded credential: a paper folded in two accredited an envoy, and from that paper the word spread to state business, to documents and embassies, to legal privilege, to delicate handling, to negotiated settlements, and finally to a suspiciously smooth manner.","cn":"八个义项沿同一份对折的凭证展开：一张对折的纸委派了使节，从这个纸页出发，词义扩展到国家事务、文书与使馆、法律特权、棘手事务的分寸、谈判解决，最后是圆滑得令人生疑的举止。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet folded once and sealed, handed across a threshold by someone authorized to speak for a state.","cn":"核心意象：一张对折并盖印的纸，由获授权代表国家发言的人递过门槛。"},"chain":["FOLD THE PAPER","ACCREDIT THE ENVOY","SPEAK FOR THE STATE","KEEP THE CHANNEL","SAVE BOTH FACES","SETTLE WITHOUT FORCE"],"branches":[{"senses":"S1 · S3","en":"PAPER AND STATE: the folded document accredits the talk, so the document sense and the state-business sense share one origin (S1, S3).","cn":"纸页与国家：对折的文书为谈判授权，因此文书义与国家事务义共享同一来源（义项一、三）。"},{"senses":"S2 · S6","en":"FACE-SAVING: tactful talk in ordinary life and delicate handling of a crisis are the same skill at different stakes (S2, S6).","cn":"顾全面子：日常的圆融与危机中的分寸，是同一种本事在不同赌注下（义项二、六）。"},{"senses":"S4 · S5","en":"PEOPLE AND PRIVILEGE: accredited staff and the protections they carry are two faces of the same credential (S4, S5).","cn":"人员与特权：持证人员与他们携带的保护，是同一份凭证的两面（义项四、五）。"},{"senses":"S7","en":"METHOD: when talks replace force, the adjective names the whole way of settling a dispute (S7).","cn":"方法：当谈判取代武力，这个形容词命名的就是整套解决争端的方式（义项七）。"},{"senses":"S8","en":"SHADOW: skill in managing people can be read as management of them, and the adjective turns ironic (S8).","cn":"阴影：善于应对他人可被读作操控他人，这个形容词便转为讽刺（义项八）。"}]},"affixes":{"intro":{"en":"Diplomatic is an adjective built on a noun of folded paper, with a Greek folding root and a Latin relational suffix carried through French.","cn":"diplomatic 是建立在「对折的纸」这一名词上的形容词，带一个希腊「折」词根和一个经法语传来的拉丁关系后缀。"},"latinIntro":{"en":"Greek diploun and diploma give the image and the noun, Latin diploma and diplomaticus give the official and adjectival forms.","cn":"希腊 diploun 与 diploma 提供意象与名词，拉丁 diploma 与 diplomaticus 提供公文形式与形容词形式。"},"items":[{"word":"diploun","structure":"diploun (Greek verb, 'to fold')","meaning":"to fold; to double","meaningCN":"折叠；使成双","example":"The verb supplies the physical act behind the whole family.","exampleCN":"这个动词提供了整族词背后的物理动作。"},{"word":"diploma","structure":"diploma, diplomatis (Greek noun, later Latin noun)","meaning":"a paper folded in two; an official document","meaningCN":"对折的纸；官方文书","example":"The noun moves from a folded sheet to a credential.","exampleCN":"这个名词从一张对折纸转到一份凭证。"},{"word":"-aticus","structure":"-aticus (Medieval Latin adjectival suffix, 'relating to')","meaning":"relating to; of the nature of","meaningCN":"与……相关的；具……性质的","example":"The suffix turns the document noun into an adjective of the field.","exampleCN":"这个后缀把文书名词变成该领域的形容词。"},{"word":"diplomaticus","structure":"diploma + -aticus (Medieval Latin)","meaning":"relating to official documents and envoys","meaningCN":"与官方文书及使节相关的","example":"The medieval adjective already pointed toward state business.","exampleCN":"这个中世纪形容词已经指向国家事务。"},{"word":"diplomatique","structure":"diplomaticus (French adjective)","meaning":"relating to envoys and state papers","meaningCN":"与使节和国家文书相关的","example":"French reshaped the Latin adjective into its modern form.","exampleCN":"法语把这个拉丁形容词改造成现代形式。"},{"word":"diplomatic","structure":"diplomatique (French, borrowed into English)","meaning":"of state relations; tactful","meaningCN":"国家关系的；圆融的","example":"English added the tact sense to the official one.","exampleCN":"英语在官方义之外增加了圆融义。"},{"word":"diplomat","structure":"diplomatic (back-formation)","meaning":"an accredited representative","meaningCN":"持证代表；外交官","example":"The person noun was cut back from the adjective.","exampleCN":"这个指人的名词是由形容词逆构而来。"},{"word":"diplomacy","structure":"diplomatique + -ie (French noun)","meaning":"the craft of conducting relations","meaningCN":"处理国家关系的技艺","example":"French made the adjective into the name of the craft.","exampleCN":"法语把这个形容词变成这门技艺的名称。"}],"latinEntries":[{"word":"diploma","structure":"diploma, diplomatis (n., third declension)","meaning":"an official document, a letter of recommendation","meaningCN":"官方文书；推荐信"},{"word":"diplomaticus","structure":"diplomaticus, diplomatica, diplomaticum (adj., first and second declension)","meaning":"relating to official documents","meaningCN":"与官方文书相关的"}]}},{"word":"diplomacy","ipa_uk":"/dɪˈpləʊməsi/","ipa_us":"/dɪˈploʊməsi/","definition_zh":"外交；外交实务；外交手腕；外交界；（喻）交际策略","definition_en":"the conduct of relations between states through negotiation and contact, and the skill of managing such relations without giving offence","core_image":"长桌两侧各坐一人，桌上摊着几张对折的文书，桌下两双脚都没有后退","scene":"长桌两侧各坐一人，桌上摊着几张对折的文书，侍者退到门边，谁也没有先起身。Quiet diplomacy kept the two delegations talking through the winter.","sceneCN":"这里 diplomacy 指「以持续谈判与往来处理国家间关系的实务」（第 1 个义项：通过接触而非武力处理对外关系的方式）；句意为静默外交让两个代表团在整个冬天都保持对话。图中可辨识物件：长桌、对折的文书、两侧的座椅、退到门边的侍者。","pos":[{"tag":"n.","zh":"外交；外交实务；外交手腕；外交界（不可数；指具体的外交活动时可数，复数 diplomacies）"}],"collocations":[{"phrase":"international diplomacy","zh":"国际外交"},{"phrase":"quiet diplomacy","zh":"静默外交；低调外交"},{"phrase":"shuttle diplomacy","zh":"穿梭外交"},{"phrase":"public diplomacy","zh":"公共外交"},{"phrase":"multilateral diplomacy","zh":"多边外交"},{"phrase":"conduct diplomacy","zh":"开展外交"}],"forms":[{"label":"复数","form":"diplomacies"},{"label":"名词（外交官）","form":"diplomat"},{"label":"形容词（外交的；圆融的）","form":"diplomatic"},{"label":"副词（圆融地）","form":"diplomatically"},{"label":"形容词（不圆融的）","form":"undiplomatic"},{"label":"同源名词（文凭；公文）","form":"diploma"},{"label":"核心搭配（穿梭外交）","form":"shuttle diplomacy"}],"derivatives":[{"word":"diplomat","pos":"n.","zh":"外交官（由 diplomatic 逆构而来，语义由「外交的」收窄为执行外交的人）"},{"word":"diplomatic","pos":"adj.","zh":"外交的；圆融的（经法语 diplomatique，由拉丁 diploma 加关系后缀，语义由文书转到国家事务与分寸）"},{"word":"diplomatically","pos":"adv.","zh":"圆融地；以外交方式（diplomatic 加 -ly，语义由性质转为方式）"},{"word":"undiplomatic","pos":"adj.","zh":"不圆融的；直来直去的（un- 加 diplomatic，语义加否定，指缺少分寸）"},{"word":"diplomatist","pos":"n.","zh":"外交家；外交事务专家（diplomatic 加 -ist，旧式说法，语义由性质转为人与职业）"},{"word":"diploma","pos":"n.","zh":"文凭；公文（希腊 diploma「对折的纸」，语义由折叠文书转到证书，与外交实务分道）"}],"senses":[{"no":"01","title":"The conduct of relations between states","titleCN":"处理国家间关系的实务","definition":"the ongoing work of managing contact between governments through talks, representation and agreement rather than force","definitionCN":"通过会谈、派驻代表与达成协议而非武力来处理政府之间往来的持续工作","example":"Quiet diplomacy kept the two delegations talking through the winter.","exampleCN":"静默外交让两个代表团在整个冬天都保持对话。","why":"The word names the business that credentials and envoys exist to carry on, so it points to the activity rather than to any one paper.","whyCN":"这个词命名的是凭证与使节存在的目的所指向的那项业务，因此指活动而非某一份纸页。"},{"no":"02","title":"The profession and the diplomatic service","titleCN":"外交这一职业与外交界","definition":"the career, ranks and institutions of officials who represent a state abroad","definitionCN":"在海外代表国家的官员所从事的职业、等级与机构","example":"She entered diplomacy after ten years in the foreign ministry.","exampleCN":"她在外交部工作十年后进入了外交界。","why":"Once the activity is organized into a service with ranks, the name of the activity also names the career.","whyCN":"当这项活动被组织成有等级的部门后，活动的名称也指这份职业。"},{"no":"03","title":"Skill in negotiation","titleCN":"谈判中的手腕与技艺","definition":"the ability to trade concessions, time moves and read the other side in order to reach an agreement","definitionCN":"通过交换让步、掌握时机与判断对方来达成协议的能力","example":"The deal was saved by patient diplomacy behind closed doors.","exampleCN":"这笔交易靠闭门之后的耐心谈判手腕才得以挽回。","why":"The activity demands a craft, and the abstract noun soon named the craft itself rather than the institution.","whyCN":"这项活动需要技艺，这个抽象名词很快便指技艺本身，而非机构。"},{"no":"04","title":"Tact in ordinary dealings","titleCN":"日常处事中的圆融得体","definition":"the everyday skill of handling people and conflicts without giving offence","definitionCN":"在日常中处理人际关系与冲突而不冒犯他人的能力","example":"It took diplomacy to tell him his proposal had already been rejected.","exampleCN":"要告诉他提案早已被否决，是需要一点圆融的。","why":"Negotiators became the model of tact, so the noun moved from the conference room to the kitchen table.","whyCN":"谈判者成了分寸的样板，于是这个名词从会议室走到了饭桌。"},{"no":"05","title":"Work in an embassy abroad","titleCN":"使馆与驻外事务","definition":"the daily duties of a mission, from visa interviews to reporting on the host country","definitionCN":"驻外机构的日常职责，从签证面谈到对驻在国的情势汇报","example":"His first year of diplomacy was spent processing visa files.","exampleCN":"他外交生涯的第一年都在处理签证档案。","why":"The grand word covers the paperwork of a mission, and that is where most of the work actually happens.","whyCN":"这个宏大的词也涵盖驻外机构的文书工作，而大部分实际工作正发生在这里。"},{"no":"06","title":"Shuttle and multilateral diplomacy","titleCN":"穿梭外交与多边外交","definition":"named modes of the craft, such as a mediator travelling between capitals or many states bargaining in one forum","definitionCN":"指这门技艺的特定模式，如斡旋者往返各首都，或许多国家在同一场合谈判","example":"Shuttle diplomacy produced a ceasefire after three weeks of flights.","exampleCN":"经过三周的飞行往返，穿梭外交促成了停火。","why":"Modern practice developed repeatable formats, and the noun attaches to each format as a named method.","whyCN":"现代实践发展出可重复的形式，这个名词便附着于每一种有名称的方法。"},{"no":"07","title":"Diplomacy as an instrument of policy","titleCN":"作为政策工具的外交","definition":"the use of envoys, aid, culture and sanctions as a softer alternative to military pressure","definitionCN":"把使节、援助、文化与制裁当作军事压力之外的较软替代手段来使用","example":"The budget treated diplomacy as a cheaper defence than another brigade.","exampleCN":"该预算把外交视为比再添一个旅更便宜的防务。","why":"Governments began to count influence as a resource, so the noun turned into a tool listed beside armies.","whyCN":"各国政府开始把影响力当作一种资源来计算，这个名词于是变成与军队并列的工具。"},{"no":"08","title":"A figurative strategy of relations","titleCN":"比喻：任何团体中的交际策略","definition":"a loosened use for the handling of alliances, rivals and feelings inside a company, family or club","definitionCN":"较松散的用法，指在公司、家庭或俱乐部内部处理盟友、对手与情绪的方式","example":"Office diplomacy decided who would sit near the new director.","exampleCN":"办公室里的交际策略决定了谁会坐在新主管旁边。","why":"The metaphor keeps the shape of many parties, limited goods and face-saving, which any group reproduces.","whyCN":"这个比喻保留了多方、有限资源与顾全面子的结构，而任何团体都会重现这一结构。"}],"etymology":{"intro":{"en":"Diplomacy reaches English through French diplomatie, a noun built on diplomatique, which goes back to Latin diploma and Greek diploma, 'a paper folded in two'. It is not a direct 'diploma plus -cy' coinage. Dates are approximate.","cn":"diplomacy 经法语 diplomatie 进入英语；diplomatie 是在 diplomatique 基础上构成的名词，而 diplomatique 可追到拉丁 diploma 与希腊 diploma「对折的纸」。它并非「diploma 加 -cy」的直接构词。年代均为约数。"},"items":[{"era":"GREEK DIPLOUN","en":"Diploun 'to fold' comes from diploos 'twofold', giving the physical image of a sheet folded once.","cn":"diploun「折」源自 diploos「双重的」，给出了一张纸对折一次的物理意象。"},{"era":"GREEK DIPLOMA","en":"The noun named a folded paper and later the letter an envoy carried to prove his commission.","cn":"这个名词指对折的纸，后来指使节随身携带、用以证明委任的信函。"},{"era":"LATIN DIPLOMA","en":"Latin used diploma for official documents and travel warrants, the paper that opened doors for an envoy.","cn":"拉丁用 diploma 指官方文书与旅行许可，正是这份纸为使者打开了门。"},{"era":"FRENCH DIPLOMATIE","en":"French coined diplomatie in the eighteenth century from diplomatique, naming the business that envoys carried on.","cn":"法语在十八世纪由 diplomatique 造出 diplomatie，命名使节所从事的那项业务。"},{"era":"ENGLISH DIPLOMACY","en":"English borrowed the French noun for the conduct of state relations and later extended it to tact in any setting.","cn":"英语借入这个法语名词，指处理国家关系的行为，后又扩展到任何场合中的分寸。"},{"era":"UNCERTAIN DATES AND DETAILS","en":"Source uncertain (dates and details): the first English use is dated only approximately, and the precise path by which the credential sense became the craft sense is not fully documented.","cn":"来源不确定（年代与细节）：英语首见年代只有约数；从「凭证」义转为「技艺」义的确切路径也缺乏完整书证。"}]},"similar":{"note":{"en":"Group one holds same-root words that look alike and name different pieces of the same field; group two holds near synonyms that differ in whether they mean an activity, a method or a personal quality.","cn":"第一组是同根、外形相近却指同一领域不同部分的词；第二组是近义词，区别在于指活动、方法还是个人品质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"diplomat","ipa":"/ˈdɪpləmæt/","tag":"same root, the person","definition":"An official who practises the craft; the noun names a person, while diplomacy names the activity.","definitionCN":"指从事这门技艺的官员；这个词命名人，而 diplomacy 命名活动。"},{"word":"diplomatic","ipa":"/ˌdɪpləˈmætɪk/","tag":"same root, the adjective","definition":"The adjective of the field and of tact; it describes, while diplomacy names.","definitionCN":"是该领域与分寸的形容词；它作描述，而 diplomacy 作命名。"},{"word":"diploma","ipa":"/dɪˈpləʊmə/","tag":"same root, the paper","definition":"The folded document or a certificate of study; it is a thing, not a practice.","definitionCN":"指对折的文书或学业证书；它是一件东西，不是一种实践。"},{"word":"diplomatics","ipa":"/dɪˈplɒmətɪks/","tag":"same root, document study","definition":"The scholarly analysis of old official documents, a separate discipline with its own methods.","definitionCN":"指对古代官方文书的学术分析，是一门有自身方法的独立学科。"}]},{"heading":"NEAR MEANING","entries":[{"word":"statecraft","ipa":"/ˈsteɪtkrɑːft/","tag":"wider governing skill","definition":"The whole art of managing a state, including domestic policy; diplomacy is its external branch.","definitionCN":"指治理国家的整体技艺，包括内政；diplomacy 是其对外分支。"},{"word":"negotiation","ipa":"/nɪˌɡəʊʃiˈeɪʃən/","tag":"one technique","definition":"The specific process of bargaining toward a deal; diplomacy may include negotiation but also representation and ceremony.","definitionCN":"指为达成交易而讨价还价的特定过程；diplomacy 可含谈判，但也含派驻与礼仪。"},{"word":"tact","ipa":"/tækt/","tag":"personal quality","definition":"The personal knack of not giving offence; it is one ingredient of diplomacy, not the whole craft.","definitionCN":"指不冒犯他人的个人本领；它是外交的一项成分，而非全部技艺。"},{"word":"foreign policy","ipa":"/ˈfɒrən ˈpɒləsi/","tag":"the aims, not the method","definition":"A government's stated goals abroad; diplomacy is one of the means used to pursue them.","definitionCN":"指一国政府对外宣称的目标；diplomacy 是实现这些目标的手段之一。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root image is a paper folded once: the credential that let an envoy speak, and the trade that grew around it.","cn":"词根意象是一张对折的纸：它让使节得以开口，围绕它长出了一门行业。"},{"en":"The family runs diploma, diplomat, diplomacy, diplomatic, diplomatically, undiplomatic.","cn":"同族词依次是 diploma、diplomat、diplomacy、diplomatic、diplomatically、undiplomatic。"},{"en":"Fixed collocations mark the modes: quiet diplomacy, shuttle diplomacy, public diplomacy, multilateral diplomacy.","cn":"固定搭配标出各种模式：静默外交、穿梭外交、公共外交、多边外交。"},{"en":"The abstract noun covers both the institution and the skill, which is why it can mean a ministry's work and a dinner-table grace.","cn":"这个抽象名词同时涵盖机构与技艺，因此既能指一个部的工作，也能指饭桌上的得体。"},{"en":"Near words split by role: statecraft governs, negotiation bargains, tact soothes, foreign policy aims.","cn":"近义词按角色分工：statecraft 治理，negotiation 讨价，tact 安抚，foreign policy 设定目标。"}],"abstract":[{"en":"Picture two chairs facing each other across a table, neither pushed back.","cn":"想象两把椅子隔着桌子相对，两把都没有被推开。"},{"en":"Picture one folded note passed from hand to hand until the crease wears soft.","cn":"想象同一张对折的便笺在几双手之间传递，折痕被磨得发软。"},{"en":"Picture a bridge laid plank by plank, each plank one more round of talks.","cn":"想象一座桥一块板一块板地铺成，每块板就是又一轮会谈。"}]},"examples":[{"en":"Years of patient diplomacy finally produced a border agreement.","cn":"多年的耐心外交终于促成了一份边界协议。"},{"en":"Sanctions without diplomacy rarely change a government's mind.","cn":"没有外交配合的制裁很少能改变一个政府的想法。"},{"en":"She handled the family quarrel with the diplomacy of a seasoned envoy.","cn":"她以老练使节般的外交手腕处理了这场家庭争吵。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「diplo（对折）+ macy（办事）」——纸能对折，话能转弯 → 外交；手腕","word":"diplomacy"},"root":"希腊 diploma「对折的纸」源自 diploun「折」，经拉丁 diploma「公文、通行凭证」进入法语 diplomatique；法语再以 diplomatique 构成名词 diplomatie，英语借入为 diplomacy。它并非「diploma 加 -cy」的直接构词；圆融义为后起引申。","sensesIntro":{"en":"Eight senses follow one craft: a folded credential lets an envoy speak, and that speaking becomes a daily practice, a career, a negotiating skill, a household tact, an embassy routine, named modes, a policy tool, and finally any group's private strategy.","cn":"八个义项沿同一门技艺展开：一份对折的凭证让使节得以开口，这种开口再成为日常实务、一种职业、谈判技艺、家庭中的分寸、使馆例行工作、有名称的模式、政策工具，最后是任何团体内部的交际策略。"},"semanticMap":{"core":{"en":"CORE IMAGE: two parties kept at one table by talk alone, with a folded credential lying between them.","cn":"核心意象：两方仅靠谈话被留在同一张桌边，中间放着一份对折的凭证。"},"chain":["FOLD THE CREDENTIAL","OPEN THE CHANNEL","KEEP TALKING","TRADE CONCESSIONS","SAVE BOTH FACES","AVOID THE ARMY"],"branches":[{"senses":"S1 · S2","en":"ACTIVITY AND CAREER: the daily conduct of relations and the service that carries it out are one practice seen as work and as profession (S1, S2).","cn":"实务与职业：日常的关系处理与执行它的部门，是同一实践作为工作与作为职业的两面（义项一、二）。"},{"senses":"S3 · S4","en":"SKILL AT TWO TABLES: bargaining across a treaty and sparing a colleague's feelings use the same craft at different stakes (S3, S4).","cn":"两种桌上的技艺：隔着条约讨价与顾全同事的感受，是同一种本事在不同赌注下（义项三、四）。"},{"senses":"S5 · S6","en":"POST AND METHOD: visa files in an embassy and a mediator flying between capitals are the routine and the named modes of one service (S5, S6).","cn":"驻馆与方法：使馆里的签证档案与往返各首都的斡旋者，是同一项工作的日常与有名称的模式（义项五、六）。"},{"senses":"S7","en":"INSTRUMENT: once counted against brigades, the craft becomes a line in a defence budget (S7).","cn":"工具：一旦与旅级部队相提并论，这门技艺就成了防务预算里的一行（义项七）。"},{"senses":"S8","en":"METAPHOR: any office or family repeats the table, the limited goods and the face-saving in miniature (S8).","cn":"比喻：任何办公室或家庭都以缩小的规模重演这张桌子、有限资源与顾全面子（义项八）。"}]},"affixes":{"intro":{"en":"Diplomacy is a French abstract noun sitting on an adjective that sits on a Greek noun of folded paper; the endings, not a '-cy' added to 'diploma', carry the abstraction.","cn":"diplomacy 是法语抽象名词，其下是形容词，再下是希腊「对折纸」名词；抽象义由词尾承担，而非在 diploma 后加 -cy。"},"latinIntro":{"en":"Greek diploma gives the noun, Latin diplomaticus the adjective, and French -ie turns that adjective into the name of the craft.","cn":"希腊 diploma 提供名词，拉丁 diplomaticus 提供形容词，法语 -ie 再把这个形容词变成技艺的名称。"},"items":[{"word":"diploun","structure":"diploun (Greek verb, 'to fold')","meaning":"to fold; to double","meaningCN":"折叠；使成双","example":"The physical act of folding is the oldest layer of the word.","exampleCN":"折叠这一物理动作是这个词最古老的一层。"},{"word":"diploma","structure":"diploma, diplomatis (Greek noun, later Latin noun)","meaning":"a folded paper; an official document","meaningCN":"对折的纸；官方文书","example":"The credential is a folded sheet before it is a profession.","exampleCN":"在成为一门职业之前，这份凭证先是一张对折的纸。"},{"word":"-aticus","structure":"-aticus (Medieval Latin adjectival suffix, 'relating to')","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns the document into an adjective of its field.","exampleCN":"这个后缀把文书变成该领域的形容词。"},{"word":"diplomaticus","structure":"diploma + -aticus (Medieval Latin)","meaning":"relating to envoys and state papers","meaningCN":"与使节和国家文书相关的","example":"The adjective is the bridge between paper and practice.","exampleCN":"这个形容词是纸页与实践之间的桥。"},{"word":"diplomatique","structure":"diplomaticus (French adjective)","meaning":"of envoys and state relations","meaningCN":"使节与国家关系的","example":"French gave the Latin adjective its modern shape.","exampleCN":"法语赋予这个拉丁形容词现代形态。"},{"word":"-ie","structure":"-ie (French noun suffix, from Latin -ia)","meaning":"an activity, a domain","meaningCN":"活动；领域","example":"The suffix turns the adjective into the name of a business.","exampleCN":"这个后缀把形容词变成一项业务的名称。"},{"word":"diplomatie","structure":"diplomatique + -ie (French noun)","meaning":"the business of envoys","meaningCN":"使节所从事的业务","example":"French coined the noun before English borrowed it.","exampleCN":"法语先造出这个名词，英语随后借入。"},{"word":"diplomacy","structure":"diplomatie (French, borrowed into English)","meaning":"the craft of conducting relations","meaningCN":"处理国家关系的技艺","example":"English kept the French ending almost unchanged.","exampleCN":"英语几乎原样保留了法语词尾。"},{"word":"diplomat","structure":"diplomatic (back-formation)","meaning":"one who practises the craft","meaningCN":"从事这门技艺的人","example":"The person noun was cut back from the adjective.","exampleCN":"这个指人的名词由形容词逆构而来。"}],"latinEntries":[{"word":"diploma","structure":"diploma, diplomatis (n., third declension)","meaning":"an official document, a letter of recommendation","meaningCN":"官方文书；推荐信"},{"word":"diplomaticus","structure":"diplomaticus, diplomatica, diplomaticum (adj., first and second declension)","meaning":"relating to official documents","meaningCN":"与官方文书相关的"}]}},{"word":"diplomat","ipa_uk":"/ˈdɪpləmæt/","ipa_us":"/ˈdɪpləmæt/","definition_zh":"外交官；（尤指）持有正式授权文书、派驻他国代表本国处理国家间事务的官员","definition_en":"an official appointed to represent a state abroad and to conduct relations with another government, especially one who holds formal credentials","core_image":"挂着两面国旗的会客室里，一位穿深色礼服的人把封好火漆的公文推过长桌，对面的人伸手接过","scene":"会客室里的吊灯刚亮，穿深色礼服的人把封好火漆的公文推过桌面，对面的人伸手接过。A senior diplomat was sent to reopen talks after the border incident.","sceneCN":"这里 diplomat 指「派驻他国、代表本国处理国家间事务的官员」（第 1 个义项：持有正式授权文书并受命与外国政府交涉的官方代表）；句意为边境事件之后，一位资深外交官被派去重启会谈。图中可辨识物件：两面国旗、封好火漆的公文、长桌、深色礼服。","pos":[{"tag":"n.","zh":"外交官；外交人员（可数，复数 diplomats）"}],"collocations":[{"phrase":"career diplomat","zh":"职业外交官"},{"phrase":"senior diplomat","zh":"高级外交官"},{"phrase":"foreign diplomat","zh":"外国外交官"},{"phrase":"diplomat posted abroad","zh":"派驻海外的外交官"},{"phrase":"a skilled diplomat","zh":"一位善于周旋的外交官"},{"phrase":"recall a diplomat","zh":"召回一名外交官"}],"forms":[{"label":"复数","form":"diplomats"},{"label":"形容词（外交的；委婉的）","form":"diplomatic"},{"label":"副词（通过外交途径；委婉地）","form":"diplomatically"},{"label":"名词（外交；外交手腕）","form":"diplomacy"},{"label":"名词（公文；文凭）","form":"diploma"},{"label":"旧称（外交家）","form":"diplomatist"}],"derivatives":[{"word":"diplomatic","pos":"adj.","zh":"外交的；措辞委婉的（diplomat 加 -ic，源自拉丁 -icus、希腊 -ikos，语义从「持公文者」偏移为「与外交有关的」）"},{"word":"diplomacy","pos":"n.","zh":"外交；外交手腕（法语 diplomatie 出自 diplomatique「外交的」，加 -ie 表行业，语义偏移为「管理国家间关系的行业」）"},{"word":"diplomatically","pos":"adv.","zh":"以外交方式；委婉地（diplomatic 加古英语副词后缀 -lice，语义偏移为「以不伤和气的方式」）"},{"word":"diploma","pos":"n.","zh":"公文；文凭（拉丁 diploma 出自希腊 diploma「对折的纸」，语义偏移为「官方文书，后指学业证书」，与指人的 diplomat 分工不同）"},{"word":"diplomatist","pos":"n.","zh":"外交家；外交事务研究者（diplomat 加 -ist，源自希腊 -istes 经法语 -iste 的施事后缀，语义偏移为「以研究或实践外交为业者」）"},{"word":"diplomatics","pos":"n.","zh":"文书学（diplomat 加 -ics，源自希腊 -ika 学科后缀，语义偏移为「研究公文格式与真伪的学科」）"}],"senses":[{"no":"01","title":"A career officer of a foreign service","titleCN":"职业外交官","definition":"an official who makes diplomacy a lifelong profession and serves in a country's foreign ministry or its missions abroad","definitionCN":"以外交为终身职业、在本国外交部或驻外机构任职的官员","example":"As a career diplomat, she has served in four capitals.","exampleCN":"作为职业外交官，她已在四个首都任职。","why":"The word names the person by the credential carried, so a whole profession and a single individual share one noun.","whyCN":"这个词以所持文书来命名人，因此整个职业与单个从业者共用一个名词。"},{"no":"02","title":"An official attached to an embassy","titleCN":"派驻大使馆的官员","definition":"a member of an embassy or consulate who handles visas, protests, cultural affairs or political reporting","definitionCN":"在大使馆或领事馆处理签证、抗议交涉、文化事务或政治情况汇报的成员","example":"The embassy diplomat handled the visa interview himself.","exampleCN":"大使馆的那位外交官亲自处理了签证面谈。","why":"An embassy is where the credential is displayed every day, so the word often means simply the officer behind the desk.","whyCN":"大使馆是文书每天展示之处，因此这个词常就指柜台后的那位官员。"},{"no":"03","title":"A skilled negotiator","titleCN":"擅长谈判周旋的人","definition":"a person whose strength is talk: finding formulas, buying time and keeping rivals at the table","definitionCN":"长处在于言谈的人：能找出措辞方案、争取时间、把对手留在谈判桌旁","example":"She proved a fine diplomat, keeping both delegations talking until midnight.","exampleCN":"她显露出出色的周旋本领，让两个代表团一直谈到午夜。","why":"The craft of the profession is talk, so the job title slides into the name of the skill itself.","whyCN":"这一行的本事就是说话，因此职位名称顺势变成了这种本领的名称。"},{"no":"04","title":"A member of a delegation or legation","titleCN":"外交使节团成员","definition":"one of the accredited persons forming an official mission sent to represent a state","definitionCN":"受命代表国家出访的正式使团中获得授权的成员之一","example":"Each delegation brought three diplomats and one interpreter.","exampleCN":"每个代表团都带来三名外交人员和一名译员。","why":"Missions are staffed by several credential holders at once, so the plural names the members of a group rather than a rank.","whyCN":"使团同时由数名持文书者组成，因此复数形式指的是团体成员，而非某一级别。"},{"no":"05","title":"An official representative handling sensitive matters","titleCN":"处理敏感事务的官方代表","definition":"a special envoy sent to manage a delicate file, such as a hostage case, a border incident or a secret exchange","definitionCN":"被派去处理棘手事务的特使，例如人质事件、边境冲突或秘密交换","example":"A diplomat was flown in to negotiate the release of the crew.","exampleCN":"一名外交官被紧急空运来，就船员的获释进行交涉。","why":"When a file is too sensitive for ordinary channels, the state sends a person whose title already means authorized talk.","whyCN":"当一桩事务敏感得不能走寻常渠道时，国家就派出头衔本身即意味「获授权交涉」的人。"},{"no":"06","title":"A socially tactful person","titleCN":"引申为善于交际者","definition":"anyone who handles people smoothly, flatters without lying and avoids needless friction","definitionCN":"任何待人圆熟、能不撒谎地恭维、避免无谓摩擦的人","example":"Her father was a diplomat at every family dinner.","exampleCN":"她父亲在每次家庭聚餐上都像个外交官。","why":"Tact in a drawing room looks exactly like tact at a conference table, so the title is borrowed for social grace.","whyCN":"客厅里的圆融与会议桌旁的圆融看起来完全一样，因此这个头衔被借来形容社交分寸。"},{"no":"07","title":"A plenipotentiary bearing a ruler's letters","titleCN":"历史上持君主文书的全权使臣","definition":"the historical envoy who carried sealed letters of authority and could bind his sovereign by agreement","definitionCN":"历史上携带盖印授权文书、能以协议约束其君主的使臣","example":"In the old court, a diplomat could not speak without his sealed letters.","exampleCN":"在旧时的宫廷里，外交使臣若没有盖印文书就无权发言。","why":"The Greek word named the folded paper, and the man was named from the paper that gave him power.","whyCN":"希腊词命名的是那张对折的纸，而人是由赋予他权力的那张纸得名的。"},{"no":"08","title":"Figurative: a smooth operator","titleCN":"比喻：圆滑的人","definition":"a slightly ironic use for someone who manages every situation and never says a plain yes or no","definitionCN":"略带反讽的用法，指凡事都要周旋、从不明说是或否的人","example":"He is too much of a diplomat to admit the plan failed.","exampleCN":"他太像外交官了，不肯承认计划已经失败。","why":"The metaphor keeps the sheen of the credential but drops the office, leaving only the manner.","whyCN":"这个比喻保留文书的光泽，却抽掉了职位，只留下那副做派。"}],"etymology":{"intro":{"en":"Diplomat goes back to a Greek word for a sheet folded double, which became the Latin word for an official letter, then a French word for the person who carried such letters. Dates are approximate.","cn":"diplomat 可追溯到希腊语中表示「对折的一张纸」的词，该词变为拉丁语中表示公文的名词，再变为法语中指携带这类文书者的名词。年代均为约数。"},"items":[{"era":"GREEK DIPLOUN","en":"Diploun meant 'to fold double', and the physical image behind the whole family is one sheet laid over itself.","cn":"diploun 意为「对折、折成两层」，整族词背后的具体意象就是把一张纸叠在自己身上。"},{"era":"GREEK DIPLOMA","en":"Diploma first named a paper folded double, then widened to any official document, including letters of recommendation and travel permits.","cn":"diploma 最初指对折的纸，随后扩大到任何官方文书，包括推荐信与通行许可。"},{"era":"LATIN DIPLOMA","en":"Latin borrowed diploma for official letters, grants of privilege and warrants; the document sense is the one that traveled onward.","cn":"拉丁语借入 diploma，指官方书信、特权授予书与委任状；继续向外传播的正是「文书」这一义。"},{"era":"FRENCH DIPLOMATE","en":"French used diplomate for a person furnished with such letters and authorized to treat with a foreign court.","cn":"法语用 diplomate 指持有这类文书、获授权与外国宫廷交涉的人。"},{"era":"ENGLISH DIPLOMAT","en":"English adopted the French word for an accredited envoy, and the sense later widened from one mission to the whole profession.","cn":"英语借入这个法语词，指获派驻的使节；后来词义从一次使命扩大到整个职业。"},{"era":"UNCERTAIN SOURCE","en":"Source uncertain: the earliest English citation is not precisely recorded, and the deeper origin of diploun is source uncertain.","cn":"来源不确定：英语最早的书证年份没有确切记载；diploun 更早的来源亦属来源不确定。"}]},"similar":{"note":{"en":"Group one holds forms built from the same folded-paper root that are easily taken for one another; group two holds ranks and missions that differ in function.","cn":"第一组是同出「对折纸」词根、容易被互相误认的形式；第二组是职能不同的使节级别与使命。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"diploma","ipa":"/dɪˈpləʊmə/","tag":"same root, the paper","definition":"The document itself, now usually a certificate of study; it is never the person who holds it.","definitionCN":"指文书本身，如今多指学业证书；它从不指持有它的人。"},{"word":"diplomacy","ipa":"/dɪˈpləʊməsi/","tag":"same root, the activity","definition":"The profession or skill of managing relations between states; it names the work, not the worker.","definitionCN":"指管理国家间关系的行业或手腕；它命名的是工作，不是从业者。"},{"word":"diplomatic","ipa":"/ˌdɪpləˈmætɪk/","tag":"same root, adjective","definition":"Describing the work or the manner; a diplomatic answer is a tactful one, not an answer delivered by an envoy.","definitionCN":"描述这项工作或这种做派；a diplomatic answer 指措辞委婉的回答，而不是由外交官给出的回答。"},{"word":"diplomatist","ipa":"/dɪˈpləʊmətɪst/","tag":"older synonym","definition":"A nineteenth-century synonym for the same person, still used of writers on the craft; it is not a separate rank.","definitionCN":"十九世纪指同一类人的同义词，至今仍用于外交实务的著作者；它并非另一个级别。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ambassador","ipa":"/æmˈbæsədə(r)/","tag":"highest rank","definition":"The chief envoy accredited to a foreign state; a diplomat may serve under an ambassador in the same mission.","definitionCN":"派驻某国的首席使节；外交官可以在同一使团里听命于大使。"},{"word":"envoy","ipa":"/ˈenvɔɪ/","tag":"mission-bound","definition":"A messenger or minister sent on a specific errand, often temporary and often outside the regular embassy.","definitionCN":"为特定任务派出的信使或使者，常为临时性质，也常不属常规使馆。"},{"word":"consul","ipa":"/ˈkɒnsəl/","tag":"local duties","definition":"An officer who protects citizens and trade in a foreign city; the diplomatic side of the role is narrower.","definitionCN":"在外国城市保护本国公民与贸易的官员；其外交职能范围较窄。"},{"word":"emissary","ipa":"/ˈemɪsəri/","tag":"secret-agent tone","definition":"A person sent to carry a message or sound out a rival, often quietly and without public status.","definitionCN":"被派去传递消息或探听对手意向的人，常行事低调、无公开身份。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"diploun 'to fold' gives diploma 'a paper folded double', and the envoy is named after the folded letters he carries.","cn":"diploun「折」得出 diploma「对折的纸」，使节正是由他携带的对折文书得名。"},{"en":"The family runs diploma, diplomat, diplomatic, diplomacy, diplomatically, diplomatist.","cn":"同族词依次是 diploma、diplomat、diplomatic、diplomacy、diplomatically、diplomatist。"},{"en":"Fixed collocations mark the role: career diplomat, senior diplomat, foreign diplomat, recall a diplomat.","cn":"固定搭配标出这一角色：职业外交官、高级外交官、外国外交官、召回外交官。"},{"en":"Two spellings must not be merged: a diploma is a certificate, a diplomat is the person who carries credentials.","cn":"两个拼法不能合并：diploma 是证书，diplomat 是携带授权文书的人。"},{"en":"The credential came first: a diplomat could not act without sealed letters from his ruler.","cn":"文书在先：外交官若没有君主盖印的书信就无法行动。"}],"abstract":[{"en":"Picture a folded sheet kept in a breast pocket, creased so often that the fold line has worn white.","cn":"想象一张对折的纸放在胸前口袋，折痕被反复摩挲得发白。"},{"en":"Picture two rivals at a long table, each passing notes to a third person instead of speaking directly.","cn":"想象两个对手坐在长桌两端，都通过第三人传纸条，而不直接说话。"},{"en":"Picture one person holding a door open for two others who refuse to be in the same room.","cn":"想象一个人为两位不肯同处一室的来客分别扶着门。"}]},"examples":[{"en":"The diplomat refused to confirm the rumor until his capital had spoken.","cn":"在首都表态之前，这位外交官拒绝证实那则传闻。"},{"en":"Talks resumed only after a junior diplomat carried a private letter across the border.","cn":"直到一名低级外交官把一封私人信件带过边境，会谈才重启。"},{"en":"What the memo called a diplomat, the press called a fixer.","cn":"备忘录称之为外交官的人，媒体称之为「摆平事的人」。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「diplo（对折的纸）+ mat」——揣着对折的授权公文出门办事的人 → 外交官","word":"diplomat"},"root":"希腊 diploma「对折的纸」，出自 diploun「折」；经拉丁 diploma「公文、通行凭证」进入法语 diplomate，指持公文受权办事的人，后专指外交官。它与 diploma「文凭」同源而所指不同，并非「学位持有者」。diploun 更早的来源属来源不确定。","sensesIntro":{"en":"Eight senses follow one folded paper: the credential is carried abroad, and the carrier becomes a career officer, an embassy official, a negotiator, a delegation member, a special envoy, a tactful guest, a plenipotentiary, and finally a smooth talker.","cn":"八个义项沿一张对折的纸展开：文书被带出国门，持文书者依次成为职业外交官、使馆官员、谈判者、使团成员、特使、善交际者、全权使臣，最后成为圆滑的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a folded credential in a breast pocket, which grants the authority to speak for a state.","cn":"核心意象：胸前口袋里一张对折的授权文书，它赋予人为国家发声的权力。"},"chain":["FOLD THE PAPER","CARRY THE LETTER","SPEAK FOR A STATE","SERVE THE PROFESSION","NEGOTIATE AND SMOOTH","TACT AS A TYPE"],"branches":[{"senses":"S1 · S2","en":"OFFICE AND POST: a lifelong career and a desk in an embassy are one credential seen from two distances.","cn":"职业与驻点：终身职业与使馆里的一张办公桌，是同一张文书的远近两种看法。"},{"senses":"S3 · S4","en":"TALK AND TEAM: negotiating skill and membership in a mission both rest on the right to speak.","cn":"言谈与团体：谈判本领与使团成员身份，都立足于「有权发言」这一点。"},{"senses":"S5 · S6","en":"SPECIAL MISSION AND SOCIAL GRACE: a delicate errand abroad and tact at a dinner table share one manner.","cn":"特使与社交分寸：海外棘手差事与餐桌上的圆融，共用同一种做派。"},{"senses":"S7","en":"HISTORICAL ENVOY: the plenipotentiary is the literal bearer of the sealed letter.","cn":"历史使臣：全权使臣就是那封盖印书信的字面携带者。"},{"senses":"S8","en":"IRONIC TYPE: the credential drops away and only the smooth manner is left.","cn":"反讽类型：文书褪去，只剩下那副圆滑的做派。"}]},"affixes":{"intro":{"en":"Diplomat is a person named from a document: a Greek verb of folding, a Greek noun of result, a Latin borrowing of the same noun, and a French agent noun.","cn":"diplomat 是由文书得名的人：一个希腊语「折」动词、一个希腊语结果名词、同一名词的拉丁语借形，以及一个法语施事名词。"},"latinIntro":{"en":"Latin kept diploma as the official letter and formed diplomaticus as its adjective; both are the direct ancestors of the English family.","cn":"拉丁语保留 diploma 指公文，并以 diplomaticus 作其形容词；二者都是英语这一族词的直接祖先。"},"items":[{"word":"diploun","structure":"diploun (Greek verb)","meaning":"to fold double","meaningCN":"对折；折成两层","example":"The verb supplies the physical image behind the whole family.","exampleCN":"这个动词提供了整族词背后的具体意象。"},{"word":"-ma","structure":"-ma (Greek noun suffix, result of an action)","meaning":"the result of an act","meaningCN":"动作的结果","example":"The suffix turns the act of folding into the folded object.","exampleCN":"这个后缀把「折」的动作变成折好的物件。"},{"word":"diploma","structure":"diploun + -ma (Greek)","meaning":"a paper folded double; an official document","meaningCN":"对折的纸；官方文书","example":"The Greek noun already carries both the paper and the official use.","exampleCN":"这个希腊名词已同时含有「纸张」与「官方用途」两层。"},{"word":"diploma","structure":"diploma (Latin, borrowed from Greek)","meaning":"official letters, a warrant, a grant of privilege","meaningCN":"官方书信；委任状；特权授予书","example":"Latin narrowed the noun toward documents that authorize action.","exampleCN":"拉丁语把这个名词收窄为「授权行动的文书」。"},{"word":"diplomate","structure":"diplomate (French, from Latin diploma)","meaning":"a person furnished with official letters","meaningCN":"持有官方文书的人","example":"French shifted the noun from the paper to its bearer.","exampleCN":"法语把这个名词从纸张转到了持纸者身上。"},{"word":"diplomat","structure":"diplomate (French) → diplomat (English)","meaning":"an accredited envoy","meaningCN":"获派驻的使节；外交官","example":"English dropped the final vowel and kept the person.","exampleCN":"英语脱落了词尾元音，保留了「人」这一义。"},{"word":"-ic","structure":"-icus (Latin adjective suffix, from Greek -ikos)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix yields diplomatic, the adjective of the whole field.","exampleCN":"这个后缀造出 diplomatic，即整个领域的形容词。"},{"word":"-cy","structure":"-ie (French noun suffix, from Latin -ia)","meaning":"a practice or profession","meaningCN":"某种实践或行业","example":"The suffix yields diplomacy, the name of the trade itself.","exampleCN":"这个后缀造出 diplomacy，即这一行本身的名称。"},{"word":"-ly","structure":"-lice (Old English adverb suffix)","meaning":"in the manner of","meaningCN":"以……的方式","example":"The suffix yields diplomatically, meaning with care for the other side.","exampleCN":"这个后缀造出 diplomatically，意为顾及对方感受地。"},{"word":"-ist","structure":"-iste (French agent suffix, from Greek -istes)","meaning":"one who practises","meaningCN":"从事……的人","example":"The suffix yields diplomatist, the older name for the practitioner.","exampleCN":"这个后缀造出 diplomatist，即从业者的旧称。"}],"latinEntries":[{"word":"diploma","structure":"diploma, diplomatis (n., third declension)","meaning":"an official letter, a folded document","meaningCN":"公文；对折的文书"},{"word":"diplomaticus","structure":"diplomaticus (adj., Late Latin, from Greek diplomatikos)","meaning":"relating to official documents","meaningCN":"与公文有关的"}]}},{"word":"negotiation process","ipa_uk":"/nɪˌɡəʊʃiˈeɪʃən ˈprəʊses/","ipa_us":"/nɪˌɡoʊʃiˈeɪʃən ˈprɑːses/","definition_zh":"谈判过程；（尤指）各方为达成协议而依次经历的正式协商阶段","definition_en":"the sequence of stages through which parties discuss terms, exchange offers and move toward an agreement","core_image":"会议室长桌两侧各摆一叠文件，中间一只沙漏，纸页被来回推过桌面，边缘已经磨软","scene":"会议室的长桌两侧各摆一叠文件，中间一只沙漏，纸页被来回推过桌面，边缘已经磨软。The negotiation process stalled for a week over the wording of a single clause.","sceneCN":"这里 negotiation process 指「各方为达成协议而依次经历的一系列协商阶段」（第 1 个义项：从首次接触直至条款谈成的整段讨论）；句意为谈判过程因为一个条款的措辞而停滞了一周。图中可辨识物件：两叠文件、沙漏、长桌、边缘磨软的纸页。","pos":[{"tag":"n.","zh":"谈判过程（可数；复数 negotiation processes）"}],"collocations":[{"phrase":"lengthy negotiation process","zh":"漫长的谈判过程"},{"phrase":"peace negotiation process","zh":"和平谈判进程"},{"phrase":"enter the negotiation process","zh":"进入谈判进程"},{"phrase":"stall the negotiation process","zh":"使谈判进程停滞"},{"phrase":"a transparent negotiation process","zh":"透明的谈判过程"},{"phrase":"the negotiation process between employers and unions","zh":"雇主与工会之间的谈判过程"}],"forms":[{"label":"复数","form":"negotiation processes"},{"label":"核心名词（谈判）","form":"negotiation"},{"label":"动词（谈判；商定）","form":"negotiate"},{"label":"名词（谈判者）","form":"negotiator"},{"label":"形容词（可协商的）","form":"negotiable"},{"label":"核心名词（过程；程序）","form":"process"}],"derivatives":[{"word":"negotiate","pos":"v.","zh":"谈判；商定（拉丁 negotiari「做生意、交涉」加 -ate，源自 -atus 动词化后缀，语义偏移为「就条件进行交涉」）"},{"word":"negotiation","pos":"n.","zh":"谈判（negotiari 加 -tion，源自拉丁 -tio 动作名词后缀，语义偏移为「交涉这一行为」）"},{"word":"negotiator","pos":"n.","zh":"谈判者（negotiation 加 -or，源自拉丁施事后缀，语义偏移为「承担交涉的人」）"},{"word":"negotiable","pos":"adj.","zh":"可协商的（negotiate 加 -able，源自拉丁 -abilis 能力后缀，语义偏移为「可经谈判改动的」）"},{"word":"process","pos":"n./v.","zh":"过程；处理（拉丁 processus 出自 procedere「向前走」，语义偏移为「一段向前推进的流程」）"},{"word":"procedural","pos":"adj.","zh":"程序上的（procedure 加 -al，源自拉丁 -alis 形容词后缀，语义偏移为「与步骤规则有关的」）"}],"senses":[{"no":"01","title":"The whole sequence of talks toward a deal","titleCN":"通向成交的整段谈判","definition":"the entire run of discussion from first contact to signed terms, seen as one continuous activity","definitionCN":"从首次接触直至条款签字的整段讨论，被视为一项连续的活动","example":"The negotiation process began with a courtesy call and ended with a handshake.","exampleCN":"谈判过程以一次礼节性拜访开始，以一次握手结束。","why":"Negotiation names the bargaining and process names the stretch of time, so the pair marks a course rather than a single moment.","whyCN":"negotiation 命名讨价还价，process 命名时间跨度，两者组合标记的是一段过程而非一个瞬间。"},{"no":"02","title":"The formal stages of consultation","titleCN":"正式协商的程序阶段","definition":"the ordered steps of an official consultation: agenda, opening positions, working groups, drafting and adoption","definitionCN":"正式协商中按序推进的步骤：议程、开场立场、工作组、起草与通过","example":"Delegates complained that the negotiation process had no clear agenda.","exampleCN":"代表们抱怨这场谈判过程没有明确议程。","why":"A process can be broken into stages, and official talks are the place where those stages are written down in rules.","whyCN":"过程可以被切成阶段，而正式会谈正是把这些阶段写成规则的地方。"},{"no":"03","title":"The bargaining flow between employers and unions","titleCN":"劳资之间的谈判流程","definition":"the routine sequence of claims, counter-offers, conciliation and a settlement or a strike in industrial relations","definitionCN":"劳动关系中提出诉求、回应报价、调解，直至达成协议或发生罢工的常规序列","example":"The negotiation process between the union and the management lasted through the summer.","exampleCN":"工会与管理层之间的谈判过程持续了整个夏天。","why":"Collective bargaining is scheduled and repeated, so it is the clearest case of bargaining with a recognizable flow.","whyCN":"集体谈判有排期、可重复，因此是「有可辨认流程的讨价还价」最清楚的例子。"},{"no":"04","title":"The track of peace talks","titleCN":"和平谈判的进程","definition":"the slow diplomatic sequence by which warring sides move from a ceasefire to a political settlement","definitionCN":"交战各方从停火走向政治解决的缓慢外交序列","example":"Observers say the peace negotiation process has stalled over the status of the border valley.","exampleCN":"观察人士说，和平谈判进程因边境山谷的地位问题而停滞。","why":"Peace talks are measured in rounds and months, so the word process is almost required to describe them.","whyCN":"和平谈判以轮次和月份来计量，因此几乎必须用 process 来描述它。"},{"no":"05","title":"The rounds of offer and counter-offer","titleCN":"多轮讨价还价的进程","definition":"the repeated exchange in which each side tests the other's limit and moves its own position","definitionCN":"各方反复交换条件、试探对方底线并调整自身立场的循环","example":"Every round of the negotiation process removed one disputed clause.","exampleCN":"谈判过程的每一轮都去掉了一个有争议的条款。","why":"The core of bargaining is iteration, and a process is exactly the shape that iteration takes over time.","whyCN":"讨价还价的核心是反复，而「过程」正是这种反复在时间上呈现的形状。"},{"no":"06","title":"A mediated consultation","titleCN":"由第三方调解促成的协商","definition":"a facilitated sequence in which a neutral party shapes the agenda and carries messages between the sides","definitionCN":"由中立第三方安排议程、在各方之间传递信息的协助式序列","example":"The mediation turned a shouting match into a workable negotiation process.","exampleCN":"调解把一场互相叫嚷变成了可行的谈判过程。","why":"When a third party manages the steps, the process itself becomes visible as a structure rather than a mood.","whyCN":"当第三方来安排步骤时，过程本身就显现为一种结构，而不只是一种情绪。"},{"no":"07","title":"The formation of a contract","titleCN":"合同形成的过程","definition":"the legal sequence of offer, acceptance and drafting through which an agreement becomes enforceable","definitionCN":"经由要约、承诺与起草，使协议成为可强制执行之文书的法律序列","example":"Lawyers watched the negotiation process to see when the offer was actually accepted.","exampleCN":"律师们盯着谈判过程，想看清要约究竟何时被实际接受。","why":"Law cares about when each step happened, so the same bargaining flow is reread as a chain of legal events.","whyCN":"法律关心每一步发生在何时，因此同一段讨价还价被重读为一串法律事件。"},{"no":"08","title":"Figurative: step-by-step consensus building","titleCN":"比喻：逐步达成共识的过程","definition":"any gradual, patient sequence by which a group talks itself into a shared position, as in a family or a committee","definitionCN":"任何群体通过缓慢耐心的谈话形成共同立场的序列，如家庭或委员会中的情形","example":"The committee's negotiation process was mostly a long exchange of drafts.","exampleCN":"委员会的那套「谈判过程」其实主要是长时间交换草稿。","why":"The metaphor works because any group that must agree repeats the literal shape: proposals, replies, revision, agreement.","whyCN":"这个比喻成立，是因为任何必须达成一致的群体都重复着字面结构：提案、回应、修改、同意。"}],"etymology":{"intro":{"en":"The phrase joins two unrelated Latin stocks: negotium is literally 'not leisure', while processus is 'a going forward'. French carried both halves into English before they were paired. Dates are approximate.","cn":"这个短语把两个互不相关的拉丁词源拼在一起：negotium 字面是「不闲」，processus 则是「向前走」。两半都经法语进入英语，之后才被组合。年代均为约数。"},"items":[{"era":"LATIN NEGOTIUM","en":"Neg- 'not' plus otium 'leisure' made negotium 'business', literally the absence of leisure.","cn":"neg-「不」加 otium「闲暇」构成 negotium「事务」，字面即「不闲」。"},{"era":"LATIN NEGOTIARI","en":"The verb negotiari meant 'to carry on business' and, by extension, 'to transact and bargain'.","cn":"动词 negotiari 意为「做生意」，并引申为「办理交易、讨价还价」。"},{"era":"LATIN NEGOTIATIO","en":"Negotiatio named a business transaction and the handling of it, and it is the direct source of English negotiation.","cn":"negotiatio 指一笔交易及其办理过程，是英语 negotiation 的直接来源。"},{"era":"LATIN PROCEDERE","en":"Pro- 'forward' plus cedere 'to go' gave procedere, 'to go forward, to advance'.","cn":"pro-「向前」加 cedere「走」构成 procedere，意为「向前走、推进」。"},{"era":"LATIN PROCESSUS","en":"Processus named a going forward, an advance or a course of events, and English took it as process.","cn":"processus 指向前行进、推进或事情的发展进程，英语借入为 process。"},{"era":"UNCERTAIN SOURCE AND DATES","en":"Source uncertain (deeper origin and first date): the deeper origin of otium is source uncertain, and the date when the two words became a fixed English phrase is not recorded.","cn":"来源不确定（深层来源与首见年代）：otium 更早的来源属来源不确定；两个词固定组合为英语短语的年份亦无记载。"}]},"similar":{"note":{"en":"Group one holds forms from the same bargaining root plus the bare second element, which are routinely confused; group two holds other names for talk that differ in what they stress.","cn":"第一组是同出「交涉」词根的形式，外加单独使用的后半部分，常被混用；第二组是侧重不同的其他「谈话」名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"negotiation","ipa":"/nɪˌɡəʊʃiˈeɪʃən/","tag":"same root, one act","definition":"The bargaining itself or a single session of it; the process is the whole course those sessions make.","definitionCN":"指讨价还价本身或其中一场；而 process 指这些场次连成的整段过程。"},{"word":"negotiator","ipa":"/nɪˈɡəʊʃieɪtə(r)/","tag":"same root, the person","definition":"The person who does the bargaining, not the course it follows.","definitionCN":"指进行交涉的人，而不是交涉所走的流程。"},{"word":"negotiable","ipa":"/nɪˈɡəʊʃiəbl/","tag":"same root, adjective","definition":"Open to being changed by talks; it describes a term or a price, not a timetable.","definitionCN":"指可经谈判改动的；它描述的是条款或价格，不是时间表。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"second element, general","definition":"Any series of steps; standing alone it says nothing about bargaining or agreement.","definitionCN":"指任何一系列步骤；单独使用时与谈判或协议无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bargaining","ipa":"/ˈbɑːɡənɪŋ/","tag":"the haggling","definition":"The trading of offers, often over price or wages; it names the haggling rather than the schedule.","definitionCN":"指交换条件，常围绕价格或工资；它命名的是讨价还价，而非流程安排。"},{"word":"mediation","ipa":"/ˌmiːdiˈeɪʃən/","tag":"third party","definition":"Assisted negotiation run by a neutral outsider; a process may contain or consist of mediation.","definitionCN":"由中立外部人士主持的协助式谈判；一个过程可以包含或就是调解。"},{"word":"consultation","ipa":"/ˌkɒnsəlˈteɪʃən/","tag":"advice-seeking","definition":"A formal asking of opinions, which may precede bargaining but need not involve offers at all.","definitionCN":"正式征求意见，可在讨价还价之前进行，但未必涉及任何报价。"},{"word":"talks","ipa":"/tɔːks/","tag":"journalistic","definition":"The press word for a series of meetings; it is looser and often more hopeful than process.","definitionCN":"新闻用语，指一系列会谈；比 process 更松散，也常带有更多期待。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Neg- 'not' plus otium 'leisure' gives negotium 'business': bargaining is what people do when they are not at ease.","cn":"neg-「不」加 otium「闲暇」得出 negotium「事务」：交涉正是人们不得清闲时做的事。"},{"en":"The first half runs otium, negotium, negotiari, negotiatio, negotiate, negotiation, negotiator, negotiable.","cn":"前半串是 otium、negotium、negotiari、negotiatio、negotiate、negotiation、negotiator、negotiable。"},{"en":"The second half runs cedere 'go', procedere 'go forward', processus 'a course', process.","cn":"后半串是 cedere「走」、procedere「向前走」、processus「进程」、process。"},{"en":"The two halves are strangers: one is about business, the other about moving forward, and the phrase simply joins them.","cn":"两半原本互不相干：一半讲生意，一半讲向前走，短语只是把它们接在一起。"},{"en":"Fixed collocations mark the stages: enter the negotiation process, stall the negotiation process, a lengthy negotiation process.","cn":"固定搭配标出阶段：进入谈判进程、使谈判进程停滞、漫长的谈判过程。"}],"abstract":[{"en":"Picture a long corridor with doors on both sides, each opening only after the one before it closes.","cn":"想象一条长走廊，两侧都是门，每一扇都要等前一扇关上才打开。"},{"en":"Picture a rope walked hand over hand across a gap, one grip at a time.","cn":"想象双手交替握着一根绳横越沟壑，一次只挪一握。"},{"en":"Picture a clock face without hands, only tick marks that someone crosses off one by one.","cn":"想象一只没有指针的钟面，只有刻度被人一格一格划掉。"}]},"examples":[{"en":"A credible negotiation process needs a timetable both sides have already accepted.","cn":"一个可信的谈判过程需要双方事先接受的时间表。"},{"en":"The document describes the negotiation process in five separate stages.","cn":"这份文件分五个阶段描述谈判过程。"},{"en":"Foreign ministers met to restart a negotiation process that had collapsed in the spring.","cn":"各国外长会面，以重启在春季崩溃的谈判进程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「neg（不）+ oti（闲暇）+ process（往前走）」——不得清闲，一步一步往前走 → 谈判过程","word":"negotiation process"},"root":"谈判：拉丁 nec/neg-「不」加 otium「闲暇」构成 negotium「事务」，再派生 negotiari「做生意、交涉」与 negotiatio「交易、谈判」；过程：pro-「向前」加 cedere「走」构成 procedere「前进」，其名词 processus 即「进程」。两半不同源。otium 更早来源属来源不确定。","sensesIntro":{"en":"Eight senses follow one course: two sides begin to talk, and the course is then read as formal stages, an industrial bargaining cycle, a peace track, repeated rounds, a mediated sequence, a contract in the making, and finally any group talking itself into agreement.","cn":"八个义项沿一段进程展开：两方开始谈，这段进程再依次被读作正式阶段、劳资谈判周期、和平轨道、反复的轮次、调解序列、正在形成的合同，最后是任何群体谈出共识的过程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a table, two stacks of paper and an hourglass, where each exchange moves the papers one step closer to a signature.","cn":"核心意象：一张桌子、两叠文件与一只沙漏，每一次交换都让纸页向签字靠近一步。"},"chain":["OPEN THE TALKS","SET THE STAGES","TRADE OFFERS","TEST THE LIMITS","NARROW THE GAP","PUT IT IN WRITING"],"branches":[{"senses":"S1 · S2","en":"WHOLE AND STEPS: a continuous course and its formal stages are the same span seen close up or from above.","cn":"整段与阶段：连续的进程与它的正式阶段，是同一段时间的近看与俯瞰。"},{"senses":"S3 · S4","en":"FACTORY AND BORDER: wages and peace are different subjects for an identical bargaining rhythm.","cn":"工厂与边境：工资与和平是不同题目，走的却是同一种交涉节奏。"},{"senses":"S5 · S6","en":"ROUNDS AND A REFEREE: repetition drives the process forward, and a mediator makes that repetition legible.","cn":"轮次与裁判：反复推动进程前行，而调解人让这种反复变得可见。"},{"senses":"S7","en":"LEGAL CHAIN: the same flow is reread as offer, acceptance and enforceable text.","cn":"法律链条：同一段流程被重读为要约、承诺与可执行的文本。"},{"senses":"S8","en":"METAPHORICAL GROUP: any committee repeats the literal shape on a smaller scale.","cn":"比喻群体：任何委员会都在更小的规模上重演这一字面结构。"}]},"affixes":{"intro":{"en":"The phrase is built from two unrelated Latin pieces: a negative plus a noun of leisure, and a prefix of forward motion plus a verb of going.","cn":"这个短语由两块互不相干的拉丁材料构成：一个否定成分加一个「闲暇」名词，以及一个表示向前的介词性成分加一个「走」动词。"},"latinIntro":{"en":"Latin negotium and negotiari supply the first half; procedere and its noun processus supply the second.","cn":"拉丁 negotium 与 negotiari 提供前半，procedere 及其名词 processus 提供后半。"},"items":[{"word":"neg-","structure":"neg- / nec- (Latin negative particle)","meaning":"not","meaningCN":"不；非","example":"The particle turns leisure into its opposite, business.","exampleCN":"这个否定成分把「闲暇」变成它的反面，即「事务」。"},{"word":"otium","structure":"otium, otii (n., second declension)","meaning":"leisure, ease, quiet","meaningCN":"闲暇；安逸；清静","example":"The noun supplies the state that business denies.","exampleCN":"这个名词提供「事务」所否定的那种状态。"},{"word":"negotium","structure":"neg- + otium","meaning":"business; a matter to be done","meaningCN":"事务；待办之事","example":"The compound is literally 'not leisure'.","exampleCN":"这个复合词字面上就是「不闲」。"},{"word":"negotiari","structure":"negotium + -ari (Latin verb ending)","meaning":"to do business, to bargain","meaningCN":"做生意；交涉","example":"The verb adds the activity to the noun of business.","exampleCN":"这个动词把「做事」的活动加在「事务」名词之上。"},{"word":"-atio","structure":"-atio (Latin noun suffix, action or process)","meaning":"the act or process of","meaningCN":"……的行为或过程","example":"The suffix turns bargaining into a named activity.","exampleCN":"这个后缀把交涉变成一个有名称的行为。"},{"word":"negotiatio","structure":"negotiari + -atio","meaning":"a transaction; bargaining","meaningCN":"交易；谈判","example":"The noun is the direct ancestor of negotiation.","exampleCN":"这个名词是 negotiation 的直接祖先。"},{"word":"pro-","structure":"pro- (Latin prefix, forward)","meaning":"forward; in front","meaningCN":"向前；在前","example":"The prefix gives the second half its direction.","exampleCN":"这个前缀给后半部分定下方向。"},{"word":"cedere","structure":"cedere, cessi, cessum (verb, third conjugation)","meaning":"to go, to yield","meaningCN":"走；让步","example":"The verb supplies the motion inside process.","exampleCN":"这个动词提供 process 内部的「行进」义。"},{"word":"processus","structure":"pro- + cedere (past participle cessus)","meaning":"a going forward; a course","meaningCN":"向前行进；进程","example":"The noun turns motion into a course of events.","exampleCN":"这个名词把位移变成事情的发展进程。"},{"word":"process","structure":"processus (Latin) → process (English)","meaning":"a series of steps","meaningCN":"一系列步骤；过程","example":"English keeps the sense of a course run through.","exampleCN":"英语保留了「走完一段路」的意思。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who does","meaningCN":"做……的人","example":"The suffix yields negotiator from the bargaining stock.","exampleCN":"这个后缀由交涉词干造出 negotiator。"}],"latinEntries":[{"word":"otium","structure":"otium, otii (n., second declension)","meaning":"leisure, ease","meaningCN":"闲暇；安逸"},{"word":"negotium","structure":"negotium, negotii (n., second declension)","meaning":"business, a matter","meaningCN":"事务；事情"},{"word":"negotiari","structure":"negotiari, negotiatus sum (verb, first conjugation, deponent)","meaning":"to carry on business, to bargain","meaningCN":"做生意；交涉"},{"word":"negotiatio","structure":"negotiatio, negotiationis (f., third declension)","meaning":"a transaction, bargaining","meaningCN":"交易；谈判"},{"word":"procedere","structure":"procedere, processi, processum (verb, third conjugation)","meaning":"to go forward, advance","meaningCN":"向前走；推进"},{"word":"processus","structure":"processus, processus (m., fourth declension)","meaning":"a going forward, a course","meaningCN":"前进；进程"}]}},{"word":"warfare","ipa_uk":"/ˈwɔːfeə(r)/","ipa_us":"/ˈwɔːrfer/","definition_zh":"战争；作战；（尤指）进行战争的行为与方式","definition_en":"the activity of fighting a war, especially the manner in which armed conflict is conducted","core_image":"泥泞的旷野上，翻倒的辎重车还在冒烟，地平线被火光染红，半埋的头盔露出边缘","scene":"泥泞的旷野上，翻倒的辎重车还在冒烟，地平线被火光染红，半埋的头盔露出边缘。Modern warfare depends on drones as much as on infantry.","sceneCN":"这里 warfare 指「进行战争的行为与方式」（第 1 个义项：以有组织武装力量交战的整体活动，尤指其打法）；句意为现代战争对无人机的依赖不亚于对步兵的依赖。图中可辨识物件：翻倒的辎重车、升起的烟、被火光染红的地平线、半埋的头盔。","pos":[{"tag":"n.","zh":"战争；作战（一般不可数；指某一类作战方式时可加修饰语，如 guerrilla warfare）"}],"collocations":[{"phrase":"modern warfare","zh":"现代战争"},{"phrase":"guerrilla warfare","zh":"游击战"},{"phrase":"chemical warfare","zh":"化学战"},{"phrase":"naval warfare","zh":"海战"},{"phrase":"warfare tactics","zh":"作战战术"},{"phrase":"the horrors of warfare","zh":"战争的恐怖"}],"forms":[{"label":"核心名词（战争）","form":"war"},{"label":"复数（战争；冲突）","form":"wars"},{"label":"名词（战士）","form":"warrior"},{"label":"名词（战时）","form":"wartime"},{"label":"名词（军舰）","form":"warship"},{"label":"名词（战场）","form":"battlefield"}],"derivatives":[{"word":"war","pos":"n./v.","zh":"战争；打仗（古北法语 werre 出自法兰克语 *werra「混乱、争斗」，语义偏移为「有组织的武装冲突」，与拉丁 bellum 无关）"},{"word":"warrior","pos":"n.","zh":"战士（war 加古法语施事后缀 -eur，经 werreur 进入英语，语义偏移为「上阵作战的人」）"},{"word":"warlike","pos":"adj.","zh":"好战的（war 加古英语相似后缀 -lic，语义偏移为「带有战争气息的」）"},{"word":"wartime","pos":"n.","zh":"战时（war 与 time 的英语复合，time 源自古英语 tima「时间」，语义偏移为「战争持续的时期」）"},{"word":"warship","pos":"n.","zh":"军舰（war 与 ship 的英语复合，ship 源自古英语 scip「船」，语义偏移为「为作战而建的船」）"},{"word":"fare","pos":"n./v.","zh":"车费；行程；过活（古英语 faru「旅程、队伍」，语义偏移为「出行、旅费、进食」，正是 warfare 后半的来源）"}],"senses":[{"no":"01","title":"The conduct of armed conflict","titleCN":"战争行为；作战","definition":"the activity of fighting with organized armed forces, especially the way it is carried out","definitionCN":"以有组织的武装力量交战这一活动，尤指其进行方式","example":"Modern warfare depends on drones as much as on infantry.","exampleCN":"现代战争对无人机的依赖不亚于对步兵的依赖。","why":"War can mean the declared state; warfare names the doing of it, so the word describes activity rather than a legal condition.","whyCN":"war 可以指宣示的状态，warfare 命名的是「做」这件事，因此它描述活动而非法律状态。"},{"no":"02","title":"A state of war between parties","titleCN":"战争状态","definition":"the condition in which two or more states or factions are openly or formally at war","definitionCN":"两个或多个国家或派别公开或正式处于交战之中的状况","example":"The two republics drifted into warfare after the border patrols clashed.","exampleCN":"边境巡逻队冲突之后，两个共和国逐渐滑入战争状态。","why":"The second element once meant a journey or expedition, so the word can name a whole stretch of hostile going, not only a battle.","whyCN":"后半部分原指旅程或出征，因此这个词可以命名一整段敌对行程，而不只是一场战斗。"},{"no":"03","title":"A named type of war","titleCN":"某一类型的战争","definition":"a labeled mode of fighting, such as conventional, guerrilla, naval, chemical or cyber warfare","definitionCN":"有标签的作战方式，如常规战、游击战、海战、化学战或网络战","example":"Guerrilla warfare bogged down the occupying army for a decade.","exampleCN":"游击战让占领军陷于泥潭达十年之久。","why":"Types branch off naturally because warfare names a manner of fighting, and manners can always be labeled.","whyCN":"类型会自然分出来，因为 warfare 命名的是打法，而打法总能被贴上标签。"},{"no":"04","title":"Military operations taken as a whole","titleCN":"军事行动的总称","definition":"the collective name for campaigns, raids, sieges and patrols conducted by an armed force","definitionCN":"对一支武装力量所进行的战役、突袭、围攻与巡逻的整体称呼","example":"The museum's maps record the warfare of an entire campaign.","exampleCN":"馆里的地图记录了整场战役的军事行动。","why":"Once many operations are seen together, the mass of them takes the same name as the activity that produced them.","whyCN":"当许多行动被放在一起看时，这一大堆行动就与产生它们的活动同名。"},{"no":"05","title":"Figurative struggle","titleCN":"比喻：斗争、对抗","definition":"a hostile contest waged with pressure rather than weapons, as in class warfare or price warfare","definitionCN":"以压力而非武器进行的敌对较量，如阶级对抗或价格战","example":"The two chains waged price warfare until smaller shops closed.","exampleCN":"两家连锁店打价格战，直到小店纷纷关门。","why":"Any contest that feels like a campaign borrows the word, whether the weapons are prices, laws or insults.","whyCN":"任何感觉像战役的较量都会借用这个词，无论武器是价格、法律还是恶语。"},{"no":"06","title":"The art of war","titleCN":"战争艺术","definition":"the study of strategy, logistics and tactics as a disciplined craft","definitionCN":"把战略、后勤与战术当作一门有章法的技艺来研究","example":"He studied warfare at the staff college for two years.","exampleCN":"他在参谋学院学了两年战争艺术。","why":"The conduct of war can be taught and examined, so the activity turns into a subject with its own rules.","whyCN":"作战可以被教授与考核，因此这项活动变成一门有自身规则学问。"},{"no":"07","title":"The destruction war leaves behind","titleCN":"战争造成的破坏","definition":"the ruin of towns, fields and lives that armed conflict produces, often spoken of as a mass","definitionCN":"武装冲突造成的城镇、田野与生命的毁坏，常被当作一整片来谈论","example":"Whole districts still show the scars of that warfare.","exampleCN":"整片城区至今仍留着那场战争造成的伤痕。","why":"The object of the word can be the wreckage rather than the fighting, because destruction is what warfare leaves visible.","whyCN":"这个词的所指可以是废墟而非战斗，因为战争留下的可见之物正是破坏。"},{"no":"08","title":"Open conflict between groups","titleCN":"群体之间的冲突","definition":"hostility between gangs, factions or communities, short of a declared war","definitionCN":"帮派、派系或社区之间的敌对，尚未达到宣战程度","example":"Police blame gang warfare for the shootings in the district.","exampleCN":"警方把该区的枪击归因于帮派争斗。","why":"Where organized groups fight without states, the same word describes the smaller war without any legal claim.","whyCN":"当有组织的群体在没有国家的情况下打斗，同一个词就用来描述这场规模更小的战争，不涉任何法律主张。"}],"etymology":{"intro":{"en":"War comes from a Frankish word of strife, not from Latin bellum, while the second element is Old English faru 'journey, troop'. The compound is native English built on a borrowed first word. Dates are approximate.","cn":"war 来自法兰克语中表示争斗的词，并非拉丁 bellum；后半部分是古英语 faru「旅程、队伍」。整个复合词是英语本土构造，只借了第一个词。年代均为约数。"},"items":[{"era":"FRANKISH *WERRA","en":"Werra meant 'confusion, strife, discord'; it is a reconstructed form, written with an asterisk because no text records it directly.","cn":"werra 意为「混乱、争斗、不和」；它属重构形式，写作时加星号，因为没有任何文本直接记录它。"},{"era":"OLD NORTH FRENCH WERRE","en":"Old North French took the Frankish word as werre and passed it to English after the Norman settlement.","cn":"古北法语把法兰克语这个词吸收为 werre，并在诺曼定居之后传入英语。"},{"era":"MIDDLE ENGLISH WAR","en":"English spelled it werre and warre before settling on war, and the word never came from Latin bellum.","cn":"英语先写作 werre、warre，后来定为 war；这个词从来不出自拉丁 bellum。"},{"era":"OLD ENGLISH FARU","en":"Faru meant 'a journey, an expedition, a troop on the move', and it is the same word that survives in fare.","cn":"faru 意为「旅程、出征、行进中的队伍」，与今天仍存的 fare 是同一个词。"},{"era":"ENGLISH WARFARE","en":"The compound of war plus fare named the waging of war, literally a going to war with troops.","cn":"war 与 fare 的复合词命名「进行战争」，字面就是带着队伍出征。"},{"era":"UNCERTAIN SOURCE AND DATES","en":"Source uncertain (reconstruction and first date): werra is a reconstruction and its deeper origin is source uncertain; the first English use of the compound is dated only approximately.","cn":"来源不确定（重构形式与首见年代）：werra 属重构形式，其更早来源属来源不确定；这个复合词在英语中最早的使用只能大致系年。"}]},"similar":{"note":{"en":"Group one holds the two elements that make the compound plus near-identical words built on them, which are often read as if they meant the same thing; group two holds other names for organized fighting.","cn":"第一组是构成该复合词的两个部分及其上长出的形近词，常被误读为同义；第二组是有组织交战的其他名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"war","ipa":"/wɔː(r)/","tag":"same first element, the state","definition":"The conflict itself or its declared condition; warfare is the conduct, not the declaration.","definitionCN":"指冲突本身或宣示的状态；warfare 指进行方式，而非宣示。"},{"word":"fare","ipa":"/feə(r)/","tag":"same second element, a journey","definition":"A journey, a passenger's ticket or the price of travel; the element once meant exactly a journey, not a cost.","definitionCN":"指行程、车票或旅费；这一词素原义正是「旅程」，并非「费用」。"},{"word":"welfare","ipa":"/ˈwelfeə(r)/","tag":"look-alike, different first element","definition":"Well plus fare, 'the state of faring well'; it is not war plus fare and has nothing to do with fighting.","definitionCN":"由 well 加 fare 构成，意为「过得好」的状态；它不是 war 加 fare，与打仗无关。"},{"word":"warrior","ipa":"/ˈwɒriə(r)/","tag":"same first element, the person","definition":"The fighter, built on the same war stock with an agent suffix; it names a person, not an activity.","definitionCN":"指战斗者，由同一 war 词干加施事后缀构成；它指人，不指活动。"}]},{"heading":"NEAR MEANING","entries":[{"word":"combat","ipa":"/ˈkɒmbæt/","tag":"the clash itself","definition":"Actual fighting between forces; combat is the clash, whereas warfare is the whole activity and its manner.","definitionCN":"指部队之间的实际交火；combat 是那一下碰撞，warfare 则是整体活动及其打法。"},{"word":"conflict","ipa":"/ˈkɒnflɪkt/","tag":"wider","definition":"Any prolonged hostility, from a border skirmish to a trade dispute; it need not involve armies at all.","definitionCN":"指任何持续的敌对，从边境小规模冲突到贸易争端；可完全不涉及军队。"},{"word":"hostilities","ipa":"/hɒˈstɪlətiz/","tag":"formal and legal","definition":"The official term for acts of war once they begin; it belongs to communiques rather than to description.","definitionCN":"对开战行为的正式称呼；它属于公报语言，而非描写语言。"},{"word":"battle","ipa":"/ˈbætl/","tag":"single engagement","definition":"One engagement between forces; warfare contains many battles and outlives all of them.","definitionCN":"指部队之间的一次交战；warfare 包含许多场战斗，并比它们持续更久。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Werra 'strife' came from Frankish, not from Latin bellum, so war and the Latin words for war are not relatives.","cn":"werra「争斗」来自法兰克语，而非拉丁 bellum，因此 war 与拉丁语中表示战争的词并非同族。"},{"en":"The second element is Old English faru 'journey, troop', the same word that survives in fare and farewell.","cn":"后半部分是古英语 faru「旅程、队伍」，与 fare、farewell 中留存的是同一个词。"},{"en":"The compound is a going to war: war plus fare, not war plus a ticket price.","cn":"这个复合词意为出征：war 加 fare，而不是 war 加票价。"},{"en":"The family runs war, warrior, warlike, wartime, warship, warfare.","cn":"同族词依次是 war、warrior、warlike、wartime、warship、warfare。"},{"en":"Collocations label the kinds: guerrilla warfare, chemical warfare, naval warfare, modern warfare.","cn":"固定搭配标出类型：游击战、化学战、海战、现代战争。"}],"abstract":[{"en":"Picture a column of carts rolling out at dawn, dust rising behind them in one long line.","cn":"想象一列车队在黎明出发，扬起的尘土在车后拉成长长一条。"},{"en":"Picture a map with red arrows drawn over it, arrows that stop at a river and never resume.","cn":"想象一张地图上画着红色箭头，箭头在一条河边停住，再没有继续。"},{"en":"Picture a field of wheat with a single track cut through it, straight as a ruler.","cn":"想象一片麦田被一道笔直如尺的车辙从中划开。"}]},"examples":[{"en":"The manual treats warfare as a craft with rules, not as a series of heroic episodes.","cn":"这本手册把作战当作一门有规则的技艺，而不是一串英雄插曲。"},{"en":"Drought and warfare drove the same families across the border in the same season.","cn":"旱灾与战乱在同一个季节把同一批家庭赶过了边境。"},{"en":"Economists now speak of warfare between platforms over the same customers.","cn":"经济学家如今谈论平台之间为争夺同一批顾客而展开的战争。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「war（打）+ fare（走一趟）」——带着队伍出去打一趟 → 战争、作战；fare 这里是「行程」不是「费用」","word":"warfare"},"root":"war 来自古北法语 werre，源自法兰克语 *werra「混乱、争斗」（重构形式），并非拉丁 bellum；-fare 来自古英语 faru「旅程、队伍」，与 fare、farewell 同族。warfare 不是 war 加 fare「费用」，而是「出征打仗」。*werra 更早来源属来源不确定。","sensesIntro":{"en":"Eight senses follow one expedition: troops go out to fight, and that going is then read as the conduct itself, a state, a labeled type, the mass of operations, a metaphor, an art, the ruin left, and finally any group's open conflict.","cn":"八个义项沿一次出征展开：队伍出去作战，这次出行再依次被读作作战本身、战争状态、贴标签的类型、行动的总和、比喻、技艺、留下的废墟，最后是任何群体的公开冲突。"},"semanticMap":{"core":{"en":"CORE IMAGE: a column of carts and troops on the move, and the ground behind them already burnt.","cn":"核心意象：一支车队与队伍正在开拔，身后的地面已经烧过。"},"chain":["DECLARE THE CONFLICT","MARCH THE TROOPS","FIGHT IN A MANNER","SUSTAIN THE CAMPAIGN","LEAVE THE RUIN","NAME ANY STRIFE"],"branches":[{"senses":"S1 · S2","en":"DOING AND BEING: the activity of fighting and the condition of being at war are one event seen as motion or as state.","cn":"动作与状态：交战的活动与处于战争中的状态，是同一事件被看作运动或状态。"},{"senses":"S3 · S4","en":"MANNER AND MASS: a labeled way of fighting and the sum of all operations both describe how the war is waged.","cn":"方式与总和：有标签的打法与所有行动的总和，都在描述战争如何被进行。"},{"senses":"S5 · S6","en":"METAPHOR AND CRAFT: any hard contest borrows the word, and the real thing can be studied as an art.","cn":"比喻与技艺：任何激烈较量都借用这个词，而真实战争可以被当作技艺来研究。"},{"senses":"S7","en":"THE WRECKAGE: what remains visible of warfare is the ruin, so the word can name the damage itself.","cn":"废墟：战争可见的遗留就是毁坏，因此这个词也能指破坏本身。"},{"senses":"S8","en":"SMALLER WAR: groups without states repeat the whole shape at the scale of a street.","cn":"更小的战争：没有国家的群体在街区的规模上重演整个结构。"}]},"affixes":{"intro":{"en":"The word is a native compound with a borrowed first element: a Frankish noun of strife, an Old English noun of journey, and a second element that behaves almost like a suffix.","cn":"这个词是本土复合词，只有第一个成分是借来的：一个法兰克语「争斗」名词、一个古英语「旅程」名词，以及一个作用近乎后缀的第二成分。"},"latinIntro":{"en":"There is no Latin kin here: war is Frankish in origin rather than Latin bellum, and fare is Old English, so no Latin entries are listed.","cn":"这里没有拉丁同族：war 源自法兰克语而非拉丁 bellum，fare 属古英语，因此不列拉丁词条。"},"items":[{"word":"*werra","structure":"werra (Frankish noun, reconstructed)","meaning":"confusion, strife","meaningCN":"混乱；争斗","example":"The asterisk marks a form reconstructed from later evidence.","exampleCN":"星号表示这是依据后世材料重构的形式。"},{"word":"werre","structure":"werre (Old North French, from Frankish)","meaning":"war, strife","meaningCN":"战争；争斗","example":"The French form is the direct bridge to English.","exampleCN":"这个法语形式是通往英语的直接桥梁。"},{"word":"war","structure":"werre → war (English)","meaning":"armed conflict","meaningCN":"武装冲突；战争","example":"English shortened the borrowed noun to one syllable.","exampleCN":"英语把这个借来的名词缩成一个音节。"},{"word":"faru","structure":"faru (Old English noun)","meaning":"a journey, an expedition, a troop","meaningCN":"旅程；出征；队伍","example":"The noun supplies the going that the compound needs.","exampleCN":"这个名词提供复合词所需的「出行」义。"},{"word":"fare","structure":"faru → fare (English)","meaning":"to travel; a journey; the price of travel","meaningCN":"行进；行程；旅费","example":"The modern noun keeps the journey and adds the cost.","exampleCN":"现代名词保留「行程」，又添上「花费」。"},{"word":"-fare","structure":"-fare (second element of English compounds)","meaning":"a going, a journey","meaningCN":"行走；行程","example":"Welfare and warfare both end in this element, though only one begins with war.","exampleCN":"welfare 与 warfare 都以这个成分结尾，尽管只有一个以 war 开头。"},{"word":"warfare","structure":"war + -fare","meaning":"the waging of war","meaningCN":"进行战争；作战","example":"The compound names the going out to fight, not the price of a ticket.","exampleCN":"这个复合词命名的是出征作战，而不是票价。"},{"word":"warrior","structure":"werre + -eur (Old North French agent suffix)","meaning":"a fighter","meaningCN":"战士；斗士","example":"The suffix turns the noun of strife into a person.","exampleCN":"这个后缀把「争斗」名词变成一个人。"},{"word":"warlike","structure":"war + -lic (Old English suffix)","meaning":"having the nature of war","meaningCN":"具有战争性质的；好战的","example":"The suffix makes an adjective of manner out of the noun.","exampleCN":"这个后缀由名词造出表示性质的形容词。"}],"latinEntries":[]}},{"word":"warfare strategy","ipa_uk":"/ˈwɔːfeə ˈstrætədʒi/","ipa_us":"/ˈwɔːrfer ˈstrætədʒi/","definition_zh":"战争战略；对战争全局的筹划与指导，包括目标设定、资源分配与作战次序","definition_en":"the overall planning and direction of a war, setting its aims, resources and the sequence of operations rather than the details of a single battle","core_image":"沙盘上插满小旗，一只手把一支旗从海岸移到内陆，旗影落在一整片等高线上","scene":"帐篷里的长桌上铺着整片海岸的沙盘，小旗分别插在港口、山口与河湾，一只手正把一支旗从岸边移向内陆。The council debated warfare strategy until the fleet could sail with a single plan.","sceneCN":"这里 warfare strategy 指「对战争全局的筹划与指导」（第 1 个义项：在开战前确定目标、资源与行动次序的总体设计）；句意为会议一直辩论战争战略，直到舰队能带着一份统一计划出航。图中可辨识物件：沙盘、成排小旗、港口与山口标记、移动旗子的手。","pos":[{"tag":"n.","zh":"战争战略；作战总方针（复合名词；指几套具体战略时复数作 warfare strategies）"}],"collocations":[{"phrase":"national warfare strategy","zh":"国家战争战略"},{"phrase":"asymmetric warfare strategy","zh":"非对称战争战略"},{"phrase":"maritime warfare strategy","zh":"海上战争战略"},{"phrase":"develop a warfare strategy","zh":"制定战争战略"},{"phrase":"revise the warfare strategy","zh":"修订战争战略"},{"phrase":"warfare strategy and tactics","zh":"战争战略与战术"}],"forms":[{"label":"复数","form":"warfare strategies"},{"label":"核心名词（战争；作战）","form":"warfare"},{"label":"核心名词（战略）","form":"strategy"},{"label":"复数（战略）","form":"strategies"},{"label":"形容词（战略的）","form":"strategic"},{"label":"副词（战略上）","form":"strategically"},{"label":"名词（战略家）","form":"strategist"}],"derivatives":[{"word":"war","pos":"n.","zh":"战争（古北法语 werre 来自法兰克语 *werra「混乱、争斗」，由「混乱」转为「有组织的武装冲突」）"},{"word":"warfare","pos":"n.","zh":"战争；作战（war 加 -fare，源自古英语 faru「旅程、队伍」，指行军打仗之事，并非 war 加 fare「费用」）"},{"word":"strategy","pos":"n.","zh":"战略（希腊 stratēgia「将帅之才」，经拉丁与法语进入英语，由「统帅本领」转为「全局筹划」）"},{"word":"strategic","pos":"adj.","zh":"战略的；关乎全局的（strategy 加 -ic，由名词转为形容词，语义从「统帅术」转向「全局性的」）"},{"word":"strategist","pos":"n.","zh":"战略家（strategy 加 -ist，指以制定全局方案为业的人）"},{"word":"stratagem","pos":"n.","zh":"计谋；诡计（希腊 stratēgēma「将帅之计」，与 strategy 同族，语义偏向具体的一次欺骗手段）"},{"word":"strategically","pos":"adv.","zh":"战略上；从全局着眼地（strategic 加 -ally，转为方式副词）"}],"senses":[{"no":"01","title":"The overall direction of a war","titleCN":"战争全局的总体指导","definition":"the plan that fixes a war's aims, priorities and the broad sequence of operations","definitionCN":"确定战争目标、优先次序与大致行动顺序的总体方案","example":"A sound warfare strategy matches the army's aims to what its industry can supply.","exampleCN":"稳妥的战争战略把军队的目标与工业所能提供的物资相匹配。","why":"Strategy names the general's art, so the compound puts that art at the level of a whole war rather than a single engagement.","whyCN":"strategy 本指将帅之才，因此这个复合词把这种本领放在整场战争的层面，而不是单次交战。"},{"no":"02","title":"A guiding line for operations","titleCN":"指导作战的方针","definition":"the settled line of action that tells commanders what to seek and what to avoid in the field","definitionCN":"告诉指挥官在战场上该追求什么、回避什么的既定行动路线","example":"Their warfare strategy was to trade space for time and never hold a ruined city.","exampleCN":"他们的作战方针是以空间换时间，绝不死守一座已成废墟的城市。","why":"Once the plan is fixed, it works as a standing rule that every subordinate order must respect.","whyCN":"方案一旦定下，就作为一条常设准则发挥作用，每一道下级命令都必须遵守它。"},{"no":"03","title":"A military action plan","titleCN":"军事行动计划","definition":"the concrete schedule of phases, routes and supply lines drawn up from the general aim","definitionCN":"由总体目标细化出的阶段、路线与补给线具体安排","example":"The staff turned the warfare strategy into a timetable of landings and advances.","exampleCN":"参谋部把战争战略变成一份登陆与推进的时间表。","why":"A strategy only exists as paper until it is broken into dates, units and routes, and that breakdown is also called by the same name.","whyCN":"战略只有被拆成日期、部队与路线才不只是纸面，而这份拆解也用同一个名称。"},{"no":"04","title":"The strategic level above tactics","titleCN":"高于战术的战略层级","definition":"the level of war that decides why and where to fight, leaving how to win a single engagement to tactics","definitionCN":"决定为何打、在哪里打的战争层级，把单场交战如何取胜交给战术","example":"At the strategic level, the warfare strategy set the front but left the tactics to the colonels.","exampleCN":"在战略层面，战争战略只划定战线，把战术留给上校们。","why":"War is commonly split into strategy and tactics, and the compound marks the upper half of that split.","whyCN":"战争通常分为战略与战术，这个复合词标记的就是这一划分的上半部分。"},{"no":"05","title":"Asymmetric warfare strategy","titleCN":"非对称战争战略","definition":"a plan by a weaker force to avoid pitched battle and wear down a stronger opponent by other means","definitionCN":"弱势一方避开正面会战、以其他手段消耗强敌的方案","example":"Their asymmetric warfare strategy relied on small units and long supply lines.","exampleCN":"他们的非对称战争战略依靠小股部队与漫长补给线。","why":"When one side cannot match the other's numbers, the same word covers a plan built on disparity rather than on mass.","whyCN":"当一方无法与对方比数量时，同一个词也涵盖建立在这种差距而非兵力之上的方案。"},{"no":"06","title":"The military part of a grand strategy","titleCN":"国家大战略中的军事部分","definition":"the armed component of a state's wider plan, which also weighs diplomacy, economy and industry","definitionCN":"国家更宏大计划中的武装部分，该计划同时衡量外交、经济与工业","example":"Diplomats set the terms, but the warfare strategy had to fit the alliance's timetables.","exampleCN":"外交官定下条件，但战争战略必须与同盟的时间表相合。","why":"Modern planning puts soldiers inside a larger frame, so the compound names one strand of that frame rather than the whole of it.","whyCN":"现代筹划把军人放进一个更大的框架，因此这个复合词只命名框架中的一股，而非全部。"},{"no":"07","title":"A business war plan by metaphor","titleCN":"商业竞争中的作战策略比喻","definition":"a journalistic use for a firm's plan to beat a rival, borrowing the vocabulary of armies and fronts","definitionCN":"新闻用法，指企业击败对手的计划，借用了军队与战线的词汇","example":"The retailer's warfare strategy was to open stores where the rival was weakest.","exampleCN":"这家零售商的战争战略是在对手最薄弱的地方开店。","why":"Markets are described as battlegrounds, so a plan for winning one borrows the name of a plan for winning a war.","whyCN":"市场常被说成战场，因此打赢市场的方案就借用了打赢战争的方案之名。"},{"no":"08","title":"A winning plan in a game or contest","titleCN":"比赛或博弈中的制胜策略","definition":"a playful extension to sport, chess or negotiation, where a long campaign of moves replaces a battle","definitionCN":"戏谑地扩展到体育、国际象棋或谈判，用一长串着法替代一场战斗","example":"Her warfare strategy for the chess final was to exhaust him in the middle game.","exampleCN":"她为象棋决赛定下的战争战略是在中局把他拖垮。","why":"The word keeps its shape wherever one side must allocate scarce pieces over many moves, and a board game has exactly that shape.","whyCN":"只要一方要在许多回合中分配有限棋子，这个词就保持其形态，而棋盘游戏正有这种结构。"}],"etymology":{"intro":{"en":"The phrase joins a Germanic noun for armed strife to a Greek noun for generalship; the two halves have no common origin. Dates are approximate.","cn":"这个短语把一个表示武装争斗的日耳曼名词与一个表示将帅之才的希腊名词连在一起，两半没有共同来源。年代均为约数。"},"items":[{"era":"GREEK STRATOS","en":"Stratos named an army, a host of men drawn up for war, and it is the first element behind the strategy family.","cn":"stratos 指军队，即列阵备战的众人，是 strategy 词族背后的第一个成分。"},{"era":"GREEK AGEIN","en":"Agein meant to lead or drive, and stratos plus agein described the leading of an army.","cn":"agein 意为引导、驱赶，stratos 与 agein 合起来指率领一支军队。"},{"era":"GREEK STRATEGIA","en":"Strategia named the office and skill of a general, and it is generally thought to have passed into Latin and then French as the word for strategic command.","cn":"stratēgia 指将帅的职位与本领，一般认为它经拉丁语再经法语，成为表示战略指挥的词。"},{"era":"FRANKISH *WERRA","en":"The war half comes through Old North French werre from Frankish *werra 'confusion, strife'; the starred form is a reconstruction, and its deeper source is not recorded.","cn":"war 这一半经古北法语 werre 来自法兰克语 *werra「混乱、争斗」；带星号的形式是重构形式，其更深来源没有记载。"},{"era":"OLD ENGLISH FARU","en":"Faru meant a journey or a troop on the move, and its descendant -fare survives in fare and farewell as well as in warfare.","cn":"faru 指旅程或行进中的队伍，其后代 -fare 还留在 fare、farewell 以及 warfare 之中。"},{"era":"MODERN COMPOUND","en":"English joined the two nouns to name the waging of war and later added strategy; the pair is a modern convenience, not an ancient unit, and its first use is source uncertain.","cn":"英语把两个名词连起来指进行战争，后来又加上 strategy；这一组合是现代便利用法，并非古代单位，其最早书证属来源不确定。"}]},"similar":{"note":{"en":"Group one separates the Greek and Germanic pieces that look like strategy words but are not; group two places the phrase among plans of wider or narrower scope.","cn":"第一组辨析那些形似战略词却并非同源的希腊与日耳曼成分；第二组把这个短语放进范围更宽或更窄的各种方案中。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"strategy","ipa":"/ˈstrætədʒi/","tag":"same Greek root, the art itself","definition":"The general art of planning and directing; it can cover peace as well as war, while the compound confines it to armed conflict.","definitionCN":"指筹划与指挥的总体本领，可涵盖和平时期，而这个复合词把它限定在武装冲突中。"},{"word":"stratagem","ipa":"/ˈstrætədʒəm/","tag":"same Greek family, a ruse","definition":"A trick or device to outwit an opponent, from Greek stratēgēma; it is a single manoeuvre, not a plan for a whole war.","definitionCN":"指智取对手的计谋，出自希腊 stratēgēma；它是一次具体手段，不是整场战争的方案。"},{"word":"warfare","ipa":"/ˈwɔːfeə/","tag":"first half only","definition":"The activity of fighting a war; it names the doing, and needs the second word before it becomes a plan.","definitionCN":"指进行战争的行为；它命名的是行动本身，要加上后一半才成为方案。"},{"word":"war","ipa":"/wɔː/","tag":"Frankish, not Latin","definition":"Armed conflict between states or groups, from Frankish *werra; it is not related to Latin bellum and not a synonym for strategy.","definitionCN":"指国家或群体之间的武装冲突，来自法兰克语 *werra；它与拉丁 bellum 无关，也不是 strategy 的同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"military strategy","ipa":"/ˈmɪlɪtəri ˈstrætədʒi/","tag":"wider umbrella","definition":"The standard term for planning armed conflict; warfare strategy is a near synonym that stresses the fighting itself.","definitionCN":"指筹划武装冲突的标准说法；warfare strategy 是强调交战本身的近义表达。"},{"word":"grand strategy","ipa":"/ɡrænd ˈstrætədʒi/","tag":"whole-of-state","definition":"A state's plan combining diplomacy, economy and force; the warfare part is only one strand of it.","definitionCN":"指国家把外交、经济与武力合为一体的计划；战争部分只是其中一股。"},{"word":"tactics","ipa":"/ˈtæktɪks/","tag":"lower level","definition":"The handling of forces in a single engagement; strategy decides where and why, tactics decides how.","definitionCN":"指单场交战中兵力的运用；战略决定在哪里打、为何打，战术决定怎么打。"},{"word":"doctrine","ipa":"/ˈdɒktrɪn/","tag":"settled guidance","definition":"Official teaching on how a force fights; it may serve a strategy but is not itself the war plan.","definitionCN":"指关于部队如何作战的官方教条；它可服务于战略，但本身不是战争方案。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Stratos 'army' plus agein 'lead' gives strategia 'generalship', so a warfare strategy is literally the leading of an army in war.","cn":"stratos「军队」加 agein「引导」得 strategia「将帅之才」，因此战争战略字面上就是在战争中率领一支军队。"},{"en":"The strategy family runs stratos, strategia, strategy, strategic, strategist, stratagem.","cn":"同根词依次是 stratos、strategia、strategy、strategic、strategist、stratagem。"},{"en":"The war half is Frankish *werra, and the -fare half is Old English faru 'journey'; the two are not war plus fare 'fee'.","cn":"战争一半是法兰克语 *werra，-fare 一半是古英语 faru「旅程」；两者不是 war 加 fare「费用」。"},{"en":"Collocations fix the scale: national warfare strategy, asymmetric warfare strategy, warfare strategy and tactics.","cn":"固定搭配标定层级：国家战争战略、非对称战争战略、战争战略与战术。"},{"en":"The pair splits war into levels: strategy above, tactics below, and the compound sits at the upper level.","cn":"这一组合把战争分为层级：战略在上，战术在下，而这个复合词位于上层。"}],"abstract":[{"en":"Picture a chess player moving one piece on a board the size of a country.","cn":"想象一名棋手在一块有整个国家那么大的棋盘上移动一枚棋子。"},{"en":"Picture a hand drawing one long arrow across a map and erasing all the short ones.","cn":"想象一只手在地图上画下一支长箭头，又把所有短箭头擦掉。"},{"en":"Picture two clocks on one wall, one counting the war's seasons and one counting the battle's minutes.","cn":"想象同一面墙上有两只钟，一只数战争的季节，一只数战斗的分钟。"}]},"examples":[{"en":"Few warfare strategies survive contact with an enemy that refuses to fight where expected.","cn":"很少有一套战争战略能在遇到拒绝在预料之处交战的敌人后仍然成立。"},{"en":"The archive keeps the minutes in which the wartime council argued over warfare strategy.","cn":"档案馆保存着战时委员会就战争战略争论的会议记录。"},{"en":"A blockade is often a warfare strategy chosen by the side that cannot win a land battle.","cn":"封锁常常是无法在陆战中取胜的一方所选的战争战略。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「war（打）+ fare（走）+ strategy（谋）」——先算清怎么走，再动手打 → 战争战略","word":"warfare strategy"},"root":"战争：war 经古北法语 werre 来自法兰克语 *werra「混乱、争斗」（重构形式，并非拉丁 bellum）；-fare 源自古英语 faru「旅程、队伍」，与 fare、farewell 同族，不是 war 加 fare「费用」。战略：希腊 stratēgia「将帅之才」< stratos「军队」+ agein「引导」，与 stratagem 同族，与拉丁 via、duct 无关。两半不同源。","sensesIntro":{"en":"Eight senses climb one ladder: from the whole direction of a war down to a single action plan, then across to asymmetry, the grand-strategic strand, business rivalry and finally a board game.","cn":"八个义项沿一架梯子展开：从战争全局指导，下到具体行动计划，再横向扩展到非对称、国家大战略中的一股、商业竞争，最后落到一盘棋。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand moves a single flag on a map, deciding where the whole army will go before any soldier moves.","cn":"核心意象：一只手在地图上移动一支旗，在任何士兵动身之前就决定整支军队的去向。"},"chain":["SET THE AIM","ALLOT THE MEANS","CHOOSE THE THEATRE","ORDER THE PHASES","OUTLAST THE ENEMY","CLOSE THE WAR"],"branches":[{"senses":"S1 · S2","en":"DIRECTION AND LINE: the same plan is both a whole-war design and a standing rule for commanders.","cn":"指导与方针：同一份方案既是对整场战争的设计，也是指挥官常设的行动准则。"},{"senses":"S3 · S4","en":"PLAN AND LEVEL: the design hardens into a timetable and marks the rung above tactics.","cn":"计划与层级：设计落实为时间表，并标记出高于战术的那一级。"},{"senses":"S5 · S6","en":"DISPARITY AND FRAME: a weaker side's plan and the military strand of a national plan share one name.","cn":"差距与框架：弱势一方的方案与国家计划中的军事部分共用同一个名称。"},{"senses":"S7","en":"MARKET FRONT: a firm borrows the map and the flags to plan a price war.","cn":"市场前线：企业借用地图与旗子来筹划一场价格战。"},{"senses":"S8","en":"BOARD AND TABLE: any contest of many moves repeats the shape in miniature.","cn":"棋盘与谈判桌：任何需要许多回合的较量都以缩小的规模重演这一结构。"}]},"affixes":{"intro":{"en":"The phrase is built from two unrelated halves: a Germanic war noun with a suffix of journeying, and a Greek noun of army leadership.","cn":"这个短语由两个互不相关的部分组成：一个带「行旅」后缀的日耳曼战争名词，和一个表示统帅军队的希腊名词。"},"latinIntro":{"en":"There are no Latin cognates to list here: the war half is Frankish and the strategy half is Greek, and neither descends from a Latin root.","cn":"这里没有可列的拉丁同族词：战争一半是法兰克语，战略一半是希腊语，两者都不出自拉丁词根。"},"items":[{"word":"war","structure":"war (English noun, from Old North French werre)","meaning":"armed conflict","meaningCN":"武装冲突；战争","example":"The noun names the state of fighting before any plan is made.","exampleCN":"这个名词指制定任何方案之前的交战状态。"},{"word":"-fare","structure":"-fare (English combining form, from Old English faru)","meaning":"a journey; a troop on the move","meaningCN":"旅程；行进中的队伍","example":"The old element survives in fare and farewell as well as in warfare.","exampleCN":"这个古老成分还留在 fare、farewell 以及 warfare 之中。"},{"word":"warfare","structure":"war + -fare","meaning":"the waging of war","meaningCN":"进行战争；作战","example":"The compound names the activity, not the plan.","exampleCN":"这个复合词命名的是行动本身，而不是方案。"},{"word":"stratos","structure":"stratos (Greek noun, second declension)","meaning":"army; host","meaningCN":"军队；队伍","example":"The army is the object that the general leads.","exampleCN":"军队正是将帅所率领的对象。"},{"word":"agein","structure":"agein (Greek verb)","meaning":"to lead, drive","meaningCN":"引导；驱赶","example":"The verb supplies the act of leading in the compound root.","exampleCN":"这个动词为复合词根提供了「率领」这一动作。"},{"word":"-ia","structure":"-ia (Greek noun suffix, abstract state or office)","meaning":"the art or office of","meaningCN":"……之术；……之职","example":"The suffix turns the act of leading into a named skill.","exampleCN":"这个后缀把率领的动作变成一种有名称的本领。"},{"word":"strategia","structure":"stratos + agein + -ia","meaning":"generalship","meaningCN":"将帅之才；统帅术","example":"The Greek noun names what a general does, not a document.","exampleCN":"这个希腊名词指将帅所做的事，而不是一份文书。"},{"word":"strategy","structure":"strategia through Latin and French","meaning":"the overall art of planning","meaningCN":"总体筹划的本领；战略","example":"The word widens from command in battle to planning in general.","exampleCN":"这个词从战场指挥扩展到一般意义上的筹划。"},{"word":"-ic","structure":"-ic (adjective suffix, from Greek -ikos)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix yields strategic from strategy.","exampleCN":"这个后缀由 strategy 造出 strategic。"},{"word":"-ist","structure":"-ist (agent suffix, from Greek -istēs)","meaning":"one who practices","meaningCN":"从事……的人","example":"The suffix yields strategist, a person who makes plans.","exampleCN":"这个后缀造出 strategist，即制定方案的人。"}],"latinEntries":[]}},{"word":"military campaign","ipa_uk":"/ˈmɪlɪtəri kæmˈpeɪn/","ipa_us":"/ˈmɪlɪtəri kæmˈpeɪn/","definition_zh":"军事战役；为达成明确目标而在一定战区连续实施的一系列作战行动","definition_en":"a connected series of military operations, fought over a period of time in one theatre, that pursues a defined objective","core_image":"指挥所地图上，一支粗箭头从滩头伸向内陆，旁边钉着一叠日历，每一页都画着一次推进","scene":"指挥所的地图上，一支粗箭头从滩头一路伸向内陆，旁边钉着一叠日历，每一页都画着一次推进。The general planned a military campaign that would end before the winter rains.","sceneCN":"这里 military campaign 指「为达成明确目标而在战区连续实施的一系列作战行动」（第 1 个义项：把多次交战串成有起止、有目标的整体）；句意为将军筹划了一场要在冬雨之前结束的军事战役。图中可辨识物件：指挥所地图、粗箭头、滩头标记、钉着的日历。","pos":[{"tag":"n.","zh":"军事战役；有明确目标的一连串作战行动（复合名词；复数作 military campaigns）"}],"collocations":[{"phrase":"launch a military campaign","zh":"发动军事战役"},{"phrase":"conduct a military campaign","zh":"实施军事战役"},{"phrase":"protracted military campaign","zh":"旷日持久的军事战役"},{"phrase":"joint military campaign","zh":"联合军事战役"},{"phrase":"aerial military campaign","zh":"空中军事战役"},{"phrase":"military campaign planning","zh":"军事战役筹划"},{"phrase":"a military campaign against the rebels","zh":"针对叛军的军事战役"}],"forms":[{"label":"复数","form":"military campaigns"},{"label":"核心形容词（军事的）","form":"military"},{"label":"核心名词（战役；运动）","form":"campaign"},{"label":"复数（战役）","form":"campaigns"},{"label":"现在分词（开展运动）","form":"campaigning"},{"label":"名词（运动参与者）","form":"campaigner"},{"label":"副词（军事上）","form":"militarily"}],"derivatives":[{"word":"military","pos":"adj./n.","zh":"军事的；军队（拉丁 militaris「士兵的」，由 miles「士兵」加 -aris 而来；miles 更深来源不确定）"},{"word":"militarily","pos":"adv.","zh":"以军事手段；在军事上（military 加 -ly，由形容词转为方式副词）"},{"word":"militarism","pos":"n.","zh":"军国主义（military 加 -ism，指把军事优先当作治国原则的意识形态）"},{"word":"militarize","pos":"v.","zh":"军事化（military 加 -ize，转为「使某物带上军事性质」）"},{"word":"campaign","pos":"n./v.","zh":"战役；运动（法语 campagne < 意大利 campagna「开阔田野」< 拉丁 campus「田野」，由「野外」转为「野外作战」，再转为「有组织的运动」）"},{"word":"campaigner","pos":"n.","zh":"运动参与者；竞选者（campaign 加 -er，指持续投入一场运动的人）"},{"word":"campus","pos":"n.","zh":"校园；田野（拉丁 campus「田野」，与 campaign 同源，后转指学校或机构的场地）"}],"senses":[{"no":"01","title":"A connected series of operations","titleCN":"为达成目标而连成一片的系列作战","definition":"several battles and supporting actions linked by one aim, one commander and one span of time","definitionCN":"由同一目标、同一指挥官与同一段时间串起来的多次交战与支援行动","example":"The spring military campaign opened with two river crossings.","exampleCN":"春季军事战役以两次渡河开始。","why":"Campaign came from 'open country', and armies that fought there called the whole season of manoeuvres by the name of the ground.","whyCN":"campaign 出自「开阔田野」，在那种地形作战的军队就把整季的机动都按这片地面来命名。"},{"no":"02","title":"A single operation with a defined objective","titleCN":"一次有明确目标的作战行动","definition":"one operation whose success is judged by taking a city, clearing a route or destroying a force","definitionCN":"以攻占城市、打通路线或消灭一支力量为成败标准的一次行动","example":"The military campaign had one objective: to cut the railway before winter.","exampleCN":"这场军事战役只有一个目标：在冬季到来之前切断铁路。","why":"An aim narrows the series into a single measurable task, and ordinary usage still calls that task a campaign.","whyCN":"目标把系列行动收窄为一项可衡量的任务，而日常用法仍把这项任务称为 campaign。"},{"no":"03","title":"A theatre-level joint operation","titleCN":"战区级联合作战","definition":"the coordinated work of land, sea and air forces inside one theatre under a single plan","definitionCN":"在同一战区、同一方案下由陆海空力量协同实施的行动","example":"The joint military campaign required the navy to hold the strait while the air force blinded the radar.","exampleCN":"这场联合军事战役要求海军守住海峡，同时空军使雷达失效。","why":"Modern commands fight one theatre as a whole, so the word covers the joint product rather than any single service's part.","whyCN":"现代指挥把整个战区当作一体来打，因此这个词涵盖联合作战的产物，而非某一军种的那一部分。"},{"no":"04","title":"A battle in the history books","titleCN":"史书中的一场战役","definition":"a named episode in military history, dated and mapped as a unit in a textbook or gallery","definitionCN":"军事史中一个有名称的片段，在教科书或展馆里被当作有年代、有地图的单位","example":"The museum's second hall is devoted to the military campaign of that autumn.","exampleCN":"博物馆的第二个展厅专门陈列那个秋天的军事战役。","why":"Once it is over and dated, a campaign becomes a chapter, and the word shifts from action to historical object.","whyCN":"一旦结束并被系上年代，一场战役就变成一章，词义也从行动转为历史对象。"},{"no":"05","title":"The planning stage of a campaign","titleCN":"战役筹划阶段","definition":"the staff work of aims, phases, logistics and timing before the first unit moves","definitionCN":"在第一支部队出动之前，对目标、阶段、后勤与时序所作的参谋工作","example":"The military campaign was won in the planning room long before the first shot.","exampleCN":"这场军事战役早在第一枪打响之前就已在作战室里赢下了。","why":"Planning is the campaign's brain, so the same word names the paper phase as well as the fighting.","whyCN":"筹划是战役的大脑，因此同一个词既指纸面阶段，也指实际交战。"},{"no":"06","title":"A long expeditionary war","titleCN":"长期远征式军事行动","definition":"a distant, prolonged operation sustained by supply lines and reinforcements rather than one decisive battle","definitionCN":"靠补给线与增援而非一场决战来维持的远距离持久行动","example":"A military campaign across the desert consumed more fuel than the fighting consumed ammunition.","exampleCN":"横越沙漠的军事战役消耗的燃料比交战消耗的弹药还多。","why":"Distance and duration make the campaign a way of life for an army, and the word grows to cover that whole stretch.","whyCN":"距离与时间使这场行动成为军队的一种生活方式，词义也随之覆盖整段过程。"},{"no":"07","title":"An air campaign","titleCN":"空袭战役","definition":"a sustained bombing or interdiction effort run as a campaign in its own right","definitionCN":"作为一场独立战役来实施的持续轰炸或阻断行动","example":"The military campaign in the air struck bridges for six weeks before the ground advance.","exampleCN":"空中军事战役在地面推进之前连续六周打击桥梁。","why":"Air power can now conduct its own connected series, so it borrows the word once reserved for armies.","whyCN":"空中力量如今能独自实施连成一片的系列行动，于是借用了原属陆军的这个词。"},{"no":"08","title":"A figurative organized push","titleCN":"比喻性的有组织攻坚行动","definition":"a journalistic use for a sustained drive by an institution to win a market, a vote or a reform","definitionCN":"新闻用法，指机构为赢得市场、选票或改革而持续发起的行动","example":"The bank's military campaign against fraud used the vocabulary of fronts and reserves.","exampleCN":"这家银行打击欺诈的军事战役借用了前线与预备队的词汇。","why":"The metaphor keeps the shape of linked actions under one aim, which is what any sustained institutional push has.","whyCN":"这个比喻保留了「同一目标下连成一片的行动」这一结构，而任何持续的组织攻坚都具有这种结构。"}],"etymology":{"intro":{"en":"The adjective comes from a Latin word for a soldier, while the noun comes from a Latin word for open field by way of Italian and French. Dates are approximate.","cn":"形容词来自拉丁语中表示士兵的词，名词则经意大利语与法语来自拉丁语中表示开阔田野的词。年代均为约数。"},"items":[{"era":"LATIN MILES","en":"Miles meant 'soldier'; its deeper origin is source uncertain, and no earlier root is reliably attested.","cn":"miles 意为「士兵」；其更深来源属来源不确定，没有可靠书证的更早词根。"},{"era":"LATIN MILITARIS","en":"Militaris, built with the adjectival ending -aris, meant 'of a soldier' and is the direct source of English military.","cn":"militaris 由形容词词尾 -aris 构成，意为「士兵的」，是英语 military 的直接来源。"},{"era":"LATIN CAMPUS","en":"Campus meant an open field or plain, the flat ground where armies could deploy.","cn":"campus 指开阔的田野或平原，即军队可以展开的平地。"},{"era":"ITALIAN CAMPAGNA","en":"Campagna named open country, and Italian soldiers applied it to a season of operations in the field.","cn":"campagna 指开阔乡野，意大利军人把它用于一季的野外作战。"},{"era":"FRENCH CAMPAGNE","en":"French borrowed campagne and passed it to English, where the military sense and the political sense grew side by side.","cn":"法语借入 campagne 再传入英语，军事义与政治运动义在此并行生长。"},{"era":"MODERN PHRASE","en":"English joined the adjective to the noun to name a connected operation; the exact first use is source uncertain and the dates are approximate.","cn":"英语把形容词与名词连起来指连成一片的作战；确切的最早书证属来源不确定，年代为约数。"}]},"similar":{"note":{"en":"Group one separates the two halves of the phrase from related words that share their roots but not their job; group two holds military actions of different scale.","cn":"第一组把这个短语的两半与同根但职能不同的词分开；第二组是规模不同的军事行动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"military","ipa":"/ˈmɪlɪtəri/","tag":"same first half, adjective","definition":"Of soldiers or armed forces; it describes the instrument, while the phrase names the operation.","definitionCN":"指士兵或武装部队的；它描述的是工具，而这个短语命名的是行动。"},{"word":"campaign","ipa":"/kæmˈpeɪn/","tag":"same second half","definition":"The operation itself or an organized public drive; the phrase pins it to warfare.","definitionCN":"指行动本身，也指有组织的公众运动；这个短语把它固定在军事上。"},{"word":"campus","ipa":"/ˈkæmpəs/","tag":"same Latin root, a place","definition":"From Latin campus 'field', now the grounds of a school or company; it shares a root but not a war.","definitionCN":"出自拉丁 campus「田野」，现指学校或公司的场地；同根但与战争无关。"},{"word":"camp","ipa":"/kæmp/","tag":"same field stock, a place to stay","definition":"A place where troops or travellers pitch tents; it is related through the field image, not the operation.","definitionCN":"指部队或旅人搭帐篷的地方；它通过「田野」意象相连，并非作战行动。"}]},{"heading":"NEAR MEANING","entries":[{"word":"operation","ipa":"/ˌɒpəˈreɪʃən/","tag":"one action","definition":"A single planned action within a campaign; several operations make the campaign.","definitionCN":"指一场战役中的单次计划行动；若干次行动才构成战役。"},{"word":"expedition","ipa":"/ɪkˈspedɪʃən/","tag":"distant mission","definition":"A journey undertaken for a purpose, often military; it stresses distance rather than the connected series.","definitionCN":"指为某一目的进行的远行，常为军事性质；它强调距离，而非系列行动。"},{"word":"offensive","ipa":"/əˈfensɪv/","tag":"attacking phase","definition":"The attacking part of a campaign; a campaign may include offensives and pauses.","definitionCN":"指战役中的进攻部分；一场战役可以包含进攻与停顿。"},{"word":"battle","ipa":"/ˈbætəl/","tag":"single engagement","definition":"One engagement between forces; a campaign contains several battles and the marches between them.","definitionCN":"指两支力量的一次交战；一场战役包含若干次战斗以及其间的行军。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Miles 'soldier' plus -aris gives militaris, the adjective behind military.","cn":"miles「士兵」加 -aris 得 militaris，即 military 背后的形容词。"},{"en":"Campus 'field' gives campagna 'open country', and a campaign is a season of fighting in the open.","cn":"campus「田野」得 campagna「开阔乡野」，而战役就是一季在野外的作战。"},{"en":"The campaign family runs campus, campagna, campagne, campaign, campaigner, campaigning.","cn":"同族词依次是 campus、campagna、campagne、campaign、campaigner、campaigning。"},{"en":"Collocations show the stages: launch a military campaign, conduct a military campaign, military campaign planning.","cn":"固定搭配显示阶段：发动军事战役、实施军事战役、军事战役筹划。"},{"en":"The phrase has two levels: a campaign is a series, a battle is one item in it.","cn":"这个短语有两个层级：战役是系列，战斗是其中一项。"}],"abstract":[{"en":"Picture one long arrow drawn across a map with many small dates pinned along it.","cn":"想象地图上画着一支长箭头，沿线钉着许多小日期。"},{"en":"Picture a farmer's field turned into a grid of tents and supply dumps.","cn":"想象一片农夫的田野被改成由帐篷与补给堆组成的网格。"},{"en":"Picture a relay race in which each runner must hand over before the next can start.","cn":"想象一场接力赛，每一棒都必须交接之后下一棒才能起跑。"}]},"examples":[{"en":"The military campaign stalled when the rains turned the roads into mud.","cn":"雨水把道路变成泥浆之后，这场军事战役停滞了。"},{"en":"Historians describe the military campaign as a series of missed chances.","cn":"历史学家把这场军事战役描述为一连串错失的机会。"},{"en":"Supply trucks, not tanks, decided the outcome of the military campaign.","cn":"决定这场军事战役结局的是补给卡车，而不是坦克。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「military（士兵的）+ campaign（田野里打仗）」——把许多场战斗连成一季的野外行动 → 军事战役","word":"military campaign"},"root":"军事：拉丁 militaris「士兵的」< miles「士兵」，miles 更深来源属来源不确定。战役：法语 campagne < 意大利 campagna「开阔田野」< 拉丁 campus「田野」；「战役」义由「在野外作战」引申，与 camp 同源。两半不同源。","sensesIntro":{"en":"Eight senses follow one connected operation: it is a series, then a single task, then a joint theatre, a dated chapter, a planning room, a long expedition, an air effort, and finally any organized institutional push.","cn":"八个义项沿同一场连贯行动展开：它先是系列，再是一项任务，继而成为联合战区、有年代的一章、作战室、长期远征、空中行动，最后是任何有组织的机构攻坚。"},"semanticMap":{"core":{"en":"CORE IMAGE: one long arrow crosses a map, and every date pinned along it belongs to the same push.","cn":"核心意象：一支长箭头横穿地图，沿箭头钉着的每一个日期都属于同一次推进。"},"chain":["CROSS THE BORDER","TAKE THE OBJECTIVE","LINK THE BATTLES","SUSTAIN THE LINES","PRESS THE THEATRE","END ON A DATE"],"branches":[{"senses":"S1 · S2","en":"SERIES AND TASK: the connected whole and the one measurable aim are the same word at two zoom levels.","cn":"系列与任务：连成的整体与那一项可衡量的目标，是同一个词在两个缩放层级上的样子。"},{"senses":"S3 · S4","en":"THEATRE AND CHAPTER: a joint operation in the field later hardens into a dated historical unit.","cn":"战区与章节：野外的联合作战后来凝固为有年代的历史单位。"},{"senses":"S5 · S6","en":"BRAIN AND DISTANCE: the planning room and the long expedition are the start and the stretch of one campaign.","cn":"大脑与距离：作战室与长期远征，是一场战役的起点与长度。"},{"senses":"S7","en":"AIR ARM: bombing can run its own connected series and so borrows the army's word.","cn":"空中一翼：轰炸能独自构成系列行动，于是借用了陆军的词。"},{"senses":"S8","en":"METAPHORICAL PUSH: any institution that links actions under one aim repeats the shape.","cn":"比喻攻坚：任何把行动串在同一目标下的机构，都在重演这一结构。"}]},"affixes":{"intro":{"en":"The phrase is two borrowed halves: a Latin adjective of soldiers and a Latin field noun that reached English through Italian and French.","cn":"这个短语由两个借来的部分组成：一个拉丁语的士兵形容词，和一个经意大利语与法语进入英语的拉丁语田野名词。"},"latinIntro":{"en":"Miles supplies the soldier half through militaris, and campus supplies the field half through campagna and campagne.","cn":"miles 经 militaris 提供「士兵」一半，campus 经 campagna 与 campagne 提供「田野」一半。"},"items":[{"word":"miles","structure":"miles, militis (Latin noun, third declension)","meaning":"soldier","meaningCN":"士兵","example":"The noun is the human unit behind the whole adjective family.","exampleCN":"这个名词是整个形容词词族背后的人之单位。"},{"word":"-aris","structure":"-aris (Latin adjective suffix)","meaning":"of or belonging to","meaningCN":"属于……的；与……有关的","example":"The suffix turns a soldier into an adjective of soldiers.","exampleCN":"这个后缀把「士兵」变成「士兵的」形容词。"},{"word":"militaris","structure":"miles + -aris","meaning":"of a soldier; military","meaningCN":"士兵的；军事的","example":"The adjective keeps the human reference of the noun.","exampleCN":"这个形容词保留了名词所指的人。"},{"word":"military","structure":"militaris through French militaire","meaning":"relating to armed forces","meaningCN":"与武装部队有关的","example":"English uses the word for both the institution and its adjective.","exampleCN":"英语把这个词既用于军队机构，也用作其形容词。"},{"word":"campus","structure":"campus, campi (Latin noun, second declension)","meaning":"open field, plain","meaningCN":"开阔田野；平原","example":"The flat ground is the place where a deployed army stands.","exampleCN":"这片平地就是展开的军队所站之处。"},{"word":"campagna","structure":"campagna (Italian noun, from Latin campus)","meaning":"open country","meaningCN":"开阔乡野","example":"Italian shifts the field word toward the countryside around a town.","exampleCN":"意大利语把这个田野词转向城镇周边的乡野。"},{"word":"campaign","structure":"campagne (French, from Italian campagna)","meaning":"a season of operations; an organized drive","meaningCN":"一季作战；有组织的运动","example":"The word moves from ground to season to organized effort.","exampleCN":"这个词从地面转到季节，再转到有组织的努力。"},{"word":"-er","structure":"-er (agent suffix)","meaning":"one who does","meaningCN":"做……的人","example":"The suffix yields campaigner from campaign.","exampleCN":"这个后缀由 campaign 造出 campaigner。"},{"word":"-ing","structure":"-ing (action noun suffix)","meaning":"the process of doing","meaningCN":"进行……的过程","example":"The suffix yields campaigning, the running of a campaign.","exampleCN":"这个后缀造出 campaigning，即开展一场运动的过程。"},{"word":"-ism","structure":"-ism (abstract noun suffix, from Greek)","meaning":"a system or doctrine","meaningCN":"一种制度或主义","example":"The suffix yields militarism, a doctrine of military priority.","exampleCN":"这个后缀造出 militarism，即军事优先的主义。"}],"latinEntries":[{"word":"miles","structure":"miles, militis (m., third declension)","meaning":"soldier","meaningCN":"士兵"},{"word":"militaris","structure":"militaris, militare (adjective, third declension)","meaning":"of a soldier, military","meaningCN":"士兵的；军事的"},{"word":"campus","structure":"campus, campi (m., second declension)","meaning":"open field, plain","meaningCN":"开阔田野；平原"},{"word":"campania","structure":"campania, campaniae (f., first declension)","meaning":"open country, level land","meaningCN":"开阔乡野；平地"}]}},{"word":"battlefield","ipa_uk":"/ˈbætəlfiːld/","ipa_us":"/ˈbætəlfiːld/","definition_zh":"战场；两军交战的地面；引申为任何斗争发生的领域","definition_en":"the ground on which a battle is fought, and by extension any area or sphere where a struggle takes place","core_image":"被车辙压出深沟的田野，断栅与散落的盔甲之间，远处两面破旗还立着","scene":"清晨的田野上留着深深的车辙与断栅，散落的盔甲被露水打湿，远处两面破旗仍插在土里。The battlefield lay silent after the last regiment withdrew.","sceneCN":"这里 battlefield 指「两军实际交战的那片地面」（第 1 个义项：战斗发生的地点本身）；句意为最后一支团撤退之后，战场一片寂静。图中可辨识物件：车辙、断栅、散落盔甲、远处两面破旗。","pos":[{"tag":"n.","zh":"战场；交战地带；斗争领域（可数；复数 battlefields）"}],"collocations":[{"phrase":"on the battlefield","zh":"在战场上"},{"phrase":"leave the battlefield","zh":"离开战场"},{"phrase":"return to the battlefield","zh":"重返战场"},{"phrase":"battlefield medicine","zh":"战地医疗"},{"phrase":"battlefield commander","zh":"战场指挥官"},{"phrase":"the battlefield of ideas","zh":"思想战场"},{"phrase":"battlefield conditions","zh":"战场环境"}],"forms":[{"label":"复数","form":"battlefields"},{"label":"核心名词（战斗）","form":"battle"},{"label":"复数（战斗）","form":"battles"},{"label":"核心名词（田野；领域）","form":"field"},{"label":"复数（田野；领域）","form":"fields"},{"label":"复合词（战场；争夺之地）","form":"battleground"},{"label":"复合词（战地医院）","form":"field hospital"}],"derivatives":[{"word":"battle","pos":"n./v.","zh":"战斗；搏斗（古法语 bataille < 拉丁 battualia「士兵的击打练习」< battuere「击打」，battuere 更深来源不确定）"},{"word":"battleground","pos":"n.","zh":"战场；争夺之地（battle 加 ground，由「战斗」转为「战斗发生的地面」）"},{"word":"battalion","pos":"n.","zh":"营；作战单位（法语 bataillon < 意大利 battaglione，与 battaglia「战斗」同族，由「战斗」转为「战斗编制」）"},{"word":"field","pos":"n./v.","zh":"田野；领域；实地（古英语 feld「开阔地」，由「开阔地」转为「活动领域」）"},{"word":"fielder","pos":"n.","zh":"守场员（field 加 -er，指在场上负责某一区域的人）"},{"word":"fielding","pos":"n.","zh":"守备；实地操作（field 加 -ing，指在场上或实地进行的过程）"}],"senses":[{"no":"01","title":"The ground of a battle","titleCN":"战斗发生的那片地面","definition":"the actual piece of ground on which opposing forces meet and fight","definitionCN":"敌对双方相遇并交战的真实地面","example":"The battlefield lay silent after the last regiment withdrew.","exampleCN":"最后一支团撤退之后，战场一片寂静。","why":"Battle names the fighting and field names the open ground, so the compound is simply the ground where the fighting happens.","whyCN":"battle 指战斗，field 指开阔地面，因此这个复合词就是战斗发生的那片地面。"},{"no":"02","title":"The wider zone of combat","titleCN":"更广的交战地带","definition":"the larger area around the fighting, including approaches, reserves and rear positions","definitionCN":"战斗周边更大的区域，包括接近路线、预备队与后方阵地","example":"The whole valley became a battlefield once the artillery found the range.","exampleCN":"炮兵测准距离之后，整条山谷都成了战场。","why":"A battle spreads outward through artillery and movement, so the word expands from the meeting point to the whole contested zone.","whyCN":"战斗会通过炮火与机动向外扩散，因此这个词从相遇点扩展到整片争夺地带。"},{"no":"03","title":"The scene after the fighting","titleCN":"战斗结束后的现场","definition":"the field as it is found afterwards, marked by wreckage, graves and abandoned equipment","definitionCN":"战后被人看到的场地，遍布残骸、坟墓与丢弃的装备","example":"Photographers walked the battlefield at dawn, counting the wrecked guns.","exampleCN":"摄影师在黎明时走过战场，清点被毁的火炮。","why":"Once the noise stops, the ground becomes a scene to be inspected, and the same word names that aftermath.","whyCN":"枪炮声停止之后，这片地面变成可供查看的现场，同一个词就指这种战后景象。"},{"no":"04","title":"A figurative arena of struggle","titleCN":"比喻性的斗争领域","definition":"any sphere in which rivals contend, such as politics, science or the market","definitionCN":"竞争对手相争的任何领域，如政治、科学或市场","example":"The courtroom became the battlefield for two rival laboratories.","exampleCN":"法庭成了两家竞争实验室的战场。","why":"The metaphor keeps the essentials of the literal scene: two sides, a contested space and a result that is won or lost.","whyCN":"这个比喻保留了字面场景的核心：两方、一片争夺的空间，以及一个分出胜负的结果。"},{"no":"05","title":"The electronic or cyber battlefield","titleCN":"电子与网络战场","definition":"the digital domain in which networks, signals and data are attacked and defended","definitionCN":"对网络、信号与数据进行攻防的数字领域","example":"Engineers now map the cyber battlefield as carefully as any hill.","exampleCN":"工程师如今像测绘任何一座山丘那样仔细地测绘网络战场。","why":"New domains inherit old words because the shape of attack, defence and terrain remains the same without soil.","whyCN":"新领域会继承旧词，因为攻防与地形的结构在没有土壤时仍然相同。"},{"no":"06","title":"The negotiating table as a battlefield","titleCN":"作为战场的谈判桌","definition":"a rhetorical use for a negotiation in which each concession is treated as ground gained or lost","definitionCN":"修辞用法，指把每一次让步都视为得失地盘的谈判","example":"Both delegations treated the treaty talks as a battlefield of paragraphs.","exampleCN":"两个代表团把条约谈判当成逐段争夺的战场。","why":"Negotiation has fronts, trenches and withdrawals in miniature, so speakers borrow the field to describe them.","whyCN":"谈判以缩小的规模拥有前线、战壕与撤退，因此说话者借这片场地来描写它。"},{"no":"07","title":"A historic site and memorial","titleCN":"作为历史遗址与纪念地","definition":"a preserved field visited for its monuments, graves and guided tours rather than for fighting","definitionCN":"因纪念碑、墓地与导览而被参观的保存场地，而非用于作战","example":"The old battlefield is now a park with a visitors' centre.","exampleCN":"这片旧战场如今是一座设有游客中心的公园。","why":"When the fighting is long past, the ground survives as a place of memory, and the word follows it into heritage.","whyCN":"战斗久远之后，这片地面作为记忆之地留存下来，词义也随之进入遗产领域。"},{"no":"08","title":"The front line of hospitals or disasters","titleCN":"医院或灾难中的前线比喻","definition":"a journalistic use for the place where medical staff or rescue workers face the heaviest pressure","definitionCN":"新闻用法，指医护人员或救援人员承受最大压力的地方","example":"The emergency ward was the battlefield of the night shift.","exampleCN":"急诊病房是夜班的前线战场。","why":"The word transfers wherever people hold a line under pressure, and a ward or a flood zone has exactly that line.","whyCN":"只要人们顶着压力守住一条线，这个词就能迁移过去，而病房或洪区正有这样一条线。"}],"etymology":{"intro":{"en":"The compound joins a Latin-derived word for fighting to an Old English word for open land; the two halves are unrelated. Dates are approximate.","cn":"这个复合词把一个源自拉丁语的「打斗」词与一个古英语的「开阔地」词连在一起，两半互不同源。年代均为约数。"},"items":[{"era":"LATIN BATTUERE","en":"Battuere meant 'to beat, strike'; its deeper origin is source uncertain, and no earlier root is reliably attested.","cn":"battuere 意为「击打、敲打」；其更深来源属来源不确定，没有可靠书证的更早词根。"},{"era":"LATIN BATTUALIA","en":"Battualia named the striking exercises of soldiers, and from that practice the word came to mean a fight.","cn":"battualia 指士兵的击打演练，由这种练习引申为一场打斗。"},{"era":"OLD FRENCH BATAILLE","en":"Old French bataille carried the sense of a battle into English, where it named the engagement itself.","cn":"古法语 bataille 把「战斗」的含义带入英语，指交战本身。"},{"era":"OLD ENGLISH FELD","en":"Feld meant open land, a wide flat stretch, and it is the source of the field half of the compound.","cn":"feld 指开阔地、大片平地，是这个复合词中 field 一半的来源。"},{"era":"MIDDLE ENGLISH COMPOUND","en":"English joined battle and field into one noun for the ground of an engagement, and the compound has kept that literal core.","cn":"英语把 battle 与 field 合成一个指交战地面的名词，这个复合词一直保留这一字面核心。"},{"era":"UNCERTAIN SOURCE","en":"Source uncertain: the exact first written use of the compound is not recorded, and the deeper origin of battuere is a matter of reconstruction rather than attested fact.","cn":"来源不确定：这个复合词确切的最早书证没有记载，battuere 的更深来源属于重构而非有书证的事实。"}]},"similar":{"note":{"en":"Group one separates the two halves and the near-doublet from the compound; group two holds terms for the spaces where fighting is organized.","cn":"第一组把这个复合词的两半及近义双式词分开；第二组是用于组织作战的空间名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"battle","ipa":"/ˈbætəl/","tag":"same first half","definition":"A single engagement between armed forces; the field is only the place where it happens.","definitionCN":"指武装力量之间的一次交战；field 只是它发生的地点。"},{"word":"field","ipa":"/fiːld/","tag":"same second half","definition":"Open land or a sphere of activity; it need not be contested at all.","definitionCN":"指开阔地或活动领域；它完全不必是被争夺的。"},{"word":"battleground","ipa":"/ˈbætəlɡraʊnd/","tag":"near-doublet, more figurative","definition":"Essentially the same ground as battlefield, but it is the more common choice in political and commercial metaphors.","definitionCN":"本质上与 battlefield 指同一片地面，但在政治与商业比喻中更常用。"},{"word":"battalion","ipa":"/bəˈtæljən/","tag":"same battle family, a unit","definition":"A military unit, from the same Italian battle family; it is an organization of soldiers, not a place.","definitionCN":"指一个军事单位，同出意大利语「战斗」词族；它是士兵的编制，不是地点。"}]},{"heading":"NEAR MEANING","entries":[{"word":"theatre","ipa":"/ˈθɪətə/","tag":"area of operations","definition":"The whole geographic area in which a war is conducted; a battlefield is one small part of it.","definitionCN":"指进行一场战争的整个地理区域；battlefield 只是其中很小的一部分。"},{"word":"front","ipa":"/frʌnt/","tag":"line of contact","definition":"The moving line where opposing forces meet; it is a boundary, while a battlefield is an area.","definitionCN":"指敌对力量相遇的移动界线；它是一条线，而 battlefield 是一片区域。"},{"word":"war zone","ipa":"/ˈwɔː zəʊn/","tag":"legal and civilian","definition":"An area officially designated as dangerous because of fighting; the term is administrative as much as military.","definitionCN":"指因交战而被正式划为危险的区域；这个词既是军事用语，也是行政用语。"},{"word":"arena","ipa":"/əˈriːnə/","tag":"figurative contest","definition":"A place or sphere of contest, from Latin arena 'sand'; it matches the figurative battlefield, not the literal one.","definitionCN":"指较量之处或领域，出自拉丁 arena「沙」；它对应比喻性的 battlefield，而非字面战场。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Battle plus field is transparent: the fighting plus the open ground it happens on.","cn":"battle 加 field 结构透明：战斗加上它发生的开阔地面。"},{"en":"The battle family runs battuere, battualia, bataille, battle, battalion, battleground.","cn":"同族词依次是 battuere、battualia、bataille、battle、battalion、battleground。"},{"en":"The field half is Old English feld 'open land', the same word that survives in field and fielder.","cn":"field 一半是古英语 feld「开阔地」，同一词还留在 field 与 fielder 中。"},{"en":"Collocations mark the literal and the figurative: on the battlefield, battlefield medicine, the battlefield of ideas.","cn":"固定搭配标出字面与比喻：在战场上、战地医疗、思想战场。"},{"en":"Two halves, two origins: battle is Latin through French, field is Old English, and they only met in English.","cn":"两半两个来源：battle 经法语来自拉丁语，field 是古英语，二者只在英语中相遇。"}],"abstract":[{"en":"Picture a ploughed field cut by a single deep line of wheel ruts.","cn":"想象一片耕过的田野被一道深深的车辙切开。"},{"en":"Picture two broken flags leaning toward each other across empty ground.","cn":"想象两面破旗隔着空地相互倾斜。"},{"en":"Picture a chessboard where every square is a hill that someone must take.","cn":"想象一张棋盘，每一格都是必须有人攻占的山丘。"}]},"examples":[{"en":"Medics carried the wounded off the battlefield under fire.","cn":"医护兵在炮火下把伤员抬离战场。"},{"en":"The novel turns the family kitchen into a battlefield of small quarrels.","cn":"这部小说把家里的厨房变成小争吵的战场。"},{"en":"Researchers treat the deep sea as the next battlefield for mining rights.","cn":"研究者把深海视为采矿权争夺的下一个战场。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「battle（打）+ field（地）」——打起来的那片地 → 战场","word":"battlefield"},"root":"战斗：battle < 古法语 bataille < 拉丁 battualia「士兵的击打练习」< battuere「击打」，battuere 更深来源属来源不确定。地面：field < 古英语 feld「开阔地」。两半不同源，只在英语中合为复合词。","sensesIntro":{"en":"Eight senses spread from one field: the ground of the fight widens into a zone, becomes an aftermath, then serves as a metaphor for any contest, a cyber domain, a negotiating table, a heritage site and finally a hospital front line.","cn":"八个义项从同一片地面铺开：交战的地面扩成地带，变成战后现场，再被借作任何较量的比喻、网络领域、谈判桌、历史遗址，最后是医院前线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rutted field where two sides met, still carrying the marks of the encounter.","cn":"核心意象：一片布满车辙的田野，两方曾在此相遇，地上仍留着交手的痕迹。"},"chain":["MEET ON OPEN GROUND","FIGHT FOR THE SPACE","MARK THE GROUND","LEAVE THE FIELD","KEEP THE MEMORY","EXTEND THE METAPHOR"],"branches":[{"senses":"S1 · S2","en":"POINT AND ZONE: the meeting ground and the wider contested area are the same field at two scales.","cn":"交点与地带：相遇的地面与更广的争夺区域，是同一片场地在两种尺度上的样子。"},{"senses":"S3 · S4","en":"AFTERMATH AND METAPHOR: what is found afterwards becomes the image for any struggle elsewhere.","cn":"现场与比喻：战后所见的景象，变成别处任何斗争的形象。"},{"senses":"S5 · S6","en":"NEW DOMAINS: networks and negotiating tables inherit the field because attack and defence keep their shape.","cn":"新领域：网络与谈判桌继承了这片场地，因为攻与守的结构不变。"},{"senses":"S7","en":"HERITAGE: the fighting ends, and the ground survives as a place to visit and remember.","cn":"遗产：战斗结束，这片地面作为可参观、可记忆之处留存下来。"},{"senses":"S8","en":"FRONT LINE: wards and flood zones repeat the literal line under pressure.","cn":"前线：病房与洪区在压力下重演了那条字面意义的线。"}]},"affixes":{"intro":{"en":"The compound is made of two unrelated pieces: a Latin-derived battle word and an Old English field word.","cn":"这个复合词由两个互不相关的部分组成：一个源自拉丁语的「战斗」词，和一个古英语的「田野」词。"},"latinIntro":{"en":"Battuere and battualia are the attested Latin ancestors of battle; field has no Latin ancestor and comes from Old English.","cn":"battuere 与 battualia 是 battle 有书证的拉丁祖先；field 没有拉丁祖先，来自古英语。"},"items":[{"word":"battuere","structure":"battuere, battui, battutum (Latin verb, third conjugation)","meaning":"to beat, strike","meaningCN":"击打；敲打","example":"The verb supplies the physical blow behind the whole family.","exampleCN":"这个动词为整族词提供了物理上的击打动作。"},{"word":"battualia","structure":"battualia, battualium (Latin noun, neuter plural)","meaning":"striking exercises, fighting practice","meaningCN":"击打演练；搏斗练习","example":"The practice ground turns into the word for a fight.","exampleCN":"练习的场地转为表示一场打斗的词。"},{"word":"bataille","structure":"bataille (Old French noun, from Latin battualia)","meaning":"battle","meaningCN":"战斗；战役","example":"Old French carries the Latin word into English.","exampleCN":"古法语把这个拉丁词带入英语。"},{"word":"battle","structure":"battle (English noun, from Old French bataille)","meaning":"a fight between armed forces","meaningCN":"武装力量之间的战斗","example":"The noun names the event, not the place.","exampleCN":"这个名词命名的是事件，而不是地点。"},{"word":"feld","structure":"feld (Old English noun)","meaning":"open land, plain","meaningCN":"开阔地；平原","example":"The Old English word names wide ground with no trees.","exampleCN":"这个古英语词指没有树木的宽阔地面。"},{"word":"field","structure":"field (English noun, from Old English feld)","meaning":"open ground; an area of activity","meaningCN":"开阔地；活动领域","example":"The word widens from soil to any sphere of work.","exampleCN":"这个词从土地扩展到任何工作领域。"},{"word":"battlefield","structure":"battle + field","meaning":"the ground of a battle","meaningCN":"战斗发生的地面","example":"The compound is literal before it is metaphorical.","exampleCN":"这个复合词先有字面义，后有比喻义。"},{"word":"battleground","structure":"battle + ground","meaning":"ground fought over","meaningCN":"被争夺的地面","example":"The variant swaps the field word for a more general ground word.","exampleCN":"这个变体把 field 换成更一般的 ground。"},{"word":"-er","structure":"-er (agent suffix)","meaning":"one who does","meaningCN":"做……的人","example":"The suffix yields fielder from field.","exampleCN":"这个后缀由 field 造出 fielder。"},{"word":"-ing","structure":"-ing (action noun suffix)","meaning":"the process of doing","meaningCN":"进行……的过程","example":"The suffix yields fielding, work done in the field.","exampleCN":"这个后缀造出 fielding，即在场地上进行的工作。"}],"latinEntries":[{"word":"battuere","structure":"battuere, battui, battutum (verb, third conjugation)","meaning":"to beat, strike","meaningCN":"击打；敲打"},{"word":"battualia","structure":"battualia, battualium (n., neuter plural, third declension)","meaning":"fighting exercises, combat practice","meaningCN":"搏击演练；战斗练习"}]}}]);
